import { parseCssColor, warnRejectedColor } from "./css-color";
import { parseBlendMode } from "./blend-mode";
import { clampFilterChannel, clampSymmetricChannel } from "./filter-clamp";

export interface InnerShadow {
  color: string;
  x: number;
  y: number;
  blur: number;
  blendMode?: string;
}

/** CSS shadow declarations shared by every visual primitive.
 *
 * Figma effects are attached to the source node, not to a particular LSML
 * primitive. Keeping the validation and lowering here prevents image, text,
 * and SVG shape nodes from silently dropping the same `shadow[]` field that
 * frames already honour.
 */
export function buildShadowCss(
  value: unknown,
  nodeId?: string,
  field = "shadow.color",
): { filter?: string; boxShadow?: string; outerBoxShadow?: string; innerShadows?: InnerShadow[] } {
  if (!Array.isArray(value) || value.length === 0) return {};
  const dropParts: string[] = [];
  const boxParts: string[] = [];
  const outerBoxParts: string[] = [];
  const innerShadows: InnerShadow[] = [];
  for (const entry of value) {
    if (typeof entry !== "object" || entry === null) continue;
    const spec = entry as {
      inset?: unknown;
      color?: unknown;
      x?: unknown;
      y?: unknown;
      blur?: unknown;
      spread?: unknown;
      blendMode?: unknown;
    };
    const color = typeof spec.color === "string" ? parseCssColor(spec.color) : null;
    if (color === null) {
      warnRejectedColor(field, nodeId);
      continue;
    }
    const x = clampSymmetricChannel("shadowOffset", numberOr(spec.x, 0)) ?? 0;
    const y = clampSymmetricChannel("shadowOffset", numberOr(spec.y, 0)) ?? 0;
    const blur = clampFilterChannel("blur", numberOr(spec.blur, 0)) ?? 0;
    const spread = clampSymmetricChannel("shadowSpread", numberOr(spec.spread, 0)) ?? 0;
    const inset = spec.inset === true;
    if (!inset && spread === 0) {
      // CSS drop-shadow's blur radius is a Gaussian sigma, whereas the
      // Figma/box-shadow channel is the visual blur diameter.
      dropParts.push(`drop-shadow(${x}px ${y}px ${blur / 2}px ${color})`);
    } else {
      const declaration = `${inset ? "inset " : ""}${x}px ${y}px ${blur}px ${spread}px ${color}`;
      boxParts.push(declaration);
      if (!inset) outerBoxParts.push(declaration);
      else {
        const blendMode = parseBlendMode(spec.blendMode);
        innerShadows.push({
          color,
          x,
          y,
          blur,
          ...(blendMode === undefined ? {} : { blendMode }),
        });
      }
    }
  }
  return {
    ...(dropParts.length > 0 ? { filter: dropParts.join(" ") } : {}),
    ...(boxParts.length > 0 ? { boxShadow: boxParts.join(", ") } : {}),
    ...(outerBoxParts.length > 0 ? { outerBoxShadow: outerBoxParts.join(", ") } : {}),
    ...(innerShadows.length > 0 ? { innerShadows } : {}),
  };
}

function numberOr(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}
