// Recursive tree renderer — resolves bindings, dispatches to
// primitives, handles `repeat` specially.

import type { Signal } from "@preact/signals-react";
import { useSignals } from "@preact/signals-react/runtime";
import { motion } from "framer-motion";
import { memo, useMemo, type CSSProperties, type ReactNode } from "react";
import type { Store } from "../state/store";
import type { Transition } from "../animate/transitions";
import { PRIMITIVES } from "./primitives";
import { PathScopeProvider, scopedPath, usePathScope } from "./scope";
import type { RenderNode } from "./bundle";
import {
  UniversalWrapper,
  buildLayerBlurFilter,
  type SizingMode,
  type UniversalProps,
} from "./universal-wrapper";
import { KeyframePlayer } from "./keyframe-player";
import { StaggerContext, computeStaggerDelayMs } from "./stagger-context";
import { useBindAnimate, type BindAnimateHandle } from "./bind-animate";
import { checkNodeProps } from "./prop-allowlist";
import { emitDiagnostic } from "./diagnostics";
import { buildMask, parseMaskSpec, MASK_FEATHER_PAD } from "./mask";
import { parseBlendMode } from "./blend-mode";
import { useAllowedHosts, useHostAssetPolicy } from "./allowed-hosts";
import { useShapeIndex } from "./shape-index";
import {
  buildMaskCoverageFromShape,
  buildMaskCoverageFromGroup,
  coverageIsFeathered,
  GROUP_MASK_MAX_DEPTH,
  simpleRoundedRectMaskRadius,
} from "./shape-geometry";

export interface TreeProps {
  node: RenderNode;
  store: Store;
  /**
   * A masked parent may split its direct children into blend runs.  The run
   * owns the child blend outside its mask, so the child must not apply the
   * same blend a second time inside the mask's isolated stacking context.
   */
  suppressBlendMode?: boolean;
  /**
   * A shape below a stroke-only vector mask keeps its layer blur on the
   * vector paint before that mask is evaluated.  This is a structural
   * composition flag, inherited through the masked subtree; it is never
   * bundle- or scene-specific.
   */
  renderBlurInsideShape?: boolean;
}

const STATIC_BIND_ANIMATE: BindAnimateHandle = {
  motionStyle: null,
  motionRef: null,
  colorProps: {},
};

const EMPTY_BINDING_ENTRIES: readonly (readonly [string, string])[] = [];
const EMPTY_BINDING_PATHS: readonly string[] = [];
const EMPTY_BINDING_SIGNALS: readonly Signal<unknown>[] = [];
const EMPTY_BINDING_VALUES: readonly unknown[] = [];
type TransitionBinding = readonly [string, Signal<Transition | undefined>];
const EMPTY_TRANSITION_BINDINGS: readonly TransitionBinding[] = [];
const TRANSITION_BINDING_KEYS: Partial<Record<RenderNode["kind"], ReadonlySet<string>>> = {
  frame: new Set(["opacity", "scale", "rotate", "x", "y"]),
  image: new Set(["opacity", "src"]),
  shape: new Set(["opacity"]),
  text: new Set(["opacity", "value"]),
};
const bindingEntriesByNode = new WeakMap<RenderNode, readonly (readonly [string, string])[]>();
const groupMaskHasBoundImages = new WeakMap<RenderNode, boolean>();

function getBindingEntries(node: RenderNode): readonly (readonly [string, string])[] {
  if (node.bindings == null) return EMPTY_BINDING_ENTRIES;

  const cached = bindingEntriesByNode.get(node);
  if (cached) return cached;

  // RenderNode trees are immutable after bundle ingestion. Cache the small
  // binding-key topology once, so live values can update without repeatedly
  // enumerating the same record in resolution, transitions, and static checks.
  const entries = Object.entries(node.bindings);
  bindingEntriesByNode.set(node, entries);
  return entries;
}

/**
 * Group-mask coverage only resolves live props for image children, and only
 * through the same depth-bounded path used by collectCoverage. Such a source
 * must stay on the uncached path so src/opacity/etc. remain signal-reactive.
 * RenderNode topology and binding keys are immutable after ingestion, so this
 * structural check is safe to memoize by source node.
 */
function groupMaskHasLiveImage(group: RenderNode): boolean {
  const cached = groupMaskHasBoundImages.get(group);
  if (cached !== undefined) return cached;

  const visit = (frame: RenderNode, depth: number): boolean => {
    for (const child of frame.children ?? []) {
      if (child.props?.visible === false) continue;
      if (child.kind === "image" && getBindingEntries(child).length > 0) return true;
      if (child.kind === "frame" && depth > 0 && visit(child, depth - 1)) return true;
    }
    return false;
  };

  const hasLiveImage = group.kind === "frame" && visit(group, GROUP_MASK_MAX_DEPTH);
  groupMaskHasBoundImages.set(group, hasLiveImage);
  return hasLiveImage;
}

function canRenderStaticPrimitive(node: RenderNode): boolean {
  return (
    getBindingEntries(node).length === 0 &&
    Object.keys(node.animateBindings ?? {}).length === 0 &&
    Object.keys(node.transitions ?? {}).length === 0 &&
    Object.keys(node.animate_initial ?? {}).length === 0 &&
    !node.keyframes
  );
}

function TreeComponent({
  node,
  store,
  suppressBlendMode,
  renderBlurInsideShape,
}: TreeProps): ReactNode {
  if (node.kind === "repeat") {
    return <Repeat node={node} store={store} />;
  }
  // The bundle's channel set is immutable. Keep the hook-heavy motion path
  // only for nodes that can actually receive bindAnimate retargets.
  const Component =
    node.animateBindings && Object.keys(node.animateBindings).length > 0 ? AnimatedNode : Node;
  return (
    <Component
      node={node}
      store={store}
      suppressBlendMode={suppressBlendMode}
      renderBlurInsideShape={renderBlurInsideShape}
    />
  );
}

/**
 * Parent signal updates rebuild child elements, but the bundle tree is immutable.
 * Shallow memoization keeps unchanged branches out of the render path; each
 * Node/Repeat still subscribes to its own signals and context values.
 */
export const Tree = memo(TreeComponent);
Tree.displayName = "Tree";

function AnimatedNode(props: TreeProps): ReactNode {
  const scope = usePathScope();
  const bindAnimate = useBindAnimate(props.node, props.store, scope);
  return <Node {...props} bindAnimate={bindAnimate} />;
}

function Node({
  node,
  store,
  suppressBlendMode = false,
  renderBlurInsideShape = false,
  bindAnimate = STATIC_BIND_ANIMATE,
}: TreeProps & { bindAnimate?: BindAnimateHandle }): ReactNode {
  // useSignals() lets the surrounding component subscribe to any
  // signal read during render. Each leaf path has its own signal so
  // re-renders only fire on touched paths.
  useSignals();
  const scope = usePathScope();
  // ADR 002 §3.2 (#E) — the bundle's host allowlist, for gating an image
  // mask source (T1/T2). `undefined` = deny every remote host.
  const allowedHosts = useAllowedHosts();
  const isHostAssetUrl = useHostAssetPolicy();
  // ADR 002 A2.1 (#K) — the bundle-wide `id → shape` index, for resolving a
  // `mask.source.kind:"shape"` ref to inlined coverage geometry.
  const shapeIndex = useShapeIndex();
  const bindings = getBindingEntries(node);
  // Repeat scopes and bundle binding keys stay stable for this mounted node.
  // Resolve their full store paths once instead of rebuilding scoped strings
  // on every signal-driven render (including a second time for transitions).
  const bindingPaths = useMemo(
    () =>
      bindings.length === 0
        ? EMPTY_BINDING_PATHS
        : bindings.map(([, path]) => scopedPath(scope, path)),
    [bindings, scope],
  );
  // Store signals are stable per path. Keep their references beside the
  // memoized paths so ordinary live renders read `.value` directly instead
  // of repeating a store Map lookup for every bound property.
  const bindingSignals = useMemo(
    () =>
      bindingPaths.length === 0
        ? EMPTY_BINDING_SIGNALS
        : bindingPaths.map((path) => store.signal(path)),
    [bindingPaths, store],
  );
  const bindingValues = readBindingValues(bindingSignals);

  const transitionBindings = useMemo(() => {
    const keys = TRANSITION_BINDING_KEYS[node.kind];
    if (keys === undefined) return EMPTY_TRANSITION_BINDINGS;

    const result: TransitionBinding[] = [];
    for (let index = 0; index < bindings.length; index += 1) {
      const key = bindings[index][0];
      if (keys.has(key)) result.push([key, store.transitionSignal(bindingPaths[index])]);
    }
    return result.length === 0 ? EMPTY_TRANSITION_BINDINGS : result;
  }, [bindings, bindingPaths, node.kind, store]);

  // Hooks must run unconditionally within this component — the early-return
  // for unknown kinds happens *after* every hook has fired.
  const resolved = useMemo(
    () => resolvePropsFromValues(node, bindings, bindingValues),
    // Signal reads above subscribe this node and become the memo dependencies.
    // Reuse their values here rather than looking up every signal a second time.
    [node, bindings, bindingPaths, ...bindingValues],
  );

  // Child position is structural: childIsAbsolute reads only immutable node
  // kinds, static props and binding-key presence. Avoid rescanning the full
  // bundle child list on every parent signal update.
  const hasAbsoluteChild = useMemo(
    () => node.children?.some(childIsAbsolute) ?? false,
    [node.children],
  );

  // ADR 001 §3.4 (issue #34) — audit static props + binding keys
  // against the primitive's allowlist ; unknown props diagnose instead
  // of dropping silently. Key sets are static per node (a live delta
  // can only change values), so the check is once-per-node.
  checkNodeProps(node);

  const Primitive = PRIMITIVES[node.kind as keyof typeof PRIMITIVES];
  if (!Primitive) {
    emitDiagnostic(node.id, "kind", "unknown render kind ; node not rendered");
    return null;
  }

  const maskSpec = resolved.mask !== undefined ? parseMaskSpec(resolved.mask, node.id) : null;
  const groupMaskRef =
    maskSpec?.source.kind === "group" && /^[A-Za-z0-9_:-]+$/.test(maskSpec.source.ref)
      ? maskSpec.source.ref
      : undefined;
  const groupMaskSource = groupMaskRef === undefined ? undefined : shapeIndex.get(groupMaskRef);
  const cachedGroupMaskAnalysis = useMemo(() => {
    if (groupMaskSource?.kind !== "frame") return undefined;
    const feather = coverageIsFeathered(groupMaskSource, GROUP_MASK_MAX_DEPTH, false);
    return {
      feather,
      simpleRoundedMaskRadius:
        !feather && maskSpec?.type === "alpha" && maskSpec.op === "intersect"
          ? simpleRoundedRectMaskRadius(groupMaskSource)
          : null,
    };
  }, [groupMaskSource, maskSpec?.type, maskSpec?.op]);
  // Group coverage is immutable unless the source contains an image whose
  // bound props are resolved from the live store. Cache only for a live
  // consumer node (the signal-driven rerender path), leaving dynamic image
  // masks on the existing resolver path below.
  const cachedGroupMaskCoverage = useMemo(() => {
    if (
      bindings.length === 0 ||
      groupMaskSource?.kind !== "frame" ||
      groupMaskHasLiveImage(groupMaskSource)
    ) {
      return undefined;
    }
    return buildMaskCoverageFromGroup(
      groupMaskSource,
      groupMaskSource.id,
      GROUP_MASK_MAX_DEPTH,
      undefined,
      false,
      undefined,
      allowedHosts,
      isHostAssetUrl,
    );
  }, [bindings.length, groupMaskSource, allowedHosts, isHostAssetUrl]);

  // LSDP/1.1 §3.2.2 — a per-leaf transition on the most recent delta
  // takes precedence over the bundle-level default. Only bound props
  // can carry a wire transition (a static prop never moves). Snapshots
  // clear the directive, so the bundle default reapplies after a reset.
  //
  // We resolve here in the parent's render (useSignals() above tracks
  // these reads) rather than inside the primitive's callback — that way
  // a transition signal change re-renders this Node, which in turn re-
  // renders the primitive with the new transition prop.
  const liveTransitions: Record<string, Transition | undefined> = {};
  for (const [key, transitionSignal] of transitionBindings) {
    const ts = transitionSignal.value;
    if (ts !== undefined) liveTransitions[key] = ts;
  }
  const transitionFor = (key: string): Transition | undefined => {
    if (key in liveTransitions) return liveTransitions[key];
    return node.transitions?.[key];
  };

  const childRenderBlurInsideShape =
    renderBlurInsideShape || hasStrokeOnlyVectorMask(resolved, shapeIndex);
  // Bundle child arrays are immutable. Preserve their React element identities
  // across updates to this node so reconciliation can bail out of static lists.
  const children = useMemo(
    () =>
      node.children?.map((child, idx) => (
        <Tree
          key={child.id ?? idx}
          node={child}
          store={store}
          renderBlurInsideShape={childRenderBlurInsideShape}
        />
      )),
    [node.children, store, childRenderBlurInsideShape],
  );

  // LSML 1.1 §5.4 — universal props applied uniformly across all
  // primitives. Pulled out of `resolved` so primitives can ignore
  // them ; the wrapper composes with whatever transform/opacity the
  // primitive's own framer-motion may apply.
  //
  // ADR 002 §3.1 (D1) — absolute placement. The compiler flattens LSML
  // `position:{x,y}` → `resolved.x`/`resolved.y` and `size:{w,h}` →
  // `resolved.width`/`resolved.height` on EVERY primitive (compile.ts
  // §universal-props). The wrapper consumes them as absolute placement,
  // EXCEPT on `frame` : a frame already positions itself (it reads
  // `x`/`y`/`width`/`height` into its own absolute box + transform), so
  // letting the wrapper pin it too would double the offset. Every other
  // kind (text/shape/image/media/instance/stack/grid) is placed by the
  // wrapper. A node without `x`/`y` gets `position: undefined` → normal
  // flow (RC#2 non-regression).
  // A masked node with a real blend hoists that blend above the mask wrapper
  // (the mask isolates an inner `mix-blend-mode`). Compute it once here so the
  // universal prop and the wrapper below agree.
  const maskHoistsBlend =
    !suppressBlendMode &&
    resolved.mask !== undefined &&
    typeof resolved.blendMode === "string" &&
    parseBlendMode(resolved.blendMode) !== undefined;
  // Figma evaluates a layer blur on a luminous vector paint after a
  // stroke-only alpha mask has clipped that paint.  Keeping this decision on
  // the typed composition (rather than a bundle/node selector) makes the same
  // rule apply to every `plus-lighter` paint using that mask topology.
  const renderBlurAfterStrokeMask =
    node.kind === "shape" &&
    hasStrokeOnlyVectorMask(resolved, shapeIndex) &&
    parseBlendMode(resolved.blendMode) === "plus-lighter";
  // A frame normally owns its own absolute box (frame.tsx), so the universal
  // wrapper deliberately receives no position/size. When a frame also needs a
  // universal isolation effect, however, that wrapper becomes a real DOM
  // containing block (notably `backdrop-filter`). Leaving it un-sized makes
  // the frame's absolute children resolve against the wrapper's normal-flow
  // slot instead of the authored frame box. Let the wrapper own the box in
  // that case and reset the inner frame's x/y below.
  const frameUniversalOwnsBox =
    node.kind === "frame" &&
    (typeof resolved.universal_opacity === "number" ||
      typeof resolved.blur === "number" ||
      typeof resolved.staticBlurPasses === "number" ||
      typeof resolved.backdropBlur === "number" ||
      (typeof resolved.noise === "object" && resolved.noise !== null) ||
      (typeof resolved.texture === "object" && resolved.texture !== null) ||
      (typeof resolved.glass === "object" && resolved.glass !== null) ||
      resolved.sizing !== undefined ||
      (typeof resolved.blendMode === "string" && !maskHoistsBlend));
  const universal = {
    visible: typeof resolved.visible === "boolean" ? resolved.visible : undefined,
    opacity:
      typeof resolved.universal_opacity === "number" ? resolved.universal_opacity : undefined,
    // A frame applies its own static rotation (frame.tsx) so it pivots around
    // its centre ; the wrapper has no box for a self-positioning frame and would
    // pivot around a collapsed (0-height) box. Non-frames keep it on the wrapper
    // (they DO carry position/size there).
    rotation:
      node.kind === "frame"
        ? undefined
        : typeof resolved.rotation === "number"
          ? resolved.rotation
          : undefined,
    // Mirror (Figma scaleY(-1)) — like rotation, a frame mirrors itself
    // (frame.tsx) ; non-frames carry it on the wrapper, composed with rotation.
    flipY: node.kind === "frame" ? undefined : resolved.flipY === true,
    blur:
      node.kind === "shape" && (renderBlurInsideShape || renderBlurAfterStrokeMask)
        ? undefined
        : typeof resolved.blur === "number"
          ? resolved.blur
          : undefined,
    staticBlurPasses:
      node.kind === "shape" && (renderBlurInsideShape || renderBlurAfterStrokeMask)
        ? undefined
        : typeof resolved.staticBlurPasses === "number"
          ? resolved.staticBlurPasses
          : undefined,
    // ADR 014 Tier B (issue #355) — backdropBlur/noise/texture/glass are
    // consumed by the wrapper (CSS backdrop-filter / EffectOverlays), same
    // shape-narrowing rigor as `mask` below (full field validation lives in
    // the wrapper/EffectOverlays' own clamps, R8 — a malformed object here
    // degrades to "no effect", never an unbounded value reaching CSS).
    backdropBlur: typeof resolved.backdropBlur === "number" ? resolved.backdropBlur : undefined,
    noise:
      typeof resolved.noise === "object" && resolved.noise !== null
        ? (resolved.noise as UniversalProps["noise"])
        : undefined,
    texture:
      typeof resolved.texture === "object" && resolved.texture !== null
        ? (resolved.texture as UniversalProps["texture"])
        : undefined,
    glass:
      typeof resolved.glass === "object" && resolved.glass !== null
        ? (resolved.glass as UniversalProps["glass"])
        : undefined,
    sizing: extractSizing(resolved.sizing),
    position:
      node.kind === "frame" && !frameUniversalOwnsBox ? undefined : extractPosition(resolved),
    size: node.kind === "frame" && !frameUniversalOwnsBox ? undefined : extractSize(resolved),
    // ADR 002 §3.2 (D2 / #D) — `blendMode` is a universal prop on every
    // primitive ; the wrapper re-validates it against the closed enum
    // before applying `mix-blend-mode` (T4 runtime gate). Pass the raw
    // resolved value through ; the wrapper omits anything off the enum.
    // A blend on a MASKED node is hoisted ABOVE the mask wrapper (see below) —
    // a CSS mask forms an isolating group, so a `mix-blend-mode` left on the
    // (inner) wrapper would fold over a transparent backdrop (the caramel
    // hard-light showed the raw blue wave instead of compositing over the warm
    // gradient). Drop it here when it will be hoisted.
    blendMode:
      !suppressBlendMode && typeof resolved.blendMode === "string" && !maskHoistsBlend
        ? resolved.blendMode
        : undefined,
  };

  // ADR 002 §3.1 (D1) — a container holding at least one absolutely
  // positioned child must establish the containing block so the child's
  // `left/top` resolve against it (and not a distant ancestor). `Frame`
  // is already `position:absolute` ; `Stack`/`Grid` flip to
  // `position:relative` only when needed (no change for pure auto-layout
  // boards — RC#2). Threaded to the primitive so the layout container
  // decides ; a node without absolute children is untouched.
  // Merge live-interpolated colour values (§6.5) over the resolved
  // props — the primitive re-validates them through `parseCssColor`.
  const resolvedWithColors =
    Object.keys(bindAnimate.colorProps).length > 0
      ? { ...resolved, ...bindAnimate.colorProps }
      : resolved;
  const primitiveResolved = frameUniversalOwnsBox
    ? { ...resolvedWithColors, x: 0, y: 0 }
    : resolvedWithColors;

  // ADR 002 §3.2 (#E) — a typed `mask` lowered onto the node. Build it up-front
  // so an IMAGE mask (CSS `mask-image`) can sit INSIDE the wrapper — it must
  // rotate WITH the content under the wrapper's transform, else an outer
  // un-rotated mask clips a mis-rotated crop (the caramel wave shrank off-box).
  // A group/shape SVG mask stays OUTSIDE (its coverage is authored in the parent
  // coordinate space). The mask is built ENTIRELY from typed fields (T3) ; enums
  // re-validated (T4), image source host-gated (T1/T2) before any `href`.
  let built: ReturnType<typeof buildMask> | null = null;
  let simpleRoundedMaskRadius: number | null = null;
  if (resolved.mask !== undefined) {
    // #K/#O — resolve a ref to its inlined coverage geometry, routed on the
    // referenced node's `kind` (shape → own outline ; frame → visible children).
    const resolveShape = (ref: string, consumerProps?: Record<string, unknown>) => {
      const target = shapeIndex.get(ref);
      if (!target) return null;
      const coverage =
        target.kind === "frame"
          ? target === groupMaskSource && cachedGroupMaskCoverage !== undefined
            ? cachedGroupMaskCoverage
            : buildMaskCoverageFromGroup(
                target,
                target.id,
                GROUP_MASK_MAX_DEPTH,
                undefined,
                false,
                (sourceNode) => resolveProps(sourceNode, store, scope),
                allowedHosts,
                isHostAssetUrl,
              )
          : buildMaskCoverageFromShape(target, target.id, consumerProps);
      return coverage;
    };
    // A FEATHERED coverage (a blurred mask edge, e.g. the bg-texture ellipse) is
    // the only case that needs the wrapper feather pad. Detect it from the mask
    // SOURCE group's children so a sharp mask skips the pad entirely (no extra
    // wrapper, no structural change).
    let feather = false;
    if (maskSpec) {
      const src = maskSpec.source as { kind?: string; ref?: unknown };
      if ((src.kind === "group" || src.kind === "shape") && typeof src.ref === "string") {
        const t = shapeIndex.get(src.ref);
        const cachedAnalysis =
          src.kind === "group" && t === groupMaskSource ? cachedGroupMaskAnalysis : undefined;
        feather =
          cachedAnalysis !== undefined
            ? cachedAnalysis.feather
            : t
              ? coverageIsFeathered(t, GROUP_MASK_MAX_DEPTH, false)
              : false;
        if (
          !feather &&
          src.kind === "group" &&
          maskSpec.type === "alpha" &&
          maskSpec.op === "intersect"
        ) {
          simpleRoundedMaskRadius =
            cachedAnalysis !== undefined
              ? cachedAnalysis.simpleRoundedMaskRadius
              : t
                ? simpleRoundedRectMaskRadius(t)
                : null;
        }
      }
    }
    built = maskSpec
      ? buildMask(
          maskSpec,
          allowedHosts,
          node.id,
          resolveShape,
          extractSize(resolved),
          feather,
          resolved,
          isHostAssetUrl,
        )
      : null;
  }
  if (built && simpleRoundedMaskRadius !== null) {
    // A sharp rounded-rectangle mask is exactly equivalent to the wrapper's
    // own overflow clip.  CSS `mask` creates an isolated stacking context;
    // border-radius preserves the authored stencil without isolating a valid
    // blend mode carried by a masked child.
    const maskStyle = { ...built.style };
    delete maskStyle.mask;
    delete maskStyle.WebkitMask;
    built = {
      ...built,
      style: { ...maskStyle, borderRadius: simpleRoundedMaskRadius },
    };
  }
  const isImageMask =
    built !== null && built.style != null && "maskImage" in (built.style as object);
  const maskLayerBlur = renderBlurAfterStrokeMask
    ? buildLayerBlurFilter(
        typeof resolved.blur === "number" ? resolved.blur : undefined,
        typeof resolved.staticBlurPasses === "number" ? resolved.staticBlurPasses : undefined,
      )
    : undefined;

  // A frame mask normally wraps the complete child subtree.  That is correct
  // for normal paint, but CSS masks isolate descendant `mix-blend-mode` from
  // the scene backdrop.  When a masked frame contains direct, positioned
  // children with different blend modes, render contiguous blend runs as
  // sibling masked layers: each run keeps the authored mask, while its blend
  // is applied on the outer sibling where it can see the already-painted
  // backdrop.  The structural predicate is deliberately conservative; any
  // unsupported layout/mask shape keeps the historical single-wrapper path.
  const shouldSplitMaskedBlendRuns = built !== null && !isImageMask;
  const splitRuns = shouldSplitMaskedBlendRuns
    ? memoizedMaskedBlendRuns(node, resolved, shapeIndex)
    : null;

  const primitiveEl = (
    <Primitive
      resolved={primitiveResolved}
      nodeId={node.id}
      transitionFor={transitionFor}
      animateInitial={node.animate_initial}
      staticRender={canRenderStaticPrimitive(node)}
      keyframed={node.keyframes !== undefined}
      establishesContainingBlock={hasAbsoluteChild}
      renderBlurInsideShape={renderBlurInsideShape}
    >
      {children}
    </Primitive>
  );

  let inner: ReactNode = primitiveEl;
  if (built && isImageMask) {
    // Image mask co-located with the content : the CSS mask-image is on a box the
    // wrapper's transform rotates, keeping its alpha aligned to the wave.
    inner = <div style={{ width: "100%", height: "100%", ...built.style }}>{inner}</div>;
  }

  let body = <UniversalWrapper {...universal}>{inner}</UniversalWrapper>;

  if (splitRuns !== null && built !== null) {
    // The split layers must sit where the ordinary mask wrapper sits: in the
    // parent's coordinate system.  Putting them inside this frame would apply
    // the mask after the frame's authored x/y offset, shifting the coverage by
    // the mask frame's own negative position.  Recreate the same frame once
    // per run and keep the mask outside each copy, preserving that offset.
    const maskedRuns = splitRuns.map((run, runIndex) => {
      const runChildren = run.nodes.map((child, childIndex) => (
        <Tree
          key={child.id ?? `${runIndex}-${childIndex}`}
          node={child}
          store={store}
          suppressBlendMode
        />
      ));
      const runPrimitive = (
        <Primitive
          resolved={primitiveResolved}
          nodeId={node.id}
          transitionFor={transitionFor}
          animateInitial={node.animate_initial}
          staticRender={canRenderStaticPrimitive(node)}
          keyframed={node.keyframes !== undefined}
          establishesContainingBlock={hasAbsoluteChild}
          renderBlurInsideShape={renderBlurInsideShape}
        >
          {runChildren}
        </Primitive>
      );
      return (
        <MaskedBlendRun
          key={`${node.id ?? "anonymous"}-mask-blend-${runIndex}`}
          built={built}
          blendMode={run.blendMode}
        >
          <UniversalWrapper {...universal}>{runPrimitive}</UniversalWrapper>
        </MaskedBlendRun>
      );
    });

    body = <>{maskedRuns}</>;
  }

  if (built && !isImageMask && splitRuns === null) {
    // The (group/shape) mask wrapper MUST own a real box for the CSS mask to clip
    // anything : its content is `position:absolute`, so fill the parent's
    // containing block to share the absolutely-placed body's coordinate space.
    // `overflow:hidden` bounds the (oversized) masked content to this box — the
    // CSS `mask` alone does NOT clip it (removing it leaked the 2786×1491 tile
    // group everywhere).
    // Only a FEATHERED mask grows the box (+ shifts the coverage, mask.tsx) ;
    // a sharp mask uses pad 0 → inset:0, identical to the un-padded structure.
    const pad = built.feather ? MASK_FEATHER_PAD : 0;
    body = (
      <div
        style={{
          position: "absolute",
          inset: -pad,
          overflow: "hidden",
          ...(maskLayerBlur !== undefined ? { filter: maskLayerBlur } : {}),
          ...built.style,
        }}
      >
        <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
          <defs>{built.def}</defs>
        </svg>
        {/* Inner box inset by +PAD cancels the wrapper's −PAD grow for the
            CONTENT — the body keeps its original coordinates while the masked
            box (and its feathered rim) is the bigger one. */}
        <div style={{ position: "absolute", inset: pad }}>{body}</div>
      </div>
    );
  }
  // Hoist the node's blend ABOVE the wrapper+mask : an outer box carrying ONLY
  // `mix-blend-mode` (no transform / opacity / filter / mask) so it composites
  // the masked result with the SCENE backdrop. The caramel 3d-render then
  // hard-lights over the warm gradient (orange) instead of its raw image (blue).
  if (built && maskHoistsBlend) {
    const hoisted = parseBlendMode(resolved.blendMode);
    body = (
      <div
        style={{
          position: "absolute",
          inset: 0,
          mixBlendMode: hoisted as React.CSSProperties["mixBlendMode"],
        }}
      >
        {body}
      </div>
    );
  }

  // Scalar bindAnimate channels apply on a wrapping motion.div (same
  // composition model as UniversalWrapper). Motion values mutate the
  // style directly — zero React re-render per frame on the hot path.
  if (bindAnimate.motionStyle) {
    body = (
      <motion.div
        ref={bindAnimate.motionRef}
        data-lumencast-bind-animate={node.id ?? ""}
        style={bindAnimate.motionStyle}
      >
        {body}
      </motion.div>
    );
  }

  // LSML 1.1 §6.6 — when a primitive declares keyframes, wrap the
  // rendered subtree in a player that drives framer-motion through the
  // step path. The player handles replay-on-key-change and reads any
  // ambient stagger delay from StaggerContext (§6.7).
  if (node.keyframes) {
    return (
      <KeyframePlayer keyframes={node.keyframes} store={store} nodeId={node.id}>
        {body}
      </KeyframePlayer>
    );
  }
  return body;
}

interface MaskedBlendRunSpec {
  nodes: RenderNode[];
  blendMode?: string;
}

type BuiltMask = NonNullable<ReturnType<typeof buildMask>>;

/**
 * Identify the safe subset where a masked frame can be split into sibling
 * blend layers without changing layout semantics. Runs stay contiguous so
 * the authored painter order is preserved. The function intentionally
 * declines nested masks, non-intersect operations, flow layout, and group
 * opacity: those cases retain the ordinary single-mask path.
 */
function maskedBlendRuns(
  node: RenderNode,
  resolved: Record<string, unknown>,
  shapeIndex: ReadonlyMap<string, RenderNode>,
): MaskedBlendRunSpec[] | null {
  if (node.kind !== "frame") return null;
  const children = (node.children ?? []).filter((child) => child.props?.visible !== false);
  if (children.length < 2 || children.some((child) => !childIsAbsolute(child))) return null;
  // Only split the Figma pattern where a frame contains painted shape layers
  // clipped by a separate stroke-only shape.  Group masks are used throughout
  // the document for cards, textures, and artwork; splitting those would
  // change their paint order and their containing-box semantics.

  const spec = parseMaskSpec(resolved.mask, node.id);
  if (spec === null || spec.type !== "alpha" || spec.op !== "intersect") return null;
  if (spec.source.kind !== "shape") return null;
  const maskSource = shapeIndex.get(spec.source.ref);
  if (!isStrokeOnlyMaskSource(maskSource)) return null;
  const parentBlend = parseBlendMode(resolved.blendMode);
  if (parentBlend !== undefined && parentBlend !== "normal") return null;
  if (
    (typeof resolved.opacity === "number" && resolved.opacity !== 1) ||
    (typeof resolved.universal_opacity === "number" && resolved.universal_opacity !== 1)
  ) {
    return null;
  }

  const runs: MaskedBlendRunSpec[] = [];
  for (const child of children) {
    const parsed = parseBlendMode(child.props?.blendMode);
    const blendMode = parsed !== undefined && parsed !== "normal" ? parsed : undefined;
    const current = runs.at(-1);
    // A non-normal child is its own Figma compositing surface.  Grouping two
    // adjacent OVERLAY (or SCREEN, etc.) children would make the browser
    // blend the second child with the first child instead of with the already
    // painted backdrop.  Normal children can still share one run because
    // their paint operation is associative here.
    if (blendMode !== undefined) {
      runs.push({ nodes: [child], blendMode });
    } else if (current !== undefined && current.blendMode === undefined) {
      current.nodes.push(child);
    } else {
      runs.push({ nodes: [child], blendMode });
    }
  }
  return runs.some((run) => run.blendMode !== undefined) ? runs : null;
}

interface MaskedBlendRunMemo {
  mask: unknown;
  blendMode: unknown;
  opacity: unknown;
  universalOpacity: unknown;
  shapeIndex: ReadonlyMap<string, RenderNode>;
  value: MaskedBlendRunSpec[] | null;
}

const maskedBlendRunMemo = new WeakMap<RenderNode, MaskedBlendRunMemo>();

/** Cache only nodes that reached the vector-mask split path. The decision is
 * structural except for these resolved gates; unrelated live deltas therefore
 * reuse the scan without adding a hook or dependency array to ordinary nodes. */
function memoizedMaskedBlendRuns(
  node: RenderNode,
  resolved: Record<string, unknown>,
  shapeIndex: ReadonlyMap<string, RenderNode>,
): MaskedBlendRunSpec[] | null {
  const cached = maskedBlendRunMemo.get(node);
  if (
    cached !== undefined &&
    cached.mask === resolved.mask &&
    cached.blendMode === resolved.blendMode &&
    cached.opacity === resolved.opacity &&
    cached.universalOpacity === resolved.universal_opacity &&
    cached.shapeIndex === shapeIndex
  ) {
    return cached.value;
  }

  const value = maskedBlendRuns(node, resolved, shapeIndex);
  maskedBlendRunMemo.set(node, {
    mask: resolved.mask,
    blendMode: resolved.blendMode,
    opacity: resolved.opacity,
    universalOpacity: resolved.universal_opacity,
    shapeIndex,
    value,
  });
  return value;
}

/** A stroke-only shape is a coverage outline, not a full paint surface. */
function isStrokeOnlyMaskSource(node: RenderNode | undefined): boolean {
  if (node?.kind !== "shape") return false;
  const props = node.props ?? {};
  const hasStroke =
    (typeof props.stroke === "string" &&
      props.stroke !== "none" &&
      props.stroke !== "transparent") ||
    (typeof props.stroke === "object" &&
      props.stroke !== null &&
      typeof (props.stroke as { color?: unknown }).color === "string");
  if (!hasStroke) return false;
  if (typeof props.fill === "string" && props.fill !== "none" && props.fill !== "transparent") {
    return false;
  }
  if (
    Array.isArray(props.fills) &&
    props.fills.some((fill) => fill !== undefined && fill !== null)
  ) {
    return false;
  }
  return true;
}

/**
 * Detect the structural composition in which vector children are painted
 * through a stroke-only alpha mask. It is deliberately narrower than a
 * generic masked subtree: group/image masks and filled shape masks retain
 * the ordinary HTML layer-blur path because their paint semantics differ.
 */
function hasStrokeOnlyVectorMask(
  resolved: Record<string, unknown>,
  shapeIndex: ReadonlyMap<string, RenderNode>,
): boolean {
  const mask = resolved.mask;
  if (typeof mask !== "object" || mask === null) return false;
  const source = (mask as { source?: unknown }).source;
  if (typeof source !== "object" || source === null) return false;
  const sourceRecord = source as { kind?: unknown; ref?: unknown };
  if (sourceRecord.kind !== "shape" || typeof sourceRecord.ref !== "string") return false;
  const maskRecord = mask as { type?: unknown; op?: unknown };
  if (maskRecord.type !== "alpha" || maskRecord.op !== "intersect") return false;
  return isStrokeOnlyMaskSource(shapeIndex.get(sourceRecord.ref));
}

/** Paint one structurally-derived mask run and keep its blend outside the CSS
 * mask stacking context. The definition is duplicated per run rather than
 * shared through mutable state; each copy is built from the same typed source
 * node and remains local to this subtree. */
function MaskedBlendRun({
  built,
  blendMode,
  children,
}: {
  built: BuiltMask;
  blendMode?: string;
  children: ReactNode;
}): ReactNode {
  const pad = built.feather ? MASK_FEATHER_PAD : 0;
  const masked = (
    <div
      style={{
        position: "absolute",
        inset: -pad,
        overflow: "hidden",
        ...built.style,
      }}
    >
      <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
        <defs>{built.def}</defs>
      </svg>
      <div style={{ position: "absolute", inset: pad }}>{children}</div>
    </div>
  );
  if (blendMode === undefined) return masked;
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        ...(blendMode === undefined
          ? {}
          : { mixBlendMode: blendMode as CSSProperties["mixBlendMode"] }),
      }}
    >
      {masked}
    </div>
  );
}

function extractSizing(value: unknown): { x?: SizingMode; y?: SizingMode } | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const obj = value as { x?: unknown; y?: unknown };
  const out: { x?: SizingMode; y?: SizingMode } = {};
  if (obj.x === "fixed" || obj.x === "hug" || obj.x === "fill") out.x = obj.x;
  if (obj.y === "fixed" || obj.y === "hug" || obj.y === "fill") out.y = obj.y;
  return out.x !== undefined || out.y !== undefined ? out : undefined;
}

function finite(v: unknown): number | undefined {
  return typeof v === "number" && Number.isFinite(v) ? v : undefined;
}

/** ADR 002 §3.1 (D1) — form the absolute-placement `position:{x,y}` from
 *  the compiler-flattened `resolved.x`/`resolved.y`. BOTH axes must be
 *  finite numbers : a partial or malformed pair yields `undefined` (the
 *  node stays in the normal flow — RC#3 mistyped-position is inert, not
 *  injected). Values are plain numbers, never untrusted strings.
 *
 *  ADR 006 §3.3 — a `meet.peer` node produced DIRECTLY by the Prism from-scene
 *  export bypasses `@lumencast/compiler`, so its geometry arrives in the NESTED
 *  LSML shape (`position:{x,y}`) rather than flattened `x`/`y`. We accept that
 *  nested form as a fallback ONLY when the flat form is absent. This is purely
 *  additive : every compiled bundle always carries flat `x`/`y` (which win), so
 *  no existing node's placement changes. */
function extractPosition(resolved: Record<string, unknown>): { x: number; y: number } | undefined {
  let x = finite(resolved.x);
  let y = finite(resolved.y);
  if (x === undefined && y === undefined) {
    const nested = resolved.position as { x?: unknown; y?: unknown } | undefined;
    if (nested && typeof nested === "object") {
      x = finite(nested.x);
      y = finite(nested.y);
    }
  }
  if (x === undefined || y === undefined) return undefined;
  return { x, y };
}

/** ADR 002 §3.1 (D1) — the absolute box size from `resolved.width`/
 *  `resolved.height`. Only meaningful alongside `position` (the wrapper
 *  ignores it otherwise). Partial sizes are allowed (one axis hugs).
 *
 *  ADR 006 §3.3 — like `extractPosition`, accept the NESTED `size:{w,h}` shape
 *  as a fallback for an uncompiled `meet.peer` node (flat `width`/`height`
 *  always win when present, so compiled bundles are unaffected). Without this,
 *  the `meet.peer` wrapper got a position but NO size → the `<video>` filled a
 *  collapsed box instead of the authored geometry (the observed RC-Geo bug). */
function extractSize(resolved: Record<string, unknown>): { w?: number; h?: number } | undefined {
  let w = finite(resolved.width);
  let h = finite(resolved.height);
  if (w === undefined && h === undefined) {
    const nested = resolved.size as { w?: unknown; h?: unknown } | undefined;
    if (nested && typeof nested === "object") {
      w = finite(nested.w);
      h = finite(nested.h);
    }
  }
  if (w === undefined && h === undefined) return undefined;
  return { w, h };
}

/** True when a child node carries a finite `{x,y}` absolute position
 *  (static prop OR a bound `x`/`y`). Used by a container primitive to
 *  decide whether to establish a positioned containing block. A bound
 *  position is treated as "absolute" structurally — the key presence is
 *  static even if the value moves live. */
function childIsAbsolute(child: RenderNode): boolean {
  if (child.kind === "frame") return false; // a frame positions itself
  const props = child.props ?? {};
  const bindings = child.bindings ?? {};
  // ADR 006 §3.3 — also recognise the nested `position:{x,y}` shape (an
  // uncompiled `meet.peer` node), mirroring extractPosition's fallback.
  const nested = props.position as { x?: unknown; y?: unknown } | undefined;
  const hasX =
    finite(props.x) !== undefined ||
    "x" in bindings ||
    (nested ? finite(nested.x) !== undefined : false);
  const hasY =
    finite(props.y) !== undefined ||
    "y" in bindings ||
    (nested ? finite(nested.y) !== undefined : false);
  return hasX && hasY;
}

function Repeat({ node, store }: TreeProps): ReactNode {
  useSignals();
  const scope = usePathScope();
  checkNodeProps(node);

  const itemsBinding = node.bindings?.items;
  const items =
    itemsBinding === undefined
      ? []
      : ((store.signal(scopedPath(scope, itemsBinding)).value as unknown[] | undefined) ?? []);
  if (!Array.isArray(items)) return null;

  const template = node.children?.[0];
  if (!template) return null;

  // LSML 1.1 §6.7 — `stagger_ms` produces wave-like reveals across
  // iterations. We compute the per-iteration delay (capped) and feed
  // it to descendants via StaggerContext so the KeyframePlayer (and
  // future animate-aware primitives) can pick it up without per-
  // iteration scripting. `stagger_ms: 0` (or unset) is a no-op.
  const staggerMs = typeof node.stagger_ms === "number" ? node.stagger_ms : 0;

  return (
    <>
      {items.map((_item, idx) => {
        const delayMs = computeStaggerDelayMs(idx, staggerMs);
        const tree = (
          <PathScopeProvider key={idx} prefix={`${itemsBinding ?? ""}.${idx}`}>
            <Tree node={template} store={store} />
          </PathScopeProvider>
        );
        if (delayMs <= 0) return tree;
        return (
          <StaggerContext.Provider key={idx} value={delayMs}>
            {tree}
          </StaggerContext.Provider>
        );
      })}
    </>
  );
}

function resolveProps(node: RenderNode, store: Store, scope: string): Record<string, unknown> {
  const entries = getBindingEntries(node);
  if (entries.length === 0) return resolvePropsFromValues(node, entries, EMPTY_BINDING_VALUES);

  const paths = entries.map(([, path]) => scopedPath(scope, path));
  const signals = paths.map((path) => store.signal(path));
  return resolvePropsFromValues(node, entries, readBindingValues(signals));
}

function resolvePropsFromValues(
  node: RenderNode,
  entries: readonly (readonly [string, string])[],
  bindingValues: readonly unknown[],
): Record<string, unknown> {
  const out: Record<string, unknown> = { ...(node.props ?? {}) };
  for (let index = 0; index < entries.length; index += 1) {
    const [propKey] = entries[index];
    const value = bindingValues[index];
    // Optional live values must not erase a valid static fallback. Twitch
    // author colours are optional, so a missing/null colour keeps the
    // colour authored in the bundle instead of falling through to the
    // document's (usually black) currentColor.
    if (propKey === "colour" && (value === null || value === undefined)) {
      continue;
    }
    out[propKey] = value;
  }
  return out;
}

/** Helper for the useMemo deps array — read each bound signal so the
 *  memo invalidates when any binding moves. */
function readBindingValues(signals: readonly Signal<unknown>[]): readonly unknown[] {
  if (signals.length === 0) return EMPTY_BINDING_VALUES;

  const values = new Array<unknown>(signals.length);
  for (let index = 0; index < signals.length; index += 1) {
    values[index] = signals[index].value;
  }
  return values;
}
