import { motion } from "framer-motion";
import { Fragment } from "react";
import type { CSSProperties, ReactNode } from "react";
import type { PrimitiveProps } from "./index";
import { toFramer, mountPlay, resolveTransition } from "../../animate/transitions";
import { parseCssColor, warnRejectedColor } from "../css-color";
import { emitDiagnostic } from "../diagnostics";
import { backgroundsToCss, parseFills, sanitizeFills, type Fill } from "../fill";
import { buildShadowCss, type InnerShadow } from "../shadow-css";
import { validatePathData } from "../svg-path";

// ── Typography grammars (LSML 1.1 TextStyle, schema.json) ───────────
// Every typo prop is wire-drivable (static bundle prop OR live LSDP
// delta via `resolveProps`, tree.tsx) and lands in inline CSS, so each
// value is validated against the field's spec'd grammar before it may
// reach the style object. Enum fields go through a closed allowlist
// (the emitted string is always one of these constants — never the
// input), numeric fields through finite-number checks. There is NO
// string passthrough on any of these sites (ADR 001 RC#11 by
// construction : no untrusted string ever reaches the style object).
const TEXT_TRANSFORMS = new Set(["none", "uppercase", "lowercase", "capitalize"]);
const TEXT_DECORATIONS = new Set(["none", "underline", "line-through"]);
const FONT_STYLES = new Set(["normal", "italic", "oblique"]);

// ── Defence-in-depth upper bounds (issue #34, Bastion follow-up on
// PR #38) ─────────────────────────────────────────────────────────────
// The numeric typo fields were type-validated but unbounded ; an absurd
// value pushed by a hostile bundle or live delta could degrade layout /
// rendering (e.g. a 10⁹-line clamp or a kilometric letter spacing).
// Policy : a value beyond its cap is REJECTED (diagnostic + omit → CSS
// initial), consistent with the existing typo grammar gates — NOT
// clamped, unlike the R8 filter caps where the spec explicitly blesses
// clamping. Rationale : there is no "nearest sensible rendering" for an
// absurd typographic value, the author's intent is unknowable ; safe
// default beats silently-altered output.
/** Max `maxLines` accepted (Bastion suggested ≤ 1000 on PR #38). */
export const MAX_MAX_LINES = 1000;
/** Max unitless `lineHeight` multiplier (100× the font size is already
 *  far beyond any broadcast layout). */
export const MAX_LINE_HEIGHT = 100;
/** Max |letterSpacing| in px, both directions (±1000 px covers any
 *  legitimate broadcast typography). */
export const MAX_LETTER_SPACING_PX = 1000;
const MAX_TEXT_OUTLINE_CHARS = 4096;
const MAX_TEXT_OUTLINE_PATHS = 64;
const MAX_TEXT_OUTLINE_DIMENSION = 1_000_000;

// ── fontFamily policy (issue #34, Bastion follow-up on PR #38) ───────
// Decision : SHAPE validation, not a font allowlist. `fontFamily` is
// assigned through the React style object (per-property assignment via
// CSSStyleDeclaration), which cannot break out of the declaration — so
// the residual risk is malformed CSS, not injection. A font allowlist
// would couple the runtime to a host-specific font inventory (a spec /
// RFC matter — flagged for Atlas in the PR), whereas shape validation
// keeps any legitimate family name working. The grammar accepts
// comma-separated family lists with optional quotes ; the injection
// metacharacters (`;` `}` `{` `:` `\` `<` `>` `(` `)`) and `url(` are
// rejected by construction (none of their characters are allowed).
// Anchored, single character class with a bounded quantifier — linear
// time (RC#12).
const FONT_FAMILY_RE = /^[a-zA-Z0-9 ,.'"_-]{1,256}$/;

/** Validate an untrusted `fontFamily` value. Returns the string or
 *  `null` on rejection (handled as "omit → inherit", with diagnostic). */
export function parseFontFamily(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const v = value.trim();
  if (v.length === 0) return null;
  return FONT_FAMILY_RE.test(v) ? v : null;
}

/** Text leaf. Value renders as the displayed string ; style props
 *  cover the full LSML TextStyle (size / font / weight / colour /
 *  alignment / lineHeight / letterSpacing / textTransform /
 *  textDecoration / fontStyle) plus `maxLines` (§4.4 ellipsis
 *  truncation). Opacity is animated when a transition is declared on
 *  `opacity` or `value`. An `animate.from` makes it mount-play
 *  (initial → target) on mount. */
export function Text({
  resolved,
  nodeId,
  transitionFor,
  animateInitial,
  staticRender = false,
}: PrimitiveProps) {
  const value = resolved.value === undefined ? "" : String(resolved.value);
  // Figma serializes authored line breaks as Unicode LINE SEPARATOR / PARAGRAPH
  // SEPARATOR characters. HTML treats those characters as ordinary text in a
  // `pre` span, while Figma renders them as hard line breaks. Normalize only
  // the display value; the original value remains the binding/text-outline
  // identity used by the authoring metadata.
  const displayValue = value.replace(/[\u2028\u2029]/g, "\n");
  const size = (resolved.size as string | number | undefined) ?? "1rem";
  const weight = (resolved.weight as number | undefined) ?? 400;
  // Issue #34 — `font` is untrusted and lands in inline CSS : shape-
  // validate (see fontFamily policy above) ; rejected → inherit.
  let font: string | undefined;
  if (resolved.font !== undefined) {
    const parsed = parseFontFamily(resolved.font);
    if (parsed === null) {
      emitDiagnostic(nodeId, "text.font", "rejected fontFamily : outside the family-list grammar");
    } else {
      font = parsed;
    }
  }
  // RC#11 : `colour` is untrusted (static prop OR live LSDP delta) and
  // lands in inline CSS — strict-parse ; rejected → safe default.
  let colour = "currentColor";
  if (resolved.colour !== undefined) {
    const parsed = parseCssColor(resolved.colour);
    if (parsed === null) {
      warnRejectedColor("text.colour", nodeId);
    } else {
      colour = parsed;
    }
  }
  const align = (resolved.align as string | undefined) ?? "start";
  const textAutoResize = resolved.textAutoResize;
  const fixedWidth = finitePositive(resolved.width);
  const fixedHeight = finitePositive(resolved.height);
  const whiteSpace =
    textAutoResize === "WIDTH_AND_HEIGHT"
      ? "pre"
      : textAutoResize === "NONE" || textAutoResize === "HEIGHT" || textAutoResize === "TRUNCATE"
        ? "pre-wrap"
        : undefined;
  const opacity = numberOr(resolved.opacity, 1);
  const typography = resolveTypography(resolved, nodeId);
  const verticalLayout = resolveTextVerticalLayout(resolved, align, nodeId);
  const shadow = buildShadowCss(resolved.shadow, nodeId, "text.shadow.color");
  const textFillStyle = resolveTextFills(resolved.textFills, nodeId, {
    boxWidth: fixedWidth,
    boxHeight: fixedHeight,
  });
  const hasTextFills = typeof textFillStyle.backgroundImage === "string";
  const textOutline = hasTextFills ? null : resolveTextOutline(resolved.textOutline, value, nodeId);
  // CSS `box-shadow: inset` is defined against an element's rectangular box,
  // while Figma's INNER_SHADOW is clipped to the painted glyphs. Applying the
  // former to a text span creates a visible rectangle around the word. Keep
  // genuine outer box shadows available, but do not leak the inset form into
  // the text element; the glyph fill remains the authoritative paint.
  const textBoxShadow = shadow.outerBoxShadow;
  const innerShadowFilterId =
    shadow.innerShadows === undefined || shadow.innerShadows.length === 0
      ? undefined
      : textInnerShadowFilterId(nodeId, shadow.innerShadows);
  // An SVG alpha filter applied to an HTML span sees the span's rectangular
  // box, not the rasterized glyph alpha.  On editable text this turns an
  // INNER_SHADOW into the visible rectangular border around the word.  Keep
  // the filter available for the optional outline-backed SVG path below, but
  // leave the HTML text paint free of that SVG filter.  The browser's glyph
  // paint remains the authoritative text geometry.
  const textFilter = shadow.filter ?? "";
  const textSegments = renderTextSegments(displayValue, resolved.textSegments, nodeId);
  const textShadowOverlay =
    innerShadowFilterId !== undefined &&
    textSegments === null &&
    fixedWidth !== undefined &&
    fixedHeight !== undefined ? (
      <TextInnerShadowOverlay
        id={`${innerShadowFilterId}-overlay`}
        value={displayValue}
        width={fixedWidth}
        height={fixedHeight}
        shadows={shadow.innerShadows!}
        style={{
          display: "inline-block",
          fontSize: size,
          ...(font !== undefined ? { fontFamily: font } : {}),
          fontWeight: weight,
          color: "white",
          width: fixedWidth,
          height: fixedHeight,
          ...(whiteSpace !== undefined ? { whiteSpace } : {}),
          textAlign: align as React.CSSProperties["textAlign"],
          ...verticalLayout,
          ...typography,
          backgroundImage: "none",
          backgroundClip: "border-box",
          WebkitBackgroundClip: "border-box",
          WebkitTextFillColor: "white",
          filter: "none",
          boxShadow: "none",
          opacity: 1,
        }}
      />
    ) : null;

  const tx = resolveTransition(transitionFor, ["opacity", "value"], animateInitial);
  const play = mountPlay({ opacity }, animateInitial, nodeId);
  const SvgElement = staticRender ? "svg" : motion.svg;
  const TextElement = staticRender ? "span" : motion.span;

  // Figma REST can provide flattened glyph outlines for a static text node.
  // They are deliberately opt-in and value-matched: a live/bound value must
  // keep the editable font-backed path rather than showing stale glyphs.
  if (textOutline !== null) {
    return (
      <>
        {innerShadowFilterId !== undefined && (
          <TextInnerShadowDefs id={innerShadowFilterId} shadows={shadow.innerShadows!} />
        )}
        <SvgElement
          width={textOutline.size.w}
          height={textOutline.size.h}
          viewBox={`0 0 ${textOutline.size.w} ${textOutline.size.h}`}
          role="img"
          aria-label={value}
          focusable="false"
          style={{
            display: "block",
            ...(staticRender ? { opacity } : {}),
            ...(textFilter !== "" ? { filter: textFilter } : {}),
            ...(textBoxShadow !== undefined ? { boxShadow: textBoxShadow } : {}),
          }}
          {...(staticRender
            ? {}
            : { initial: play.initial, animate: play.animate, transition: toFramer(tx) })}
        >
          {textOutline.paths.map((path, index) => (
            <path key={index} d={path.data} fill={colour} fillRule={path.fillRule} />
          ))}
        </SvgElement>
      </>
    );
  }

  return (
    <>
      {innerShadowFilterId !== undefined && (
        <TextInnerShadowDefs id={innerShadowFilterId} shadows={shadow.innerShadows!} />
      )}
      <TextElement
        style={{
          display: "inline-block",
          ...(staticRender ? { opacity } : {}),
          fontSize: size,
          // `font` carries LSML text.style.fontFamily (spec'd in schema.json).
          // Omitted => inherit the host/container font.
          ...(font !== undefined ? { fontFamily: font } : {}),
          fontWeight: weight,
          color: hasTextFills ? "transparent" : colour,
          ...(fixedWidth !== undefined ? { width: fixedWidth } : {}),
          ...(fixedHeight !== undefined ? { height: fixedHeight } : {}),
          ...(whiteSpace !== undefined ? { whiteSpace } : {}),
          textAlign: align as React.CSSProperties["textAlign"],
          ...verticalLayout,
          ...(hasTextFills
            ? {
                ...textFillStyle,
                backgroundClip: "text",
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
              }
            : {}),
          ...(textFilter !== "" ? { filter: textFilter } : {}),
          ...(textBoxShadow !== undefined ? { boxShadow: textBoxShadow } : {}),
          ...typography,
          ...(textShadowOverlay !== null ? { position: "relative" as const } : {}),
        }}
        {...(staticRender
          ? {}
          : { initial: play.initial, animate: play.animate, transition: toFramer(tx) })}
      >
        {textSegments ?? displayValue}
        {textShadowOverlay}
      </TextElement>
    </>
  );
}

/**
 * Render Figma INNER_SHADOW paint from the same font-backed glyphs as the
 * editable HTML text. Applying an SVG filter directly to an HTML span makes
 * Chromium use the span's rectangular alpha in this capture path. A
 * `foreignObject` keeps the browser's own font shaping and line box, while the
 * surrounding SVG supplies a glyph alpha source for the geometry-only filter.
 * The overlay emits shadows only; the base span remains the authoritative text
 * fill and layout.
 */
function TextInnerShadowOverlay({
  id,
  value,
  width,
  height,
  shadows,
  style,
}: {
  id: string;
  value: string;
  width: number;
  height: number;
  shadows: InnerShadow[];
  style: CSSProperties;
}) {
  const padding = Math.max(1, width, height);
  const textStyle: CSSProperties = {
    ...style,
    position: "absolute",
    left: 0,
    top: 0,
  };
  return (
    <svg
      aria-hidden="true"
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      focusable="false"
      style={{
        position: "absolute",
        inset: 0,
        width,
        height,
        overflow: "visible",
        pointerEvents: "none",
        zIndex: 1,
      }}
    >
      <defs>
        <filter
          id={id}
          x={-padding}
          y={-padding}
          width={width + padding * 2}
          height={height + padding * 2}
          filterUnits="userSpaceOnUse"
          primitiveUnits="userSpaceOnUse"
          colorInterpolationFilters="sRGB"
        >
          {shadows.map((shadow, index) => (
            <Fragment key={index}>
              <feGaussianBlur
                in="SourceAlpha"
                stdDeviation={shadow.blur / 2}
                result={`text-overlay-blur-${index}`}
              />
              <feOffset
                in={`text-overlay-blur-${index}`}
                dx={shadow.x}
                dy={shadow.y}
                result={`text-overlay-offset-${index}`}
              />
              <feComposite
                in="SourceAlpha"
                in2={`text-overlay-offset-${index}`}
                operator="out"
                result={`text-overlay-mask-${index}`}
              />
              <feFlood floodColor={shadow.color} result={`text-overlay-color-${index}`} />
              <feComposite
                in={`text-overlay-color-${index}`}
                in2={`text-overlay-mask-${index}`}
                operator="in"
                result={`text-overlay-paint-${index}`}
              />
            </Fragment>
          ))}
          <feMerge>
            {shadows.map((_, index) => (
              <feMergeNode key={index} in={`text-overlay-paint-${index}`} />
            ))}
          </feMerge>
        </filter>
      </defs>
      <g style={{ filter: `url(#${id})` }}>
        <foreignObject x={0} y={0} width={width} height={height}>
          <span style={textStyle}>{value}</span>
        </foreignObject>
      </g>
    </svg>
  );
}

/** Render Figma's bounded per-character style runs without changing the
 * parent text box. Plain inline spans preserve the browser's normal glyph
 * shaping while allowing a font/fill override to affect only its range. */
function renderTextSegments(value: string, raw: unknown, nodeId?: string): ReactNode[] | null {
  if (!Array.isArray(raw) || raw.length === 0) return null;
  const children: ReactNode[] = [];
  let cursor = 0;

  for (let index = 0; index < raw.length; index += 1) {
    const valueAtIndex = raw[index];
    if (typeof valueAtIndex !== "object" || valueAtIndex === null || Array.isArray(valueAtIndex)) {
      emitDiagnostic(nodeId, "text.textSegments", "rejected malformed character-style segment");
      return null;
    }
    const segment = valueAtIndex as Record<string, unknown>;
    const start = segment.start;
    const end = segment.end;
    if (
      !Number.isInteger(start) ||
      !Number.isInteger(end) ||
      (start as number) < cursor ||
      (end as number) <= (start as number) ||
      (end as number) > value.length
    ) {
      emitDiagnostic(nodeId, "text.textSegments", "rejected overlapping or out-of-bounds range");
      return null;
    }
    if ((start as number) > cursor) children.push(value.slice(cursor, start as number));
    const text = value.slice(start as number, end as number);
    children.push(
      <span key={`text-segment-${index}`} style={resolveTextSegmentStyle(segment, nodeId)}>
        {text}
      </span>,
    );
    cursor = end as number;
  }
  if (cursor < value.length) children.push(value.slice(cursor));
  return children;
}

function resolveTextSegmentStyle(segment: Record<string, unknown>, nodeId?: string): CSSProperties {
  const style: CSSProperties = {};
  const rawFont = segment.fontName;
  if (typeof rawFont === "object" && rawFont !== null && !Array.isArray(rawFont)) {
    const font = rawFont as { family?: unknown; style?: unknown };
    const family = parseFontFamily(font.family);
    if (family !== null) style.fontFamily = family;
    if (typeof font.style === "string") {
      const weight = fontWeightFromFigmaStyle(font.style);
      if (weight !== undefined) style.fontWeight = weight;
      if (/italic/i.test(font.style)) style.fontStyle = "italic";
      else if (/oblique/i.test(font.style)) style.fontStyle = "oblique";
    }
  }
  if (finitePositive(segment.fontWeight)) style.fontWeight = segment.fontWeight as number;
  if (finitePositive(segment.fontSize)) style.fontSize = segment.fontSize as number;

  if (segment.textFills !== undefined) {
    const fills = sanitizeFills(
      parseFills(segment.textFills, "text.textSegments.textFills", nodeId),
      "text.textSegments.textFills",
      nodeId,
    );
    const fillStyle = backgroundsToCss(fills, nodeId);
    if (typeof fillStyle.backgroundImage === "string") {
      Object.assign(style, fillStyle, {
        color: "transparent",
        backgroundClip: "text",
        WebkitBackgroundClip: "text",
        WebkitTextFillColor: "transparent",
      });
    }
  }

  const typography = resolveTypography(
    {
      lineHeight: segment.lineHeight,
      letterSpacing: segment.letterSpacing,
      textTransform: segment.textTransform,
      textDecoration: segment.textDecoration,
      fontStyle: segment.fontStyle,
    },
    nodeId,
  );
  Object.assign(style, typography);
  return style;
}

function fontWeightFromFigmaStyle(style: string): number | undefined {
  const normalized = style.toLowerCase().replace(/[\s_-]+/g, "");
  if (normalized.includes("thin") || normalized.includes("hairline")) return 100;
  if (normalized.includes("extralight") || normalized.includes("ultralight")) return 200;
  if (normalized.includes("light")) return 300;
  if (normalized.includes("semibold") || normalized.includes("demibold")) return 600;
  if (normalized.includes("extrabold") || normalized.includes("ultrabold")) return 800;
  if (normalized.includes("black") || normalized.includes("heavy")) return 900;
  if (normalized.includes("bold")) return 700;
  if (normalized.includes("medium")) return 500;
  if (normalized.includes("regular") || normalized.includes("book") || normalized === "normal")
    return 400;
  return undefined;
}

function TextInnerShadowDefs({ id, shadows }: { id: string; shadows: InnerShadow[] }) {
  return (
    <svg
      aria-hidden="true"
      width="0"
      height="0"
      style={{ position: "absolute", width: 0, height: 0, overflow: "hidden" }}
    >
      <defs>
        <filter
          id={id}
          x="-1"
          y="-1"
          width="3"
          height="3"
          filterUnits="objectBoundingBox"
          colorInterpolationFilters="sRGB"
        >
          {shadows.map((shadow, index) => (
            <Fragment key={index}>
              <feGaussianBlur
                in="SourceAlpha"
                stdDeviation={shadow.blur / 2}
                result={`text-shadow-blur-${index}`}
              />
              <feOffset
                in={`text-shadow-blur-${index}`}
                dx={shadow.x}
                dy={shadow.y}
                result={`text-shadow-offset-${index}`}
              />
              <feComposite
                in="SourceAlpha"
                in2={`text-shadow-offset-${index}`}
                operator="out"
                result={`text-shadow-diff-${index}`}
              />
              <feFlood floodColor={shadow.color} result={`text-shadow-color-${index}`} />
              <feComposite
                in={`text-shadow-color-${index}`}
                in2={`text-shadow-diff-${index}`}
                operator="in"
                result={`text-shadow-inner-${index}`}
              />
            </Fragment>
          ))}
          <feMerge>
            {shadows.map((_, index) => (
              <feMergeNode key={`shadow-${index}`} in={`text-shadow-inner-${index}`} />
            ))}
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
    </svg>
  );
}

function textInnerShadowFilterId(nodeId: string | undefined, shadows: InnerShadow[]): string {
  const seed = `${nodeId ?? "anonymous"}:${JSON.stringify(shadows)}`;
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const safeNodeId = (nodeId ?? "anonymous").replace(/[^a-zA-Z0-9_-]/g, "-");
  return `lumencast-text-inner-${safeNodeId}-${(hash >>> 0).toString(16)}`;
}

interface TextOutline {
  characters: string;
  size: { w: number; h: number };
  paths: { data: string; fillRule: "nonzero" | "evenodd" }[];
}

/** Validate the optional static glyph outline at the same render boundary as
 *  ordinary shape paths. Live deltas can bypass the compiler, so the path
 *  grammar and caps are enforced again here before any `d` reaches the DOM. */
function resolveTextOutline(
  value: unknown,
  displayed: string,
  nodeId?: string,
): TextOutline | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
  const source = value as { characters?: unknown; size?: unknown; paths?: unknown };
  if (typeof source.characters !== "string" || source.characters.length > MAX_TEXT_OUTLINE_CHARS) {
    emitDiagnostic(nodeId, "text.textOutline.characters", "rejected static glyph outline text");
    return null;
  }
  // The outline is only authoritative for the captured literal. A bound value
  // must remain font-backed and editable when it changes at runtime.
  if (source.characters !== displayed) return null;
  if (typeof source.size !== "object" || source.size === null || Array.isArray(source.size)) {
    emitDiagnostic(nodeId, "text.textOutline.size", "rejected static glyph outline dimensions");
    return null;
  }
  const size = source.size as { w?: unknown; h?: unknown };
  if (
    !finiteBounded(size.w, MAX_TEXT_OUTLINE_DIMENSION) ||
    !finiteBounded(size.h, MAX_TEXT_OUTLINE_DIMENSION) ||
    size.w <= 0 ||
    size.h <= 0
  ) {
    emitDiagnostic(nodeId, "text.textOutline.size", "rejected static glyph outline dimensions");
    return null;
  }
  if (!Array.isArray(source.paths) || source.paths.length === 0) {
    emitDiagnostic(nodeId, "text.textOutline.paths", "rejected empty static glyph outline");
    return null;
  }
  if (source.paths.length > MAX_TEXT_OUTLINE_PATHS) {
    emitDiagnostic(nodeId, "text.textOutline.paths", "rejected oversized static glyph outline");
    return null;
  }

  const paths: TextOutline["paths"] = [];
  for (let index = 0; index < source.paths.length; index++) {
    const rawPath = source.paths[index];
    if (typeof rawPath !== "object" || rawPath === null || Array.isArray(rawPath)) {
      emitDiagnostic(nodeId, `text.textOutline.paths[${index}]`, "rejected malformed glyph path");
      return null;
    }
    const path = rawPath as { data?: unknown; windingRule?: unknown };
    const data = validatePathData(path.data);
    if (data === null) {
      emitDiagnostic(
        nodeId,
        `text.textOutline.paths[${index}].data`,
        "rejected invalid glyph path",
      );
      return null;
    }
    const fillRule =
      path.windingRule === undefined
        ? "nonzero"
        : path.windingRule === "NONZERO"
          ? "nonzero"
          : path.windingRule === "EVENODD"
            ? "evenodd"
            : null;
    if (fillRule === null) {
      emitDiagnostic(
        nodeId,
        `text.textOutline.paths[${index}].windingRule`,
        "rejected invalid glyph winding rule",
      );
      return null;
    }
    paths.push({ data, fillRule });
  }
  return { characters: source.characters, size: { w: size.w, h: size.h }, paths };
}

function finiteBounded(value: unknown, limit: number): value is number {
  return typeof value === "number" && Number.isFinite(value) && Math.abs(value) <= limit;
}

function numberOr(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

function finitePositive(v: unknown): number | undefined {
  return typeof v === "number" && Number.isFinite(v) && v > 0 ? v : undefined;
}

/** Render Figma's lowered text paint array as a clipped CSS background.
 * Image fills are intentionally rejected here because text paint metadata has
 * no trusted image-source contract; frame/shape fills own that gate. */
function resolveTextFills(
  value: unknown,
  nodeId?: string,
  boxSize: { boxWidth?: number; boxHeight?: number } = {},
): CSSProperties {
  const parsed = parseFills(value, "text.textFills", nodeId);
  const nonImage = parsed.filter((fill): fill is Exclude<Fill, { kind: "image" }> => {
    if (fill.kind !== "image") return true;
    emitDiagnostic(
      nodeId,
      "text.textFills.kind",
      "image fills are not supported for text paint arrays; layer dropped",
    );
    return false;
  });
  return backgroundsToCss(sanitizeFills(nonImage, "text.textFills", nodeId), nodeId, boxSize);
}

/** Render the Figma-only vertical text-box alignment retained in metadata. */
export function resolveTextVerticalLayout(
  resolved: Record<string, unknown>,
  align: string,
  nodeId?: string,
): React.CSSProperties {
  const vertical = resolved.textAlignVertical;
  if (vertical === undefined) return {};
  if (vertical !== "TOP" && vertical !== "CENTER" && vertical !== "BOTTOM") {
    emitDiagnostic(
      nodeId,
      "text.textAlignVertical",
      "rejected vertical alignment : expected TOP, CENTER, or BOTTOM",
    );
    return {};
  }
  const height = resolved.height;
  if (typeof height !== "number" || !Number.isFinite(height) || height <= 0) return {};
  const width = resolved.width;

  const justifyContent =
    align === "center"
      ? "center"
      : align === "end" || align === "right"
        ? "flex-end"
        : "flex-start";
  return {
    display: "flex",
    // Preserve Figma's fixed-box baseline rounding for fractional heights.
    position: "relative",
    top: "1px",
    // The text primitive can sit directly in an auto-layout frame. In that
    // case there is no sized universal wrapper to provide the containing box;
    // `100%` would resolve against the parent frame (the footer headings were
    // expanding to 236px instead of their authored 30px box). Keep the exact
    // Figma dimensions on the leaf. For an absolutely placed text node these
    // dimensions equal the wrapper's box, so the same rule covers both paths.
    ...(typeof width === "number" && Number.isFinite(width) && width > 0 ? { width } : {}),
    height,
    alignItems:
      vertical === "CENTER" ? "center" : vertical === "BOTTOM" ? "flex-end" : "flex-start",
    justifyContent,
  };
}

/**
 * Resolve the LSML 1.1 TextStyle typography props (`lineHeight`,
 * `letterSpacing`, `textTransform`, `textDecoration`, `fontStyle`) and
 * `maxLines` (§4.4) into a validated React style fragment.
 *
 * Exported for boundary testing : happy-dom drops `-webkit-*`
 * declarations from `CSSStyleDeclaration`, so the line-clamp pattern is
 * asserted on the exact object handed to React's inline style (same
 * approach as `backgroundsToCss` for `color-mix`).
 *
 * Defaults = omit the declaration (inherit / CSS initial). A
 * non-conforming value → R9 diagnostic + omit ; the returned object
 * only ever contains allowlisted constants or validated finite
 * numbers — never the raw input. Numeric fields additionally enforce
 * the defence-in-depth caps above (issue #34).
 */
export function resolveTypography(
  resolved: Record<string, unknown>,
  nodeId?: string,
): React.CSSProperties {
  // schema.json : lineHeight is a unitless multiplier ≥ 0 ;
  // letterSpacing is a number (px) ; the three enums are closed sets.
  const lineHeight = boundedNumber(
    resolved.lineHeight,
    0,
    MAX_LINE_HEIGHT,
    "text.lineHeight",
    nodeId,
  );
  const letterSpacing = boundedNumber(
    resolved.letterSpacing,
    -MAX_LETTER_SPACING_PX,
    MAX_LETTER_SPACING_PX,
    "text.letterSpacing",
    nodeId,
  );
  const textTransform = enumValue(
    resolved.textTransform,
    TEXT_TRANSFORMS,
    "text.textTransform",
    nodeId,
  );
  const textDecoration = enumValue(
    resolved.textDecoration,
    TEXT_DECORATIONS,
    "text.textDecoration",
    nodeId,
  );
  const fontStyle = enumValue(resolved.fontStyle, FONT_STYLES, "text.fontStyle", nodeId);
  // §4.4 maxLines — truncation with ellipsis after N lines, via the
  // standard line-clamp pattern (display:-webkit-box overrides the
  // base inline-block ; this fragment is spread after it so it wins).
  const maxLines = positiveInteger(resolved.maxLines, MAX_MAX_LINES, "text.maxLines", nodeId);

  return {
    ...(lineHeight !== undefined ? { lineHeight } : {}),
    // Built from a validated finite number — no string passthrough.
    ...(letterSpacing !== undefined ? { letterSpacing: `${letterSpacing}px` } : {}),
    ...(textTransform !== undefined
      ? { textTransform: textTransform as React.CSSProperties["textTransform"] }
      : {}),
    ...(textDecoration !== undefined ? { textDecoration } : {}),
    ...(fontStyle !== undefined ? { fontStyle } : {}),
    ...(maxLines !== undefined
      ? {
          display: "-webkit-box",
          WebkitBoxOrient: "vertical" as const,
          WebkitLineClamp: maxLines,
          overflow: "hidden",
          textOverflow: "ellipsis",
        }
      : {}),
  };
}

/** Closed-allowlist enum gate. Returns the canonical constant from the
 *  allowlist (NEVER the raw input) or `undefined` (field omitted →
 *  CSS initial). Non-conforming value → R9 diagnostic, no passthrough. */
function enumValue(
  v: unknown,
  allow: ReadonlySet<string>,
  field: string,
  nodeId?: string,
): string | undefined {
  if (v === undefined) return undefined;
  if (typeof v === "string" && allow.has(v)) return v;
  warnRejectedTypo(field, nodeId);
  return undefined;
}

/** Finite number within [min, max] or omit (R9 diagnostic on a
 *  non-conforming or out-of-cap input — rejected, never clamped). */
function boundedNumber(
  v: unknown,
  min: number,
  max: number,
  field: string,
  nodeId?: string,
): number | undefined {
  if (v === undefined) return undefined;
  if (typeof v === "number" && Number.isFinite(v) && v >= min && v <= max) return v;
  warnRejectedTypo(field, nodeId);
  return undefined;
}

/** Integer in [1, max] or omit (schema : maxLines is a line count ;
 *  capped per the issue #34 defence-in-depth bounds). */
function positiveInteger(
  v: unknown,
  max: number,
  field: string,
  nodeId?: string,
): number | undefined {
  if (v === undefined) return undefined;
  if (typeof v === "number" && Number.isInteger(v) && v >= 1 && v <= max) return v;
  warnRejectedTypo(field, nodeId);
  return undefined;
}

/**
 * Diagnostic for a typo value outside its spec'd grammar or caps.
 * Bastion R9 (ADR 001 §5.1) : the rejected VALUE is never logged nor
 * forwarded — only `node.id` (RC#7), the field name and a static
 * reason. Routed through the structured diagnostics channel.
 */
function warnRejectedTypo(field: string, nodeId?: string): void {
  emitDiagnostic(
    nodeId,
    field,
    "rejected typography value : outside the field's spec'd grammar or caps",
  );
}
