import { useEffect, useRef, useState } from "react";
import { useOptionalLumencastRuntime } from "../../overlay/runtime-context";

/** Shared LIVE peer-stream rendering (ADR 006 §3.3/§3.5) — the SINGLE srcObject
 *  path used by BOTH the `media` primitive's live mode (#4, keyed on `peerLabel`)
 *  AND the generic `meet.peer` source kind (the unified source abstraction).
 *  There is no special renderer per source : every live source resolves
 *  `peerLabel → MediaStream` through the host viewer and paints it the same way.
 *
 *  Resolution : prefer the reactive channel (`subscribePeerStream`, #3) so a node
 *  mounted BEFORE its peer connects re-renders on arrival ; fall back to the
 *  one-shot `resolvePeerStream` (#4 contract) ; no host resolver → stream-less
 *  box. Reading a stream is the ONLY side effect — the scene is never mutated
 *  (RC-ReadOnly).
 *
 *  Geometry (RC-Geo) : the `<video>` fills `100%`/`100%` of the box the Tree's
 *  UniversalWrapper sized from the node's `x/y/width/height`. The geometry lives
 *  on the wrapper, NEVER on the video, so it is structurally impossible to force
 *  a full-viewport size ; `object-fit` is the scene-authored value.
 *
 *  Ownership : the stream is owned by the viewer (#3). This component is a pure
 *  consumer — unmounting clears its own `srcObject` and stops NO track (a mirror
 *  must never tear a peer down for the on-air composite). */
export function LivePeerVideo({
  peerLabel,
  objectFit,
  muted,
}: {
  peerLabel: string;
  objectFit: string;
  /** Explicit playout override. When set, it WINS (a node can force a local
   *  mute for its own reason). When left undefined (the normal case), the mute
   *  state is decided by the host via `runtime.liveAudio` : muted UNLESS the
   *  host declared it is the flux réellement diffusé/enregistré. */
  muted?: boolean;
}) {
  const runtime = useOptionalLumencastRuntime();
  const resolvePeerStream = runtime?.resolvePeerStream;
  const subscribePeerStream = runtime?.subscribePeerStream;
  // A guest peer's audio lives ONLY inside its WebRTC `MediaStreamTrack` on this
  // page — there is no native Pulsar/OBS audio device for a remote peer (unlike
  // a local webcam, whose mic is a separate native Audio Input source). Muting
  // this element therefore deletes that audio from the on-air / recording mix
  // for good. So we mute by DEFAULT and only un-mute when the host explicitly
  // opts in via `liveAudio` — a host that KNOWS it is the on-air / REC render
  // (the antenne, the test-REC, the Pulsar CEF atlas). It must NEVER be set on
  // an interactive preview/editor host (the operator may have the same ZabCam
  // room open elsewhere → audio feedback / echo). An explicit `muted` prop
  // still wins over this default. See `MountOptions.liveAudio`.
  const isMuted = muted ?? !runtime?.liveAudio;

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    if (subscribePeerStream !== undefined) {
      return subscribePeerStream(peerLabel, setStream);
    }
    if (resolvePeerStream !== undefined) {
      setStream(resolvePeerStream(peerLabel));
      return;
    }
    setStream(null);
  }, [peerLabel, resolvePeerStream, subscribePeerStream]);

  // `srcObject` is not a serialisable attribute — attach imperatively. Never
  // stop the tracks here (the viewer owns them).
  useEffect(() => {
    const el = videoRef.current;
    if (el === null) return;
    el.srcObject = stream;
    return () => {
      if (el !== null) el.srcObject = null;
    };
  }, [stream]);

  // Autoplay policy : Chromium's headless CEF (Pulsar) has NO user gesture, so a
  // `<video autoPlay>` that is NON-muted at first render has its internal
  // `.play()` REJECTED silently — the element freezes, not a single frame paints.
  // The element therefore ALWAYS renders `muted` (JSX below is hard `true`) so
  // autoplay is always permitted ; we flip `el.muted` to the wanted value
  // imperatively once the element exists. Un-muting an element that is ALREADY
  // playing is NOT blocked by the autoplay policy (unlike a first `.play()` on a
  // non-muted element). Re-runs on `isMuted` change so a live `liveAudio` toggle
  // is reflected without re-rendering the element (which would restart autoplay).
  useEffect(() => {
    const el = videoRef.current;
    if (el === null) return;
    el.muted = isMuted;
  }, [isMuted, stream]);

  if (stream === null) {
    // Stream-less box of the wrapper geometry — transparent, inert, paints
    // nothing. NOT an error : the peer can connect mid-show.
    return (
      <div
        aria-hidden
        data-lumencast-media-live
        style={{ width: "100%", height: "100%", opacity: 0, pointerEvents: "none" }}
      />
    );
  }

  return (
    <video
      ref={videoRef}
      data-lumencast-media-live
      autoPlay
      // ALWAYS muted at first render so Chromium's autoplay policy permits
      // playback with no user gesture (headless CEF). NEVER drive this from
      // `isMuted` — the real mute state is applied imperatively via the effect
      // above once the element is playing. See the effect's comment.
      muted
      playsInline
      style={{
        width: "100%",
        height: "100%",
        objectFit: objectFit as React.CSSProperties["objectFit"],
        pointerEvents: "none",
      }}
    />
  );
}
