import type { EncodedRasterSource } from "./image-raster";

interface RasterEntry {
  promise: Promise<EncodedRasterSource>;
  references: number;
  settled: boolean;
  raster?: EncodedRasterSource;
}

export interface SharedRasterLease {
  /** A per-consumer view whose release drops only this consumer's reference. */
  promise: Promise<EncodedRasterSource>;
  release(): void;
}

const entries = new Map<string, RasterEntry>();

/**
 * Share an in-flight or retained raster for consumers of the same source and
 * raster settings. The result stays alive only while at least one mounted
 * consumer holds a lease; the final release revokes its Blob URL.
 */
export function acquireSharedRaster(
  key: string,
  create: () => Promise<EncodedRasterSource>,
): SharedRasterLease {
  let entry = entries.get(key);
  if (entry === undefined) {
    let resolveRaster!: (raster: EncodedRasterSource) => void;
    let rejectRaster!: (reason: unknown) => void;
    const promise = new Promise<EncodedRasterSource>((resolve, reject) => {
      resolveRaster = resolve;
      rejectRaster = reject;
    });
    const created: RasterEntry = { promise, references: 0, settled: false };
    entry = created;
    entries.set(key, created);

    void Promise.resolve()
      .then(create)
      .then(
        (raster) => {
          created.raster = raster;
          created.settled = true;
          releaseIfUnused(key, created);
          resolveRaster(raster);
        },
        (reason: unknown) => {
          created.settled = true;
          if (entries.get(key) === created) entries.delete(key);
          rejectRaster(reason);
        },
      );
  }

  entry.references += 1;
  let released = false;
  const release = (): void => {
    if (released) return;
    released = true;
    entry.references -= 1;
    releaseIfUnused(key, entry);
  };
  const leasePromise = entry.promise.then((raster) => ({
    src: raster.src,
    ...(raster.fallbackToDataUrl !== undefined
      ? { fallbackToDataUrl: raster.fallbackToDataUrl }
      : {}),
    release,
  }));

  return { promise: leasePromise, release };
}

function releaseIfUnused(key: string, entry: RasterEntry): void {
  if (!entry.settled || entry.references !== 0) return;
  if (entries.get(key) === entry) entries.delete(key);
  const raster = entry.raster;
  entry.raster = undefined;
  try {
    raster?.release?.();
  } catch {
    // Cleanup must not turn an already-resolved raster into a rejected render.
  }
}
