import { emitDiagnostic } from "./diagnostics";

/** Figma IMAGE-paint adjustment channels. Values are authored in [-1, 1]. */
export interface ImageFilters {
  exposure?: number;
  contrast?: number;
  saturation?: number;
  temperature?: number;
  tint?: number;
  highlights?: number;
  shadows?: number;
}

const CHANNELS = [
  "exposure",
  "contrast",
  "saturation",
  "temperature",
  "tint",
  "highlights",
  "shadows",
] as const;

type ImageFilterChannel = (typeof CHANNELS)[number];

/** Runtime half of the image-paint filter gate. Live bundles can bypass the
 * compiler, so every channel is revalidated before it influences CSS. */
export function readImageFilters(value: unknown, nodeId?: string): ImageFilters | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    emitDiagnostic(
      nodeId,
      "image.imageFilters",
      "rejected value : expected a bounded channel object",
    );
    return undefined;
  }
  const raw = value as Record<string, unknown>;
  const out: ImageFilters = {};
  for (const channel of CHANNELS) {
    const candidate = raw[channel];
    if (candidate === undefined) continue;
    if (typeof candidate !== "number" || !Number.isFinite(candidate)) {
      warnRejectedImageFilter(channel, nodeId);
      continue;
    }
    out[channel] = Math.max(-1, Math.min(1, candidate));
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

/**
 * Map the typed Figma adjustment channels to the browser's bounded filter
 * primitives. Figma's IMAGE `tint` is a green↔magenta correction; Chrome has
 * no native tint() primitive, so the stable approximation combines its
 * luminance compensation with a saturation reduction. The other channels map
 * directly to their CSS counterparts and remain deterministic across renders.
 */
export function imageFiltersToCss(filters: ImageFilters | undefined): string | undefined {
  if (!filters) return undefined;
  const css: string[] = [];
  const exposure = filters.exposure ?? 0;
  if (exposure !== 0) css.push(`brightness(${format(2 ** exposure)})`);

  const tint = filters.tint ?? 0;
  if (tint !== 0) {
    // Positive Figma tint moves green toward magenta. The luminance
    // compensation follows the adjustment's authored strength rather than a
    // scene-specific constant, so every image paint uses the same rule.
    const brightness = 1 - 0.9 * Math.max(tint, 0) + 0.2 * Math.min(tint, 0);
    const saturation = 1 - 0.5 * Math.abs(tint);
    css.push(`brightness(${format(Math.max(0.1, brightness))})`);
    css.push(`saturate(${format(Math.max(0, saturation))})`);
  }

  const contrast = filters.contrast ?? 0;
  if (contrast !== 0) css.push(`contrast(${format(Math.max(0, 1 + contrast))})`);
  const saturation = filters.saturation ?? 0;
  if (saturation !== 0) css.push(`saturate(${format(Math.max(0, 1 + saturation))})`);

  const temperature = filters.temperature ?? 0;
  if (temperature !== 0) {
    css.push(`sepia(${format(0.25 * Math.abs(temperature))})`);
    css.push(`hue-rotate(${format(-30 * temperature)}deg)`);
  }

  // Highlights/shadows are a tonal split in Figma. CSS has no split-tone
  // primitive; a bounded contrast/brightness pair keeps the direction of the
  // authored adjustment without emitting an unsafe free-form filter.
  const highlights = filters.highlights ?? 0;
  if (highlights !== 0) css.push(`contrast(${format(Math.max(0, 1 - 0.2 * highlights))})`);
  const shadows = filters.shadows ?? 0;
  if (shadows !== 0) css.push(`brightness(${format(Math.max(0.1, 1 + 0.25 * shadows))})`);

  return css.length > 0 ? css.join(" ") : undefined;
}

function format(value: number): string {
  return Number(value.toFixed(4)).toString();
}

function warnRejectedImageFilter(channel: ImageFilterChannel, nodeId?: string): void {
  emitDiagnostic(
    nodeId,
    `image.imageFilters.${channel}`,
    "rejected value : expected a finite channel in the interval [-1, 1]",
  );
}
