// Per-frame delta coalescing (ADR 001 RC#13 — bindAnimate anti-DoS).
//
// A live LSDP producer may push deltas at arbitrary frequency (the
// threat model assumes 1 kHz). Retargeting a Framer animation per delta
// would start hundreds of redundant animations per displayed frame. The
// coalescer buffers the LATEST value per binding key and flushes once
// per animation frame : one retarget max per rAF per binding,
// independently of the producer's rate.
//
// Pure scheduling logic, injectable rAF — unit-testable without a
// browser loop.

export interface FrameCoalescer {
  /** Buffer `value` for `key` ; schedules a flush on the next frame.
   *  Multiple pushes on the same key within one frame keep only the
   *  last value (the previous targets are obsolete by construction). */
  push(key: string, value: unknown): void;
  /** Cancel any scheduled flush and drop pending values. */
  dispose(): void;
}

type Schedule = (cb: () => void) => number;
type Cancel = (id: number) => void;

export function createFrameCoalescer(
  flush: (key: string, value: unknown) => void,
  schedule: Schedule = (cb) => requestAnimationFrame(cb),
  cancel: Cancel = (id) => cancelAnimationFrame(id),
): FrameCoalescer {
  let pending = new Map<string, unknown>();
  let spare: Map<string, unknown> | null = null;
  let deferred: Map<string, unknown> | null = null;
  let frameId: number | null = null;
  let disposed = false;
  let flushing = false;

  const dispatch = (value: unknown, key: string): void => flush(key, value);

  const onFrame = (): void => {
    frameId = null;
    // Flush the current map directly, without allocating a copied entries
    // array. Re-entrant pushes use a secondary map, so they still schedule
    // the NEXT frame instead of extending the batch being flushed.
    const entries = pending;
    flushing = true;
    try {
      entries.forEach(dispatch);
    } finally {
      flushing = false;
      entries.clear();
      if (deferred !== null && deferred.size > 0) {
        pending = deferred;
        deferred = null;
        spare = entries;
      } else {
        pending = entries;
        deferred = null;
        spare = null;
      }
    }
  };

  return {
    push(key, value): void {
      if (disposed) return;
      const target = flushing ? (deferred ??= spare ?? new Map<string, unknown>()) : pending;
      target.set(key, value);
      if (frameId === null) {
        frameId = schedule(onFrame);
      }
    },
    dispose(): void {
      disposed = true;
      // The active map is still being iterated. Leave that in-flight batch
      // intact, but drop any work queued for a later frame.
      if (!flushing) pending.clear();
      deferred?.clear();
      spare?.clear();
      if (frameId !== null) {
        cancel(frameId);
        frameId = null;
      }
    },
  };
}
