export interface EncodedRasterSource {
  src: string;
  release?: () => void;
  fallbackToDataUrl?: () => string;
}

const PACKED_RGBA_LITTLE_ENDIAN = new Uint8Array(new Uint32Array([1]).buffer)[0] === 1;
const PACKED_CHANNEL_MASK = 0x00ff00ff;
const PACKED_HALF_UP = 0x00020002;

/** Same-origin HTTP images can be safely read from the visible <img> itself. */
export function isSameOriginRasterSource(src: string, origin: string): boolean {
  try {
    const pageUrl = new URL(origin);
    const sourceUrl = new URL(src, pageUrl);
    return (
      (sourceUrl.protocol === "http:" || sourceUrl.protocol === "https:") &&
      sourceUrl.origin === pageUrl.origin
    );
  } catch {
    return false;
  }
}

/** Encode raster pixels without synchronously base64-encoding on the mount path. */
export async function encodeRasterCanvas(canvas: HTMLCanvasElement): Promise<EncodedRasterSource> {
  if (typeof canvas.toBlob !== "function" || typeof URL.createObjectURL !== "function") {
    return { src: canvas.toDataURL("image/png") };
  }

  let blob: Blob | null;
  try {
    blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
  } catch {
    blob = null;
  }
  if (blob === null) return { src: canvas.toDataURL("image/png") };

  let src: string;
  try {
    src = URL.createObjectURL(blob);
  } catch {
    return { src: canvas.toDataURL("image/png") };
  }

  let released = false;
  return {
    src,
    release: () => {
      if (released) return;
      released = true;
      URL.revokeObjectURL(src);
    },
    // Some embedding pages allow `data:` but not `blob:` in img-src. If the
    // generated URL is blocked, preserve the existing exact-render fallback.
    fallbackToDataUrl: () => canvas.toDataURL("image/png"),
  };
}

/**
 * Apply Figma's exact 2×2 box reduction to RGBA image data.
 *
 * Keep this arithmetic byte-identical to Math.round(the four source samples / 4)
 * while avoiding the per-pixel channel loop in the image mount hot path.
 */
export function downsample2x2Rgba(
  source: Uint8ClampedArray,
  sourceWidth: number,
  sourceHeight: number,
  target: Uint8ClampedArray,
): void {
  const targetWidth = sourceWidth / 2;
  const targetHeight = sourceHeight / 2;
  if (
    !Number.isSafeInteger(sourceWidth) ||
    !Number.isSafeInteger(sourceHeight) ||
    sourceWidth <= 0 ||
    sourceHeight <= 0 ||
    sourceWidth % 2 !== 0 ||
    sourceHeight % 2 !== 0 ||
    source.length !== sourceWidth * sourceHeight * 4 ||
    target.length !== targetWidth * targetHeight * 4
  ) {
    throw new RangeError("2×2 image reduction requires matching even-sized RGBA buffers");
  }

  const sourceEnd = source.byteOffset + source.byteLength;
  const targetEnd = target.byteOffset + target.byteLength;
  const overlaps =
    source.buffer === target.buffer &&
    source.byteOffset < targetEnd &&
    target.byteOffset < sourceEnd;
  if (
    PACKED_RGBA_LITTLE_ENDIAN &&
    source.byteOffset % 4 === 0 &&
    target.byteOffset % 4 === 0 &&
    !overlaps
  ) {
    // Pack R/B and G/A into separate 16-bit lanes. The sum of four 8-bit
    // samples plus the half-up rounding bias fits in each lane, so the two
    // lanes can be shifted together without cross-channel carries.
    const sourceWords = new Uint32Array(source.buffer, source.byteOffset, source.length / 4);
    const targetWords = new Uint32Array(target.buffer, target.byteOffset, target.length / 4);
    for (let y = 0; y < targetHeight; y += 1) {
      const topRowOffset = y * sourceWidth * 2;
      const bottomRowOffset = topRowOffset + sourceWidth;
      const targetRowOffset = y * targetWidth;
      for (let x = 0; x < targetWidth; x += 1) {
        const sourceOffset = topRowOffset + x * 2;
        const topLeft = sourceWords[sourceOffset]!;
        const topRight = sourceWords[sourceOffset + 1]!;
        const bottomLeft = sourceWords[bottomRowOffset + x * 2]!;
        const bottomRight = sourceWords[bottomRowOffset + x * 2 + 1]!;
        const redBlue =
          ((topLeft & PACKED_CHANNEL_MASK) +
            (topRight & PACKED_CHANNEL_MASK) +
            (bottomLeft & PACKED_CHANNEL_MASK) +
            (bottomRight & PACKED_CHANNEL_MASK) +
            PACKED_HALF_UP) >>
          2;
        const greenAlpha =
          (((topLeft >>> 8) & PACKED_CHANNEL_MASK) +
            ((topRight >>> 8) & PACKED_CHANNEL_MASK) +
            ((bottomLeft >>> 8) & PACKED_CHANNEL_MASK) +
            ((bottomRight >>> 8) & PACKED_CHANNEL_MASK) +
            PACKED_HALF_UP) >>
          2;
        targetWords[targetRowOffset + x] =
          ((redBlue & PACKED_CHANNEL_MASK) | ((greenAlpha & PACKED_CHANNEL_MASK) << 8)) >>> 0;
      }
    }
    return;
  }

  // Portable path for big-endian platforms, unaligned views, or overlapping
  // buffers; retain the original per-channel byte semantics in those cases.
  const sourceStride = sourceWidth * 4;
  const targetStride = targetWidth * 4;
  for (let y = 0; y < targetHeight; y += 1) {
    let sourceOffset = y * sourceStride * 2;
    let targetOffset = y * targetStride;
    const lowerRowOffset = sourceOffset + sourceStride;
    for (let x = 0; x < targetWidth; x += 1) {
      const lowerOffset = lowerRowOffset + x * 8;
      target[targetOffset] =
        (source[sourceOffset]! +
          source[sourceOffset + 4]! +
          source[lowerOffset]! +
          source[lowerOffset + 4]! +
          2) >>
        2;
      target[targetOffset + 1] =
        (source[sourceOffset + 1]! +
          source[sourceOffset + 5]! +
          source[lowerOffset + 1]! +
          source[lowerOffset + 5]! +
          2) >>
        2;
      target[targetOffset + 2] =
        (source[sourceOffset + 2]! +
          source[sourceOffset + 6]! +
          source[lowerOffset + 2]! +
          source[lowerOffset + 6]! +
          2) >>
        2;
      target[targetOffset + 3] =
        (source[sourceOffset + 3]! +
          source[sourceOffset + 7]! +
          source[lowerOffset + 3]! +
          source[lowerOffset + 7]! +
          2) >>
        2;
      sourceOffset += 8;
      targetOffset += 4;
    }
  }
}
