import { motion } from "framer-motion";
import { useEffect, useRef, useState } from "react";
import type { PrimitiveProps } from "./index";
import { toFramer, mountPlay, resolveTransition } from "../../animate/transitions";
import { gateSrc, useAllowedHosts, useHostAssetPolicy } from "../allowed-hosts";
import { emitDiagnostic } from "../diagnostics";
import { buildShadowCss } from "../shadow-css";
import { imageFiltersToCss, readImageFilters } from "../image-filters";
import { acquireSharedRaster } from "../raster-cache";
import {
  downsample2x2Rgba,
  encodeRasterCanvas,
  isSameOriginRasterSource,
  type EncodedRasterSource,
} from "../image-raster";

interface ScaledImageSource extends EncodedRasterSource {
  input: string;
  factor: number;
}

/** Image leaf. `src`, `fit` (cover/contain/fill), `position`,
 *  `opacity`. Opacity is animated when a transition is declared. When an
 *  `animate.from` is lowered onto the node, it mounts at that state and
 *  plays to its target on mount (mount-play).
 *
 *  Security (Bastion T1/T2, ADR 002 #F) : `src` is untrusted (static prop
 *  OR live LSDP delta) and was placed into the DOM with NO host/scheme
 *  check until #F (the latent 1.1 hole — `assets.allowedHosts` was declared
 *  but never enforced). It now passes `gateSrc` BEFORE reaching the `<img>`
 *  — a rejected host/scheme omits the image entirely (no passthrough), with
 *  an R9-clean diagnostic. This is the runtime arm of the double-gate. */
export function Image({
  resolved,
  nodeId,
  transitionFor,
  animateInitial,
  staticRender = false,
}: PrimitiveProps) {
  const allowedHosts = useAllowedHosts();
  const isHostAssetUrl = useHostAssetPolicy();
  const src = gateSrc(resolved.src, allowedHosts, "image.src", nodeId, isHostAssetUrl);
  const imageScaleFactor = readImageScaleFactor(resolved.imageScaleFactor, nodeId);
  const imageRef = useRef<HTMLImageElement>(null);
  const [scaledImage, setScaledImage] = useState<ScaledImageSource | undefined>(undefined);
  const activeScaledImage =
    scaledImage && scaledImage.input === src && scaledImage.factor === imageScaleFactor
      ? scaledImage
      : undefined;

  // Figma's IMAGE `scalingFactor` is a raster-resolution hint, not a visual
  // transform. Pre-rasterise into a bounded canvas so the node keeps the same
  // geometry while its source pixels match the authored resolution. Reuse the
  // visible image for same-origin sources; cross-origin sources retain a
  // CORS-enabled preloader so a tainted canvas safely falls back to the source.
  // An invalid factor is rejected by readImageScaleFactor before this hook.
  useEffect(() => {
    let cancelled = false;
    let releaseScaledImage: (() => void) | undefined;
    let corsSource: HTMLImageElement | undefined;
    if (!src || imageScaleFactor === 1) {
      setScaledImage(undefined);
      return () => {
        cancelled = true;
      };
    }

    setScaledImage(undefined);
    const rasterizeLoadedImage = (source: HTMLImageElement) => {
      if (cancelled) return;
      const width = Math.max(1, Math.round(source.naturalWidth * imageScaleFactor));
      const height = Math.max(1, Math.round(source.naturalHeight * imageScaleFactor));
      const key = JSON.stringify([src, imageScaleFactor]) ?? "";
      const lease = acquireSharedRaster(key, () =>
        rasterizeImage(source, imageScaleFactor, width, height),
      );
      releaseScaledImage = lease.release;
      void lease.promise
        .then((raster) => {
          if (cancelled) {
            raster.release?.();
            return;
          }
          setScaledImage({ ...raster, input: src, factor: imageScaleFactor });
        })
        .catch(() => {
          // A remote asset without CORS permission cannot be read back. The
          // source image remains a safe, visually useful fallback.
        });
    };

    const loadCorsSource = () => {
      const source = new window.Image();
      corsSource = source;
      source.decoding = "async";
      source.crossOrigin = "anonymous";
      source.onload = () => rasterizeLoadedImage(source);
      source.src = src;
      return source;
    };

    const visibleImage = imageRef.current;
    if (visibleImage && isSameOriginRasterSource(src, window.location.origin)) {
      const rasterizeVisibleImage = () => {
        if (cancelled || visibleImage.getAttribute("src") !== src) return;
        if (!isSameOriginRasterSource(visibleImage.currentSrc, window.location.origin)) {
          loadCorsSource();
          return;
        }
        rasterizeLoadedImage(visibleImage);
      };
      if (visibleImage.complete) {
        if (visibleImage.naturalWidth > 0) rasterizeVisibleImage();
      } else {
        visibleImage.addEventListener("load", rasterizeVisibleImage, { once: true });
      }
      return () => {
        cancelled = true;
        visibleImage.removeEventListener("load", rasterizeVisibleImage);
        if (corsSource) {
          corsSource.onload = null;
          corsSource.onerror = null;
        }
        releaseScaledImage?.();
      };
    }

    const source = loadCorsSource();
    return () => {
      cancelled = true;
      source.onload = null;
      source.onerror = null;
      releaseScaledImage?.();
    };
  }, [src, imageScaleFactor]);

  if (!src) return null;
  // LSML §4.5 `alt` is required and was silently unrendered until
  // issue #34's allowlist audit surfaced it — now forwarded to the DOM.
  const alt = typeof resolved.alt === "string" ? resolved.alt : "";
  const fit = (resolved.fit as string | undefined) ?? "contain";
  const position = (resolved.position as string | undefined) ?? "center";
  const opacity = numberOr(resolved.opacity, 1);
  // `width`/`height` carry LSML image.size (compiler maps size.w/.h → width/height).
  // When present, honour the intrinsic image dimensions; otherwise fill the
  // container (the prior behaviour — a sized parent drives the layout).
  const width = dimOr(resolved.width, "100%");
  const height = dimOr(resolved.height, "100%");
  const imageTransform = readImageTransform(resolved.imageTransform, nodeId, width, height);
  const shadow = buildShadowCss(resolved.shadow, nodeId, "image.shadow.color");
  const imageFilter = imageFiltersToCss(readImageFilters(resolved.imageFilters, nodeId));
  const filter = [imageFilter, shadow.filter]
    .filter((value): value is string => value !== undefined)
    .join(" ");

  const tx = resolveTransition(transitionFor, ["opacity", "src"], animateInitial);
  const play = mountPlay({ opacity }, animateInitial, nodeId);
  const ImageElement = staticRender ? "img" : motion.img;

  const image = (
    <ImageElement
      ref={imageRef}
      src={activeScaledImage?.src ?? src}
      alt={alt}
      style={{
        objectFit: fit as React.CSSProperties["objectFit"],
        objectPosition: position,
        // Keep static image opacity in the DOM style as well as in Framer's
        // animation target. `motion.img` does not necessarily materialize an
        // unchanged target value, so omitting this would make authored image
        // paint opacity silently render as 1.
        opacity,
        width: imageTransform?.width ?? width,
        height: imageTransform?.height ?? height,
        ...(imageTransform
          ? {
              position: "absolute",
              left: imageTransform.left,
              top: imageTransform.top,
              ...(imageTransform.css
                ? { transformOrigin: "0 0", transform: imageTransform.css }
                : {}),
              ...(imageTransform.axisAligned || imageTransform.transformedObjectFitFill
                ? { objectFit: "fill" as const }
                : {}),
            }
          : {}),
        ...(filter !== "" ? { filter } : {}),
        ...(shadow.boxShadow !== undefined ? { boxShadow: shadow.boxShadow } : {}),
        // NB: NO `will-change` here. Promoting the <img> to its own GPU layer
        // hoists it out of the wrapper's paint buffer, so a `mix-blend-mode`
        // on the wrapper (Sunshine screen, Ruby20 / caramel hard-light) blends
        // an EMPTY box with the backdrop → the blend silently no-ops and the
        // image's contribution (the diagonal light streaks, the warm Ruby) is
        // lost. Static images don't need the compositor hint anyway.
      }}
      {...(staticRender
        ? {}
        : { initial: play.initial, animate: play.animate, transition: toFramer(tx) })}
      onLoad={() => {
        if (activeScaledImage?.fallbackToDataUrl) {
          setScaledImage({ ...activeScaledImage, fallbackToDataUrl: undefined });
        }
      }}
      onError={() => {
        const fallback = activeScaledImage?.fallbackToDataUrl;
        if (!fallback || !activeScaledImage) return;
        try {
          const dataUrl = fallback();
          activeScaledImage.release?.();
          setScaledImage({
            ...activeScaledImage,
            src: dataUrl,
            release: undefined,
            fallbackToDataUrl: undefined,
          });
        } catch {
          setScaledImage(undefined);
        }
      }}
      draggable={false}
    />
  );

  if (!imageTransform) return image;
  return <div style={{ position: "relative", overflow: "hidden", width, height }}>{image}</div>;
}

/** Rasterise the source at the Figma paint resolution. Figma's common
 * `scalingFactor: 0.5` path is a 2×2 box reduction, not a CSS scale; doing the
 * reduction explicitly keeps the authored node geometry intact and avoids
 * relying on the browser's compositor interpolation choice. Other factors
 * use the browser's bounded low-quality resampler as a safe fallback. */
export async function rasterizeImage(
  source: HTMLImageElement,
  factor: number,
  width: number,
  height: number,
): Promise<EncodedRasterSource> {
  const isHalf = factor === 0.5 && source.naturalWidth % 2 === 0 && source.naturalHeight % 2 === 0;
  if (isHalf) {
    const sourceCanvas = document.createElement("canvas");
    sourceCanvas.width = source.naturalWidth;
    sourceCanvas.height = source.naturalHeight;
    const sourceContext = sourceCanvas.getContext("2d", { willReadFrequently: true });
    if (!sourceContext) throw new Error("image source canvas unavailable");
    sourceContext.drawImage(source, 0, 0, source.naturalWidth, source.naturalHeight);
    const sourcePixels = sourceContext.getImageData(
      0,
      0,
      source.naturalWidth,
      source.naturalHeight,
    );
    // The source pixels are now held by ImageData, so reuse the same canvas
    // backing store for the smaller result instead of allocating a second one.
    sourceCanvas.width = width;
    sourceCanvas.height = height;
    const targetContext = sourceCanvas.getContext("2d");
    if (!targetContext) throw new Error("image target canvas unavailable");
    const targetPixels = targetContext.createImageData(width, height);
    downsample2x2Rgba(
      sourcePixels.data,
      source.naturalWidth,
      source.naturalHeight,
      targetPixels.data,
    );
    targetContext.putImageData(targetPixels, 0, 0);
    return encodeRasterCanvas(sourceCanvas);
  }

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("image canvas unavailable");
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "low";
  context.drawImage(source, 0, 0, width, height);
  return encodeRasterCanvas(canvas);
}

function readImageScaleFactor(value: unknown, nodeId?: string): number {
  if (value === undefined) return 1;
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0 || value > 1) {
    emitDiagnostic(
      nodeId,
      "image.imageScaleFactor",
      "rejected value : expected a finite number in the interval (0, 1]",
    );
    return 1;
  }
  return value;
}

function numberOr(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

/** A render dimension: a finite number → px, a non-empty string → verbatim
 *  (e.g. "100%"), anything else → the fallback. */
function dimOr(v: unknown, fallback: string): string {
  if (typeof v === "number" && Number.isFinite(v)) return `${v}px`;
  if (typeof v === "string" && v.length > 0) return v;
  return fallback;
}

function readImageTransform(
  value: unknown,
  nodeId?: string,
  width?: string,
  height?: string,
):
  | {
      width: string;
      height: string;
      left: number | string;
      top: number | string;
      axisAligned?: boolean;
      transformedObjectFitFill?: boolean;
      css?: string;
    }
  | undefined {
  if (!Array.isArray(value) || value.length !== 6) return undefined;
  if (
    value.some(
      (entry) => typeof entry !== "number" || !Number.isFinite(entry) || Math.abs(entry) > 1000,
    )
  ) {
    emitDiagnostic(nodeId, "image.imageTransform", "rejected value : not a finite bounded matrix");
    return undefined;
  }
  const [a, b, c, d, e, f] = value as number[];
  const widthPx = parsePx(width);
  const heightPx = parsePx(height);
  // Figma's CROP matrix describes the source image in normalized image space:
  //   nodeSize = sourceSize * scale
  //   offset = sourceSize * translation
  // (the same convention used by the Figma plugin API). For the common crop
  // case the matrix is axis-aligned; render the unscaled source rectangle and
  // let the containing box clip it. This is materially different from
  // applying `scale(d)` to a node-sized <img>, which shrinks the source instead
  // of exposing the requested crop.
  const axisAligned = Math.abs(b) < 1e-6 && Math.abs(c) < 1e-6 && a > 0 && d > 0;
  if (axisAligned && widthPx !== undefined && heightPx !== undefined) {
    return {
      axisAligned: true,
      width: `${widthPx / a}px`,
      height: `${heightPx / d}px`,
      // The Figma translation describes which source region is exposed by
      // the node. CSS positions the larger source image in the opposite
      // direction inside the clipped node box.
      left: `${-(widthPx / a) * e}px`,
      top: `${-(heightPx / d) * f}px`,
    };
  }
  // A non-axis-aligned Figma matrix maps the NODE'S normalized coordinates to
  // normalized source-image coordinates.  Applying that matrix directly to a
  // node-sized <img> shrinks the source into a thin strip (the common symptom
  // is an apparently missing / inverted texture).  Render the source at the
  // crop dimensions implied by its diagonal scale, then apply the bounded
  // inverse affine map so CSS paints the same crop into the node box.
  // Percentage-sized live nodes cannot be resolved numerically; retain a
  // bounded identity-sized fallback rather than inventing pixel dimensions.
  const tx = widthPx === undefined ? 0 : e * widthPx;
  const ty = heightPx === undefined ? 0 : f * heightPx;
  if (widthPx !== undefined && heightPx !== undefined) {
    const determinant = a * d - b * c;
    const scaleX = Math.max(Math.abs(a), 1e-6);
    const scaleY = Math.max(Math.abs(d), 1e-6);
    if (Math.abs(determinant) > 1e-6) {
      const sourceWidth = widthPx / scaleX;
      const sourceHeight = heightPx / scaleY;
      const inverseA = d / determinant;
      const inverseB = -b / determinant;
      const inverseC = -c / determinant;
      const inverseD = a / determinant;
      const inverseTx = -(inverseA * e + inverseC * f);
      const inverseTy = -(inverseB * e + inverseD * f);
      return {
        width: `${sourceWidth}px`,
        height: `${sourceHeight}px`,
        left: 0,
        top: 0,
        transformedObjectFitFill: true,
        css: `matrix(${(widthPx / sourceWidth) * inverseA},${(heightPx / sourceWidth) * inverseB},${(widthPx / sourceHeight) * inverseC},${(heightPx / sourceHeight) * inverseD},${widthPx * inverseTx},${heightPx * inverseTy})`,
      };
    }
  }
  return {
    css: `matrix(${a},${b},${c},${d},${tx},${ty})`,
    left: 0,
    top: 0,
    width: "100%",
    height: "100%",
  };
}

function parsePx(value: string | undefined): number | undefined {
  if (!value) return undefined;
  const match = /^(-?\d+(?:\.\d+)?)px$/.exec(value);
  return match ? Number(match[1]) : undefined;
}
