// Strict SVG path-data validator — the ONLY gate through which
// untrusted `d` strings (bundle props AND live LSDP deltas, see
// `resolveProps` in tree.tsx) may reach a rendered `<path d>` attribute.
//
// ADR 001 §6 RC#10 (allowlisted `d` grammar) + RC#12 (anti-ReDoS),
// threat model Bastion 2026-06-10, issue #30. Every new path string and
// every rejected payload is validated at EVERY render — props are
// wire-drivable, so a hostile delta arriving after mount goes through
// the exact same gate as a static prop. Exact previously accepted values
// may reuse a bounded success-only cache.
//
// Accepted grammar (SVG path data, LSML 1.1 §4.6, nothing more) :
//   - command letters : M m L l H h V v C c S s Q q T t A a Z z
//   - numbers         : [+-]? digits [. digits]? ([eE] [+-]? digits)?
//   - separators      : space, tab, CR, LF, comma
// Anything else — including `url(`, `data:`, `<`, `&`, parentheses,
// quotes, semicolons, braces — is REJECTED (null). Never passthrough.
//
// ── Linear-time justification (RC#12, written per Bastion) ──────────
// 1. Inputs longer than MAX_SUBPATH_LEN (16 KiB) are rejected on a
//    single O(1) length check before any scanning — a 10⁶-command
//    payload never reaches the scanner.
// 2. The scanner is a hand-written single forward pass : every loop
//    iteration advances `i` by at least one character and there is no
//    regex anywhere, so total work is O(min(n, 8192)) per value
//    regardless of payload shape. No backtracking is possible by
//    construction.
// 3. The command cap (MAX_SUBPATH_COMMANDS) additionally bounds the
//    number of path segments the SVG engine will ever be asked to
//    tessellate, independently of string length.
// ─────────────────────────────────────────────────────────────────────

import { emitDiagnostic } from "./diagnostics";

/** RC#10 — hard cap : 16 KiB per subpath `d` string.
 *
 * This remains a bounded input gate; the separate 4000-command and 64-subpath
 * caps continue to protect SVG parsing/tessellation. The larger byte cap is
 * required for legitimate Figma flattened vector strokes just over 8 KiB.
 */
export const MAX_SUBPATH_LEN = 16 * 1024;
/**
 * RC#10 — hard cap on commands per subpath. Aligned on the compiler's
 * MAX_PATH_COMMANDS = 4000 (PR #39, deliberate authoring cap) so a live
 * LSDP delta can never carry more commands than the authoring pipeline
 * accepts. A shared constant module is tracked in issue #41 — do not
 * diverge these two values in the meantime.
 */
export const MAX_SUBPATH_COMMANDS = 4000;
/** RC#10 — hard cap on subpaths per shape. */
export const MAX_SUBPATHS = 64;

const CMD_CHARS = new Set("MmLlHhVvCcSsQqTtAaZz");

// Figma scenes commonly repeat the same flattened path many times. Cache
// only exact strings that passed the complete validator, keeping live
// delta inputs behind the same gate while avoiding repeated scans of
// already-proven immutable values. Four bytes per UTF-16 code unit
// conservatively accounts for the raw key and trimmed value; entry and
// weight limits keep retention bounded even for large paths.
const VALIDATED_PATH_CACHE_MAX_ENTRIES = 512;
const VALIDATED_PATH_CACHE_MAX_WEIGHT = 256 * 1024;
const validatedPathCache = new Map<string, { value: string; weight: number }>();
let validatedPathCacheWeight = 0;

function cacheValidatedPath(input: string, value: string): void {
  const weight = (input.length + value.length) * 2;
  while (
    validatedPathCache.size >= VALIDATED_PATH_CACHE_MAX_ENTRIES ||
    validatedPathCacheWeight + weight > VALIDATED_PATH_CACHE_MAX_WEIGHT
  ) {
    const oldest = validatedPathCache.entries().next().value as
      | [string, { value: string; weight: number }]
      | undefined;
    if (oldest === undefined) return;
    validatedPathCache.delete(oldest[0]);
    validatedPathCacheWeight -= oldest[1].weight;
  }
  validatedPathCache.set(input, { value, weight });
  validatedPathCacheWeight += weight;
}

function isDigit(code: number): boolean {
  return code >= 0x30 && code <= 0x39; // 0-9
}

function isSeparator(code: number): boolean {
  // space, tab, CR, LF, comma
  return code === 0x20 || code === 0x09 || code === 0x0d || code === 0x0a || code === 0x2c;
}

/**
 * Validate an untrusted SVG path `d` string against the strict grammar
 * above. Returns the validated (trimmed) string or `null` on rejection.
 * A `null` MUST be handled as "omit the subpath + emit a diagnostic" —
 * never interpolate the raw input into the DOM.
 */
export function validatePathData(value: unknown): string | null {
  if (typeof value !== "string") return null;
  // O(1) length gate BEFORE any per-character work (RC#12).
  if (value.length === 0 || value.length > MAX_SUBPATH_LEN) return null;
  const cached = validatedPathCache.get(value);
  if (cached !== undefined) {
    validatedPathCache.delete(value);
    validatedPathCache.set(value, cached);
    return cached.value;
  }
  const d = value.trim();
  if (d.length === 0) return null;

  // Contractual explicit rejects (Bastion RC#10) — redundant with the
  // allowlist scan below, kept as belt-and-braces so the contract
  // holds even if the grammar is ever extended.
  const lower = d.toLowerCase();
  if (lower.includes("url(") || lower.includes("data:")) return null;
  if (d.includes("<") || d.includes("&")) return null;

  // Single forward pass — tokenizes commands and numbers, rejects any
  // character outside the allowlist, counts commands.
  const n = d.length;
  let i = 0;
  let commands = 0;
  let sawCommand = false;
  while (i < n) {
    const code = d.charCodeAt(i);
    if (isSeparator(code)) {
      i++;
      continue;
    }
    const ch = d[i];
    if (CMD_CHARS.has(ch)) {
      // Path data must start with a moveto (M/m).
      if (!sawCommand && ch !== "M" && ch !== "m") return null;
      sawCommand = true;
      commands++;
      if (commands > MAX_SUBPATH_COMMANDS) return null;
      i++;
      continue;
    }
    // Anything else must be a well-formed number token — and numbers
    // can only appear after the leading moveto.
    if (!sawCommand) return null;
    if (ch === "+" || ch === "-") i++;
    let digits = 0;
    while (i < n && isDigit(d.charCodeAt(i))) {
      i++;
      digits++;
    }
    if (i < n && d[i] === ".") {
      i++;
      let fracDigits = 0;
      while (i < n && isDigit(d.charCodeAt(i))) {
        i++;
        fracDigits++;
      }
      // A token ending in a bare "." (empty decimal part, e.g. "1.")
      // must not be immediately followed by another "." — "1..2" is not
      // valid SVG path data and would otherwise be mis-scanned as the
      // two tokens "1." + ".2" (Probe bug report, issue #30).
      if (fracDigits === 0 && i < n && d[i] === ".") return null;
      digits += fracDigits;
    }
    if (digits === 0) return null; // bare sign / dot / forbidden char
    if (i < n && (d[i] === "e" || d[i] === "E")) {
      i++;
      if (i < n && (d[i] === "+" || d[i] === "-")) i++;
      let expDigits = 0;
      while (i < n && isDigit(d.charCodeAt(i))) {
        i++;
        expDigits++;
      }
      if (expDigits === 0) return null;
    }
  }
  if (commands === 0) return null;
  cacheValidatedPath(value, d);
  return d;
}

export interface SubPath {
  d: string;
  fillRule: "nonzero" | "evenodd";
}

/**
 * Return a conservative vertical extent for validated SVG path data.
 *
 * Figma exports flattened dashed strokes as closed paths with an authored
 * layout height of zero.  The SVG viewport still needs a positive height to
 * rasterise those coordinates; this small command-aware pass supplies that
 * extent without asking the browser to measure an unmounted path or trusting
 * unvalidated text.  Control points and arc radii are included conservatively
 * so the viewport never clips a legitimate curve.
 */
export function pathVerticalBounds(
  paths: readonly SubPath[],
): { minY: number; maxY: number } | null {
  let minY = Number.POSITIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  for (const path of paths) {
    const bounds = onePathVerticalBounds(path.d);
    if (bounds === null) continue;
    minY = Math.min(minY, bounds.minY);
    maxY = Math.max(maxY, bounds.maxY);
  }
  return Number.isFinite(minY) && Number.isFinite(maxY) ? { minY, maxY } : null;
}

type PathCommand = "M" | "L" | "H" | "V" | "C" | "S" | "Q" | "T" | "A";

const PATH_NUMBER_OR_COMMAND =
  /[AaCcHhLlMmQqSsTtVvZz]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?/g;
const PATH_PARAMETER_COUNT: Record<PathCommand, number> = {
  M: 2,
  L: 2,
  H: 1,
  V: 1,
  C: 6,
  S: 4,
  Q: 4,
  T: 2,
  A: 7,
};

function onePathVerticalBounds(d: string): { minY: number; maxY: number } | null {
  const tokens = d.match(PATH_NUMBER_OR_COMMAND);
  if (tokens === null) return null;
  let index = 0;
  let command: string | undefined;
  let x = 0;
  let y = 0;
  let startX = 0;
  let startY = 0;
  let minY = Number.POSITIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;

  const addY = (value: number): void => {
    if (!Number.isFinite(value)) return;
    minY = Math.min(minY, value);
    maxY = Math.max(maxY, value);
  };
  const isCommand = (value: string): boolean => /^[A-Za-z]$/.test(value);
  const nextNumber = (): number | null => {
    const value = tokens[index];
    if (value === undefined || isCommand(value)) return null;
    index += 1;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };

  while (index < tokens.length) {
    const token = tokens[index];
    if (token !== undefined && isCommand(token)) {
      index += 1;
      if (token === "Z" || token === "z") {
        x = startX;
        y = startY;
        addY(y);
        command = undefined;
        continue;
      }
      command = token;
    }
    if (command === undefined) return null;
    const upper = command.toUpperCase() as PathCommand;
    const count = PATH_PARAMETER_COUNT[upper];
    if (count === undefined) return null;
    const absolute = command === upper;
    let firstMove = upper === "M";
    let consumed = false;
    while (index < tokens.length && !isCommand(tokens[index]!)) {
      const values: number[] = [];
      for (let valueIndex = 0; valueIndex < count; valueIndex += 1) {
        const value = nextNumber();
        if (value === null) return null;
        values.push(value);
      }
      consumed = true;
      const baseX = x;
      const baseY = y;
      switch (upper) {
        case "M":
        case "L":
        case "T": {
          x = absolute ? values[0]! : baseX + values[0]!;
          y = absolute ? values[1]! : baseY + values[1]!;
          addY(y);
          if (upper === "M" && firstMove) {
            startX = x;
            startY = y;
            firstMove = false;
          }
          break;
        }
        case "H":
          x = absolute ? values[0]! : baseX + values[0]!;
          addY(y);
          break;
        case "V":
          y = absolute ? values[0]! : baseY + values[0]!;
          addY(y);
          break;
        case "C": {
          const control1Y = absolute ? values[1]! : baseY + values[1]!;
          const control2Y = absolute ? values[3]! : baseY + values[3]!;
          y = absolute ? values[5]! : baseY + values[5]!;
          addY(control1Y);
          addY(control2Y);
          addY(y);
          x = absolute ? values[4]! : baseX + values[4]!;
          break;
        }
        case "S":
        case "Q": {
          const controlY = absolute ? values[1]! : baseY + values[1]!;
          y = absolute ? values[3]! : baseY + values[3]!;
          addY(controlY);
          addY(y);
          x = absolute ? values[2]! : baseX + values[2]!;
          break;
        }
        case "A": {
          const radiusY = Math.abs(values[1]!);
          y = absolute ? values[6]! : baseY + values[6]!;
          addY(baseY - radiusY);
          addY(baseY + radiusY);
          addY(y - radiusY);
          addY(y + radiusY);
          x = absolute ? values[5]! : baseX + values[5]!;
          break;
        }
      }
      if (upper === "M") command = absolute ? "L" : "l";
    }
    if (!consumed) return null;
  }
  return Number.isFinite(minY) && Number.isFinite(maxY) ? { minY, maxY } : null;
}

/**
 * Resolve a shape's `pathData` / `paths[]` props (LSML 1.1 §4.6) into
 * validated subpaths ready for rendering — one `<path>` element per
 * entry (ADR 001 §3.2.3). `pathData` is equivalent to
 * `paths: [{ data: pathData, windingRule: "NONZERO" }]`.
 *
 * Resolves at every render (RC#10 — props are live via LSDP deltas);
 * exact previously accepted strings may reuse the bounded validator cache,
 * while every unseen or rejected value is checked normally. Every rejected
 * or unrendered field emits a diagnostic (ADR 001 §3.4, anti-silent-drop)
 * that NEVER contains the value (R9).
 */
export function parseShapePaths(resolved: Record<string, unknown>, nodeId?: string): SubPath[] {
  const rawPaths = resolved.paths;
  const rawPathData = resolved.pathData;

  if (Array.isArray(rawPaths)) {
    if (rawPathData !== undefined) {
      // Spec §4.6 : mutually exclusive. Tolerate with paths[] winning
      // (mirrors the fills[]/fill precedence), but never silently.
      warnPath(nodeId, "shape.pathData", "mutually exclusive with paths[] ; paths[] wins");
    }
    const out: SubPath[] = [];
    for (let idx = 0; idx < rawPaths.length; idx++) {
      if (out.length >= MAX_SUBPATHS) {
        warnPath(nodeId, "shape.paths", "subpath cap exceeded ; remaining entries dropped");
        break;
      }
      const entry = rawPaths[idx] as { data?: unknown; windingRule?: unknown } | null;
      const d = validatePathData(
        typeof entry === "object" && entry !== null ? entry.data : undefined,
      );
      if (d === null) {
        warnPath(nodeId, "shape.paths.data", "not a strict SVG path grammar (allowlist/caps)");
        continue;
      }
      out.push({ d, fillRule: toFillRule(entry?.windingRule, nodeId) });
    }
    if (out.length === 0 && rawPaths.length > 0) {
      warnPath(nodeId, "shape.paths", "no renderable subpath ; shape geometry omitted");
    }
    return out;
  }

  if (rawPathData !== undefined) {
    const d = validatePathData(rawPathData);
    if (d === null) {
      warnPath(nodeId, "shape.pathData", "not a strict SVG path grammar (allowlist/caps)");
      return [];
    }
    return [{ d, fillRule: "nonzero" }];
  }

  // geometry:"path" with neither prop — spec'd field combination we
  // cannot render. Diagnostic, never a silent no-op (ADR 001 §3.4).
  warnPath(nodeId, "shape.paths", "geometry is path but neither pathData nor paths[] is present");
  return [];
}

function toFillRule(windingRule: unknown, nodeId?: string): "nonzero" | "evenodd" {
  if (windingRule === undefined || windingRule === "NONZERO") return "nonzero";
  if (windingRule === "EVENODD") return "evenodd";
  warnPath(nodeId, "shape.paths.windingRule", "unknown winding rule ; defaulting to nonzero");
  return "nonzero";
}

/**
 * Diagnostic for a rejected / unrendered path field. Bastion R9
 * (ADR 001 §5.1) : the rejected VALUE is never logged nor forwarded —
 * only `node.id` (RC#7, issue #34), the field name and a static reason.
 * Routed through the structured diagnostics channel.
 */
function warnPath(nodeId: string | undefined, field: string, reason: string): void {
  emitDiagnostic(nodeId, field, reason);
}
