import { motion } from "framer-motion";
import type { ReactElement } from "react";
import type { PrimitiveProps } from "./index";
import { toFramer, mountPlay, resolveTransition } from "../../animate/transitions";
import { parseFills, renderFill, sanitizeFills, gateImageFills, type Fill } from "../fill";
import { parseCssColor, warnRejectedColor } from "../css-color";
import { useAllowedHosts, useHostAssetPolicy } from "../allowed-hosts";
import { buildShapeOutline } from "../shape-geometry";
import { buildLayerBlurFilter } from "../universal-wrapper";
import { parseShapePaths, pathVerticalBounds } from "../svg-path";
import { buildShadowCss, type InnerShadow } from "../shadow-css";

interface StrokeSpec {
  color?: string;
  width?: number;
  fill?: unknown;
  align?: "INSIDE" | "OUTSIDE" | "CENTER";
}

/** Rectangle / circle / line / path. Renders as SVG so stroke + fill
 *  behave predictably across hosts. Opacity animatable.
 *
 *  LSML 1.1 §4.6 + §4.12 add `fills[]` / `strokes[]` arrays as the
 *  preferred way to declare multi-layer fills with linear/radial
 *  gradients. The legacy single `fill` / `stroke` props remain
 *  accepted for 1.0 bundles ; when both are present the array form
 *  wins (the spec forbids mixing, but we tolerate to ease migration).
 *
 *  Security (ADR 001 §6 RC#10 + RC#11, issue #30) : every colour that
 *  reaches an SVG `fill`/`stroke`/`stop-color` attribute goes through
 *  the strict `parseCssColor` gate, and every path `d` goes through
 *  `validatePathData` — at EVERY render, because props are wire-
 *  drivable live via LSDP deltas (`resolveProps`, tree.tsx).
 */
export function Shape({
  resolved,
  nodeId,
  transitionFor,
  animateInitial,
  staticRender = false,
  renderBlurInsideShape = false,
}: PrimitiveProps) {
  // Canonical prop name is `geometry` (LSML §4.6 — what the compiler
  // emits) ; `kind` is kept as a fallback for hand-rolled Solar-lineage
  // RenderNodes that predate the compiler.
  const kind =
    (resolved.geometry as string | undefined) ?? (resolved.kind as string | undefined) ?? "rect";
  const hasAuthoredStrokeGeometry =
    (kind === "path" || kind === "circle") &&
    Array.isArray(resolved.stroke_geometry) &&
    resolved.stroke_geometry.length > 0;
  const legacyFill = safeColor(resolved.fill, "shape.fill", nodeId) ?? "transparent";
  const legacyStroke =
    typeof resolved.stroke === "string"
      ? (safeColor(resolved.stroke, "shape.stroke", nodeId) ?? "transparent")
      : "transparent";
  const legacyStrokeWidth = numberOr(resolved.stroke_width, 0);
  const legacyStrokeAlign = strokeAlign(resolved.stroke_align);
  const width = numberOr(resolved.width, 100);
  const height = numberOr(resolved.height, 100);
  const opacity = numberOr(resolved.opacity, 1);
  // LSML §4.6 `ariaLabel` was silently unrendered until issue #34's
  // allowlist audit surfaced it — now forwarded as the SVG label.
  const ariaLabel = typeof resolved.ariaLabel === "string" ? resolved.ariaLabel : undefined;

  const tx = resolveTransition(transitionFor, ["opacity"], animateInitial);
  const transition = toFramer(tx);
  const play = mountPlay({ opacity }, animateInitial, nodeId);

  // LSML 1.1 §4.6 — `fills[]` is the preferred multi-fill form. Fall
  // back to the singular `fill` for 1.0 bundles. Colours are strict-
  // validated (a rejected colour drops its layer, with diagnostic).
  // LSML 1.2 §3.2 — image-fill `src` is host/scheme-gated (Bastion T1/T2)
  // BEFORE any URL reaches an SVG <image href>. A rejected image-fill is
  // dropped (no passthrough) with an R9-clean diagnostic. Colour fills go
  // through `sanitizeFills` (RC#11) ; image fills pass it through untouched.
  const allowedHosts = useAllowedHosts();
  const isHostAssetUrl = useHostAssetPolicy();
  const fills = gateImageFills(
    sanitizeFills(parseFills(resolved.fills, "shape.fills", nodeId), "shape.fills", nodeId),
    allowedHosts,
    "shape.fills",
    nodeId,
    isHostAssetUrl,
  );
  // The compiler lowers a typed single stroke to `strokes[]`, while direct
  // Figma/LSML captures may still carry the same object in singular `stroke`.
  // Accept both wire forms so a gradient/path stroke is never silently turned
  // into a zero-width SVG pass when the bundle bypasses the compiler.
  const strokes = parseStrokes(resolved.strokes);
  const effectiveStrokeSpecs = strokes.length > 0 ? strokes : parseStrokes(resolved.stroke);
  const shadow = buildShadowCss(resolved.shadow, nodeId, "shape.shadow.color");
  const shapeLayerBlur = renderBlurInsideShape
    ? buildLayerBlurFilter(
        typeof resolved.blur === "number" ? resolved.blur : undefined,
        typeof resolved.staticBlurPasses === "number" ? resolved.staticBlurPasses : undefined,
      )
    : undefined;

  // Each fill compiles to a (defs, ref) pair. We render the shape outline
  // once per fill in authored painter order: the first entry is painted
  // first and later entries composite over it, matching SVG sibling order.
  // The defs are aggregated for a single <defs>.
  const fillRenders = fills.map((fill) => renderFill(fill));
  // A Figma gradient stroke uses the same typed paint vocabulary as a fill.
  // Validate it through the exact same colour/image gates, then reuse
  // renderFill to produce a generated SVG paint server (`url(#...)`).
  const strokeRenders = effectiveStrokeSpecs.map((stroke) => {
    if (stroke.fill === undefined || typeof stroke.fill !== "object" || stroke.fill === null) {
      return null;
    }
    const [safe] = gateImageFills(
      sanitizeFills([stroke.fill as Fill], "shape.strokes.fill", nodeId),
      allowedHosts,
      "shape.strokes.fill",
      nodeId,
      isHostAssetUrl,
    );
    return safe
      ? renderFill(
          safe,
          kind === "path" || kind === "circle" ? { authoredBox: { width, height } } : {},
        )
      : null;
  });
  const allDefs = [
    ...fillRenders.flatMap((r) => r.defs),
    ...strokeRenders.flatMap((r) => (r ? r.defs : [])),
  ];
  // #L — each fill layer carries its (runtime-revalidated) `mix-blend-mode`,
  // applied on that layer's SVG element, independent of the node-level blend
  // (#D, on the wrapper). Legacy single-fill path carries no per-fill blend.
  const fillLayers: { ref: string; mixBlendMode?: string }[] =
    fillRenders.length > 0
      ? fillRenders.map((r) => ({ ref: r.ref, mixBlendMode: r.mixBlendMode }))
      : [{ ref: legacyFill }];

  // Strokes use the same layered approach as fills. Solid colours and typed
  // gradient paint servers are each rendered as an additional pass over the
  // same shape outline.
  const strokeLayers =
    effectiveStrokeSpecs.length > 0
      ? effectiveStrokeSpecs.map((s, i) => ({
          color:
            strokeRenders[i]?.ref ??
            safeColor(s.color, "shape.strokes.color", nodeId) ??
            "transparent",
          width: s.width ?? 0,
          align: s.align ?? legacyStrokeAlign,
        }))
      : [{ color: legacyStroke, width: legacyStrokeWidth, align: legacyStrokeAlign }];

  // Figma's Paint[] is painter order: the first entry is painted first and
  // subsequent entries are composited over it. Keep that order when emitting
  // SVG siblings because SVG paints later siblings on top. Reversing here
  // makes a multi-fill shape visually back-to-front and is especially visible
  // when two gradients cover the same geometry.
  const stackedFills = fillLayers;
  const stackedStrokes = [...strokeLayers].reverse();
  // For paths, a zero-width / transparent stroke pass would only emit
  // invisible duplicate <path> elements — skip it.
  const effectiveStrokes =
    kind === "path"
      ? stackedStrokes.filter((s) => s.width > 0 && s.color !== "transparent")
      : stackedStrokes;
  const zeroPathBounds =
    kind === "path" && height === 0 ? pathVerticalBounds(parseShapePaths(resolved, nodeId)) : null;
  const zeroPathMinY = zeroPathBounds?.minY ?? 0;
  const zeroPathMaxY = zeroPathBounds?.maxY ?? 0;
  const zeroPathHeight = zeroPathBounds === null ? 0 : Math.max(0, zeroPathMaxY - zeroPathMinY);
  const svgHeight = zeroPathBounds === null ? height : zeroPathHeight;
  // INNER_SHADOW is a paint effect in Figma: its alpha is clipped to the
  // painted geometry. CSS `box-shadow: inset` clips to the SVG viewport and
  // is therefore wrong for both rings and irregular paths (it was the source
  // of the large white triangular artefact). Retain only non-inset spread
  // shadows on the CSS box until a path-clipped inner-shadow compositor is
  // available for the remaining inset layers.
  const shapeBoxShadow = shadow.outerBoxShadow;
  const innerShadowLayers =
    shadow.innerShadows?.map((innerShadow, index) => ({
      innerShadow,
      id: shapeInnerShadowFilterId(nodeId, innerShadow, index, width, height),
    })) ?? [];
  // A missing fill is represented by the transparent legacy fallback so the
  // normal paint pass remains structurally stable. It must not become a white
  // source geometry in the INNER_SHADOW overlay, however: Figma clips an
  // inner shadow to the authored painted geometry, and a stroke-only shape has
  // no filled disk to contribute to that alpha.
  const innerShadowFills = fillRenders.length > 0 ? stackedFills : [];

  // Integration #K × #L — geometry construction is delegated to the single
  // typed outline builder (`shape-geometry.tsx`, ADR 002 A2.1 #K), so a
  // referenced shape's mask coverage is built from the IDENTICAL geometry as
  // its on-screen render. The per-fill `mix-blend-mode` (#L, already runtime-
  // revalidated by `renderFill` against the closed enum) is threaded through
  // the paint argument and applied as inline `style` on the painted layer's
  // SVG element. `undefined` (absent / out-of-enum) → no style key, layer
  // blends `normal` (rétro-compat). Stroke passes never carry a fill blend —
  // and the mask coverage path NEVER carries a blend (a mask is a coverage
  // stencil, not a colour reproduction : `buildMaskCoverageFromShape` omits
  // `mixBlendMode` entirely, #K hypothesis 2).
  const renderShape = (
    fill: string,
    stroke: { color: string; width: number; align?: StrokeSpec["align"] },
    keyPrefix: string,
    mixBlendMode?: string,
    filter?: string,
  ): ReactElement =>
    buildShapeOutline(
      resolved,
      {
        fill,
        stroke: stroke.color,
        strokeWidth: stroke.width,
        strokeAlign: stroke.align,
        mixBlendMode,
        filter,
      },
      nodeId,
      keyPrefix,
    );

  const ShapeElement = staticRender ? "svg" : motion.svg;
  return (
    <ShapeElement
      width={width}
      height={svgHeight}
      viewBox={
        zeroPathBounds === null
          ? `0 0 ${width} ${height}`
          : `0 ${zeroPathMinY} ${width} ${zeroPathHeight}`
      }
      {...(ariaLabel !== undefined ? { "aria-label": ariaLabel, role: "img" } : {})}
      style={{
        // SVG is an atomic visual primitive, not inline text. Keeping the
        // default inline baseline would add a font-dependent descent inside
        // absolute wrappers (the 8px Figma underline was shifted ~6px down).
        display: "block",
        // Keep the authored static shape opacity in the DOM as well as in
        // Framer's animation target. `motion.svg` does not necessarily
        // materialize an unchanged target value, so omitting this would make
        // imported Figma shape paints render fully opaque.
        opacity,
        // Figma exports line-like path geometry with an authored height of
        // zero while the stroke itself extends above/below the centreline.
        // Chromium's default SVG overflow clips that paint completely. Keep
        // the zero-height layout box, but let only path geometry escape it so
        // dashed separators and other zero-height vector lines remain visible.
        ...((kind === "path" || kind === "circle") && (height === 0 || hasAuthoredStrokeGeometry)
          ? { overflow: "visible" as const }
          : {}),
        ...(zeroPathBounds !== null ? { transform: `translateY(${zeroPathMinY}px)` } : {}),
        ...(shadow.filter !== undefined ? { filter: shadow.filter } : {}),
        ...(shapeBoxShadow !== undefined ? { boxShadow: shapeBoxShadow } : {}),
      }}
      {...(staticRender ? {} : { initial: play.initial, animate: play.animate, transition })}
    >
      {(allDefs.length > 0 || innerShadowLayers.length > 0) && (
        <defs>
          {allDefs}
          {innerShadowLayers.map(({ id, innerShadow }) => (
            <ShapeInnerShadowFilter
              key={id}
              id={id}
              width={width}
              height={height}
              shadow={innerShadow}
            />
          ))}
        </defs>
      )}
      {stackedFills.map((layer, i) =>
        renderShape(
          layer.ref,
          { color: "transparent", width: 0 },
          `fill-${i}`,
          layer.mixBlendMode,
          shapeLayerBlur,
        ),
      )}
      {effectiveStrokes.map((s, i) =>
        renderShape("none", s, `stroke-${i}`, undefined, shapeLayerBlur),
      )}
      {innerShadowLayers.map(({ id, innerShadow }) => (
        <g
          key={`inner-shadow-${id}`}
          style={{
            filter: `url(#${id})`,
            mixBlendMode: svgBlendMode(innerShadow.blendMode),
          }}
        >
          {innerShadowFills.map((_layer, i) =>
            renderShape("white", { color: "transparent", width: 0 }, `inner-fill-${i}`),
          )}
          {effectiveStrokes.map((stroke, i) =>
            renderShape(
              "none",
              { color: "white", width: stroke.width, align: stroke.align },
              `inner-stroke-${i}`,
            ),
          )}
        </g>
      ))}
    </ShapeElement>
  );
}

type SvgBlendMode =
  | "normal"
  | "plus-lighter"
  | "multiply"
  | "screen"
  | "overlay"
  | "darken"
  | "lighten"
  | "color-dodge"
  | "color-burn"
  | "hard-light"
  | "soft-light"
  | "difference"
  | "exclusion"
  | "hue"
  | "saturation"
  | "color"
  | "luminosity";

/** Render one Figma INNER_SHADOW as a geometry-alpha overlay.
 *
 * The filter intentionally emits only the shadow paint. The source geometry
 * is duplicated in a sibling `<g>` so the original fill/stroke remains the
 * authoritative base paint and outer drop shadows stay on the source SVG.
 * This avoids the rectangle clipping produced by CSS `box-shadow: inset` and
 * by applying an SVG filter directly to an HTML/SVG box with unrelated
 * content. The overlay's CSS blend mode is the compositing stage for the
 * shadow, matching the authored Figma effect rather than baking it into the
 * base colour.
 */
function ShapeInnerShadowFilter({
  id,
  width,
  height,
  shadow,
}: {
  id: string;
  width: number;
  height: number;
  shadow: InnerShadow;
}): ReactElement {
  const padding = Math.max(1, width, height);
  return (
    <filter
      id={id}
      x={-padding}
      y={-padding}
      width={width + padding * 2}
      height={height + padding * 2}
      filterUnits="userSpaceOnUse"
      primitiveUnits="userSpaceOnUse"
      colorInterpolationFilters="sRGB"
    >
      <feGaussianBlur
        in="SourceAlpha"
        stdDeviation={Math.max(0, shadow.blur / 2)}
        result="inner-shadow-blur"
      />
      <feOffset in="inner-shadow-blur" dx={shadow.x} dy={shadow.y} result="inner-shadow-offset" />
      <feComposite
        in="SourceAlpha"
        in2="inner-shadow-offset"
        operator="out"
        result="inner-shadow-mask"
      />
      <feFlood floodColor={shadow.color} result="inner-shadow-color" />
      <feComposite
        in="inner-shadow-color"
        in2="inner-shadow-mask"
        operator="in"
        result="inner-shadow-paint"
      />
      <feMerge>
        <feMergeNode in="inner-shadow-paint" />
      </feMerge>
    </filter>
  );
}

function svgBlendMode(value: string | undefined): SvgBlendMode {
  // The overlay is an SVG group, but its blend is a CSS `mix-blend-mode`
  // declaration. Preserve Figma's LINEAR_DODGE lowering as `plus-lighter`
  // instead of replacing it with the non-equivalent `screen` approximation.
  if (value === "plus-lighter") return "plus-lighter";
  switch (value) {
    case "multiply":
    case "screen":
    case "overlay":
    case "darken":
    case "lighten":
    case "color-dodge":
    case "color-burn":
    case "hard-light":
    case "soft-light":
    case "difference":
    case "exclusion":
    case "hue":
    case "saturation":
    case "color":
    case "luminosity":
      return value;
    default:
      return "normal";
  }
}

function shapeInnerShadowFilterId(
  nodeId: string | undefined,
  shadow: InnerShadow,
  index: number,
  width: number,
  height: number,
): string {
  const seed = `${nodeId ?? "anonymous"}:${index}:${width}:${height}:${JSON.stringify(shadow)}`;
  let hash = 2166136261;
  for (let position = 0; position < seed.length; position += 1) {
    hash ^= seed.charCodeAt(position);
    hash = Math.imul(hash, 16777619);
  }
  const safeNodeId = (nodeId ?? "anonymous").replace(/[^a-zA-Z0-9_-]/g, "-");
  return `lumencast-shape-inner-${safeNodeId}-${(hash >>> 0).toString(16)}`;
}

/** Strict-validate a colour prop (RC#11 — SVG attributes are injection
 * sites too once values are wire-drivable). Non-strings resolve to
 * null silently (absent prop) ; a string that fails the strict grammar
 * is rejected with a diagnostic (value withheld per R9). */
function safeColor(value: unknown, field: string, nodeId?: string): string | null {
  if (typeof value !== "string") return null;
  const color = parseCssColor(value);
  if (color === null) warnRejectedColor(field, nodeId);
  return color;
}

function parseStrokes(value: unknown): StrokeSpec[] {
  const candidates = Array.isArray(value) ? value : value === undefined ? [] : [value];
  return candidates.filter(
    (v): v is StrokeSpec =>
      typeof v === "object" && v !== null && ("color" in v || "fill" in v || "width" in v),
  );
}

function strokeAlign(value: unknown): StrokeSpec["align"] | undefined {
  return value === "INSIDE" || value === "OUTSIDE" || value === "CENTER" ? value : undefined;
}

function numberOr(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}
