import { motion } from "framer-motion";
import type { CSSProperties } from "react";
import type { PrimitiveProps } from "./index";
import { toFramer, mountPlay, resolveTransition } from "../../animate/transitions";
import { backgroundsToCss, parseFills, gateImageFills, renderFill, type Fill } from "../fill";
import { parseCssColor, warnRejectedColor } from "../css-color";
import { emitDiagnostic } from "../diagnostics";
import { useAllowedHosts, useHostAssetPolicy } from "../allowed-hosts";
import { clampFilterChannel, clampSymmetricChannel } from "../filter-clamp";
import { parseBlendMode } from "../blend-mode";

/** Absolute-positioned container with size + transform + opacity.
 *  Animatable on `transform` and `opacity` only — width/height/position
 *  changes are intentionally *not* animatable to keep the broadcast
 *  off the layout path.
 *
 *  LSML 1.1 §4.3 + §4.12 add `backgrounds[]` as an alternative to the
 *  legacy `background` (single color). The array form supports stacked
 *  fills with linear / radial gradients ; first entry renders on top.
 *
 *  LSML 1.1 §4.3 `clipsContent` (default `true`) clips children outside
 *  the frame's bounds via `overflow: hidden` (ADR 001 §3.2.5, RC#5).
 */
export function Frame({
  resolved,
  nodeId,
  transitionFor,
  animateInitial,
  staticRender = false,
  keyframed = false,
  children,
}: PrimitiveProps) {
  const x = numberOr(resolved.x, 0);
  const y = numberOr(resolved.y, 0);
  const width = sizeProp(resolved.width);
  const height = sizeProp(resolved.height);
  const opacity = numberOr(resolved.opacity, 1);
  const scale = numberOr(resolved.scale, 1);
  // Static `rotation` (LSML §5.4) is applied HERE, on the frame's own box, so it
  // pivots around the frame centre (transform-origin: center). It must NOT go on
  // the UniversalWrapper for a frame : the wrapper carries no position/size for
  // a self-positioning frame, so it collapses to a 0-height box and the rotation
  // pivots around the wrong point (the picto/caramel swung off-place). `rotate`
  // (animated) still wins when present.
  const rotate = numberOr(resolved.rotate, numberOr(resolved.rotation, 0));
  // Mirror (Figma `scaleY(-1)`, from a negative transform determinant). Applied
  // on the frame box like the rotation so it composes correctly.
  const flipY = resolved.flipY === true;
  // Compiler forwards `cornerRadius` → `radius` (compile.ts). A frame can be a
  // rounded container (Figma pills, the rounded picto square) — apply it as
  // `border-radius` so the frame isn't rendered square. Figma clamps an
  // oversized uniform radius to the shortest side; using the raw token would
  // make CSS resolve the frame as an ellipse instead of a capsule.
  const rawRadius = numberOr(resolved.radius, 0);
  const rawWidth = numberOr(resolved.width, 0);
  const rawHeight = numberOr(resolved.height, 0);
  const radius =
    rawWidth > 0 && rawHeight > 0 ? Math.min(rawRadius, rawWidth / 2, rawHeight / 2) : rawRadius;
  // 1.0 single-fill prop — used as fallback when 1.1 `backgrounds[]`
  // is empty. RC#11 : the value is untrusted (static prop OR live LSDP
  // delta) and lands in inline CSS — strict-parse, never passthrough.
  const rawBackground = resolved.background;
  const legacyBackground = rawBackground === undefined ? undefined : parseCssColor(rawBackground);
  if (rawBackground !== undefined && legacyBackground === null) {
    warnRejectedColor("frame.background", nodeId);
  }
  // LSML 1.2 §3.2 — image-fill `src` is host/scheme-gated (Bastion T1/T2)
  // BEFORE any URL reaches `background-image`. A rejected image-fill is
  // dropped (no passthrough) with an R9-clean diagnostic.
  const allowedHosts = useAllowedHosts();
  const isHostAssetUrl = useHostAssetPolicy();
  const backgrounds = gateImageFills(
    parseFills(resolved.backgrounds, "frame.backgrounds", nodeId),
    allowedHosts,
    "frame.backgrounds",
    nodeId,
    isHostAssetUrl,
  );
  const clipsContent = resolveClipsContent(resolved.clipsContent, nodeId);

  // Pick the most expressive declared transition among the animated
  // bindings (transform / opacity). If none, no animation.
  const tx = resolveTransition(
    transitionFor,
    ["opacity", "scale", "rotate", "x", "y"],
    animateInitial,
  );
  // A static frame must not receive Framer Motion's identity transform.
  // Even matrix(1, 0, 0, 1, x, y) creates a stacking context and prevents a
  // descendant mix-blend-mode from compositing with the scene behind it.
  const hasMountPlay = animateInitial !== undefined && Object.keys(animateInitial).length > 0;
  // A KeyframePlayer composes its own animated transform around this frame.
  // Keep authored x/y on the motion transform for that subtree (the Solar
  // animation.play contract); ordinary static frames keep layout placement.
  const staticPlacement = tx === undefined && !hasMountPlay && !keyframed;
  // Framer writes `transform: none` on an identity static frame. Keep the
  // exact style contract while skipping its visual element machinery.
  const plain = staticRender && staticPlacement && scale === 1 && rotate === 0 && !flipY;

  const style: CSSProperties = {
    position: "absolute",
    left: staticPlacement ? x : 0,
    top: staticPlacement ? y : 0,
    ...(plain ? { transform: "none" } : {}),
    width,
    height,
    // Keep the authored static frame opacity in the DOM. Framer Motion's
    // initial/animate props do not reliably materialize an unchanged opacity
    // on non-animated nodes, which otherwise promotes authored 0.1 groups to
    // fully opaque layers.
    opacity,
    // NB: NO permanent `will-change`. `will-change: opacity` makes the frame an
    // isolated group (the browser pre-promotes it as if opacity < 1), which
    // CONTAINS any descendant `mix-blend-mode` to the frame's own backdrop — so
    // a screen/hard-light layer (Sunshine, Ruby20) silently stops compositing
    // with the scene below. The hint also belongs only on actively-animating
    // nodes (bind-animate adds it there) ; a static board doesn't need it.
    // LSML 1.1 §4.3 `clipsContent` (default `true`) — children outside
    // the frame's `size` are clipped. Static layout property : it never
    // animates, so it stays off the 0-layout-event hot path (ADR 001
    // §3.2.5). `false` => omit the declaration (CSS initial = visible).
    ...(clipsContent ? { overflow: "hidden" } : {}),
    ...(radius > 0 ? { borderRadius: radius } : {}),
  };
  const hasImageBackground = backgrounds.some((fill) => fill.kind === "image");
  const hasAffineGradientBackground = backgrounds.some(
    (fill) =>
      fill.kind === "linear-gradient" &&
      Array.isArray(fill.transform) &&
      fill.transform.length === 6,
  );
  if (backgrounds.length > 0) {
    if (!hasImageBackground && !hasAffineGradientBackground) {
      Object.assign(style, backgroundsToCss(backgrounds, nodeId));
    }
  } else if (legacyBackground !== undefined && legacyBackground !== null) {
    style.background = legacyBackground;
  }
  // Figma DROP_SHADOW / INNER_SHADOW. INNER → CSS `box-shadow: inset` (the
  // square's orange/red rim, on the rotated rounded frame, rotates with it in
  // local space — matches Figma). A no-spread DROP → CSS `filter: drop-shadow`,
  // which casts the shadow from the element's RENDERED CONTENT silhouette, not
  // its own rectangular box : the 5 drop shadows live on the UN-rotated wrapper
  // GROUP, so a plain `box-shadow` would project a sharp axis-aligned 464² rect
  // instead of the rotated (8.63°) rounded (r=111) square held inside. The
  // colour is strict-parsed (RC#11) ; geometry is numeric.
  const {
    filter: shadowFilter,
    boxShadow,
    blendedBoxShadows,
  } = buildShadows(resolved.shadow, nodeId);
  const frameStroke = buildFrameStroke(resolved.frameStroke, nodeId);
  const strokeShadow = frameStroke === undefined ? undefined : frameStrokeToShadow(frameStroke);
  const hasPaintBackground = hasImageBackground || hasAffineGradientBackground;
  const backgroundBoxShadow = [strokeShadow, boxShadow]
    .filter((value): value is string => value !== undefined)
    .join(", ");
  // Affine/image fills are painted in a child layer so their transform and
  // per-paint blend survive the runtime. An inset shadow on the transparent
  // parent cannot affect that child; move the box-shadow to the same painted
  // layer in that case. Solid/legacy backgrounds stay on the frame itself.
  if (!hasPaintBackground && backgroundBoxShadow !== "") style.boxShadow = backgroundBoxShadow;
  if (shadowFilter !== undefined) style.filter = shadowFilter;

  const play = mountPlay(
    {
      opacity,
      ...(staticPlacement ? {} : { x, y }),
      scale,
      rotate,
      ...(flipY ? { scaleY: -1 } : {}),
    },
    animateInitial,
    nodeId,
  );
  // A motion frame without movement still instantiates Framer's visual
  // element. Plain DOM is equivalent only when its static box owns placement
  // and no transform channel has a non-identity authored value.
  const FrameElement = plain ? "div" : motion.div;

  return (
    <FrameElement
      style={style}
      {...(plain ? {} : { initial: play.initial, animate: play.animate, transition: toFramer(tx) })}
    >
      {hasPaintBackground && (
        <FrameBackgroundLayers
          fills={backgrounds}
          nodeId={nodeId}
          radius={radius}
          boxShadow={backgroundBoxShadow}
          blendedBoxShadows={blendedBoxShadows}
        />
      )}
      {!hasPaintBackground && blendedBoxShadows.length > 0 && (
        <ShadowOverlays radius={radius} shadows={blendedBoxShadows} />
      )}
      {children}
    </FrameElement>
  );
}

/**
 * Render image-containing frame backgrounds as explicit layers instead of a
 * single CSS `background-image` list. CSS has no per-layer opacity for a
 * background image, while Figma's ImagePaint opacity is part of the paint
 * itself. A positioned layer keeps that opacity local to the image and also
 * gives each fill its own blend context. Layers are emitted in reverse order
 * because the first Figma fill is the top-most paint.
 */
function FrameBackgroundLayers({
  fills,
  nodeId,
  radius,
  boxShadow,
  blendedBoxShadows,
}: {
  fills: Fill[];
  nodeId?: string;
  radius: number;
  boxShadow: string;
  blendedBoxShadows: ShadowLayer[];
}) {
  return (
    <div
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        ...(radius > 0 ? { borderRadius: radius, overflow: "hidden" } : {}),
      }}
    >
      {[...fills].reverse().map((fill, index) => {
        const affineGradient =
          fill.kind === "linear-gradient" &&
          Array.isArray(fill.transform) &&
          fill.transform.length === 6;
        if (affineGradient) {
          const rendered = renderFill(fill);
          const blend = parseBlendMode(rendered.mixBlendMode);
          return (
            <svg
              key={`background-layer-${fills.length - 1 - index}`}
              aria-hidden="true"
              viewBox="0 0 1 1"
              preserveAspectRatio="none"
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                pointerEvents: "none",
                ...(blend !== undefined
                  ? { mixBlendMode: blend as CSSProperties["mixBlendMode"] }
                  : {}),
              }}
            >
              <defs>{rendered.defs}</defs>
              <rect x="0" y="0" width="1" height="1" fill={rendered.ref} />
            </svg>
          );
        }
        const layerStyle: CSSProperties = {
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          ...backgroundsToCss([fill], nodeId),
        };
        if (
          fill.kind === "image" &&
          typeof fill.opacity === "number" &&
          Number.isFinite(fill.opacity) &&
          fill.opacity >= 0 &&
          fill.opacity <= 1
        ) {
          layerStyle.opacity = fill.opacity;
        }
        const blend = parseBlendMode(fill.blendMode);
        if (blend !== undefined) {
          layerStyle.mixBlendMode = blend as CSSProperties["mixBlendMode"];
        }
        return (
          <div
            key={`background-layer-${fills.length - 1 - index}`}
            aria-hidden="true"
            style={layerStyle}
          />
        );
      })}
      {boxShadow !== "" && (
        <div
          aria-hidden="true"
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            // Chromium paints an inset shadow underneath an element's
            // background and descendants. Keep it on a final, nearly
            // transparent overlay so it composites above affine SVG/image
            // fills instead of disappearing behind them.
            background: "rgba(255, 255, 255, 0.0001)",
            ...(radius > 0 ? { borderRadius: radius } : {}),
            boxShadow,
            zIndex: 1,
          }}
        />
      )}
      {blendedBoxShadows.length > 0 && (
        <ShadowOverlays radius={radius} shadows={blendedBoxShadows} />
      )}
    </div>
  );
}

function ShadowOverlays({ radius, shadows }: { radius: number; shadows: ShadowLayer[] }) {
  return (
    <>
      {shadows.map((shadow, index) => (
        <div
          key={`shadow-overlay-${index}`}
          aria-hidden="true"
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            background: "rgba(255, 255, 255, 0.0001)",
            ...(radius > 0 ? { borderRadius: radius } : {}),
            boxShadow: shadow.css,
            mixBlendMode: shadow.blendMode as CSSProperties["mixBlendMode"],
            zIndex: 2 + index,
          }}
        />
      ))}
    </>
  );
}

/**
 * Resolve `clipsContent` (LSML 1.1 §4.3, schema default `true`).
 *
 * The prop is wire-drivable (static bundle prop OR live LSDP delta via
 * `resolveProps`, tree.tsx), so a non-boolean is treated as hostile :
 * R9 diagnostic (value withheld) + fall back to the spec default
 * (`true`, i.e. clipped — the safe state for broadcast). The returned
 * value only ever selects between two literal style fragments — no
 * untrusted value can reach inline CSS through this path (RC#11 by
 * construction). Exported for boundary testing.
 */
export function resolveClipsContent(v: unknown, nodeId?: string): boolean {
  if (v === undefined) return true;
  if (typeof v === "boolean") return v;
  emitDiagnostic(nodeId, "frame.clipsContent", "rejected value : not a boolean");
  return true;
}

function numberOr(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

/** Build validated shadow CSS from the node's `shadow[]` (each entry:
 *  `{ inset?, color, x, y, blur, spread }`). Every colour goes through the
 *  strict `parseCssColor` gate (RC#11 : the value is wire-drivable) — a
 *  rejected colour drops that layer with a diagnostic, never reaches CSS.
 *  Geometry values are coerced to finite numbers.
 *
 *  Splits by kind :
 *   - INNER (inset) OR any shadow with a non-zero spread → `box-shadow`
 *     (inset rim / spread halo — both follow the element's own border box,
 *     which for the rotated rounded square IS the right silhouette).
 *   - no-spread DROP → `filter: drop-shadow`, cast from the element's rendered
 *     CONTENT (so a wrapper group's drop shadow tracks its rotated/rounded
 *     child instead of the wrapper's rectangular box). Chromium's
 *     drop-shadow sigma is calibrated at 2.16× against Figma's frame-shadow
 *     radius; box-shadow keeps the authored radius for inset/spread effects.
 *  Returns `{}` when nothing usable survives. */
type ShadowLayer = {
  css: string;
  blendMode: string;
};

function buildShadows(
  value: unknown,
  nodeId?: string,
): { filter?: string; boxShadow?: string; blendedBoxShadows: ShadowLayer[] } {
  if (!Array.isArray(value) || value.length === 0) return { blendedBoxShadows: [] };
  const dropParts: string[] = [];
  const boxParts: string[] = [];
  const blendedBoxShadows: ShadowLayer[] = [];
  for (const s of value) {
    if (typeof s !== "object" || s === null) continue;
    const spec = s as {
      inset?: unknown;
      color?: unknown;
      x?: unknown;
      y?: unknown;
      blur?: unknown;
      spread?: unknown;
      blendMode?: unknown;
    };
    const color = typeof spec.color === "string" ? parseCssColor(spec.color) : null;
    if (color === null) {
      warnRejectedColor("frame.shadow.color", nodeId);
      continue;
    }
    // R8 runtime gate (ADR 014 R2/R8) — ``shadow[]`` is wire-drivable (a
    // static bundle prop OR a live LSDP delta bypassing the compiler's
    // clamp), so re-validate and re-clamp here too. Non-finite falls back
    // to 0 (``clampFilterChannel``/``clampSymmetricChannel`` return
    // ``null`` on non-finite input) rather than reaching CSS unbounded.
    const inset = spec.inset === true;
    const x = clampSymmetricChannel("shadowOffset", numberOr(spec.x, 0)) ?? 0;
    const y = clampSymmetricChannel("shadowOffset", numberOr(spec.y, 0)) ?? 0;
    const blur = clampFilterChannel("blur", numberOr(spec.blur, 0)) ?? 0;
    const spread = clampSymmetricChannel("shadowSpread", numberOr(spec.spread, 0)) ?? 0;
    if (!inset && spread === 0) {
      dropParts.push(`drop-shadow(${x}px ${y}px ${blur / 2.16}px ${color})`);
    } else {
      const insetKw = inset ? "inset " : "";
      // Figma effects are composited in declaration order; CSS paints the
      // first shadow over later shadows, so prepend to preserve the authored
      // top-to-bottom order at the visual surface.
      const css = `${insetKw}${x}px ${y}px ${blur}px ${spread}px ${color}`;
      const blendMode = parseBlendMode(spec.blendMode) ?? "normal";
      if (blendMode !== "normal") {
        blendedBoxShadows.unshift({ css, blendMode });
      } else {
        boxParts.unshift(css);
      }
    }
  }
  const out: { filter?: string; boxShadow?: string; blendedBoxShadows: ShadowLayer[] } = {
    blendedBoxShadows,
  };
  if (dropParts.length > 0) out.filter = dropParts.join(" ");
  if (boxParts.length > 0) out.boxShadow = boxParts.join(", ");
  return out;
}

type FrameStroke = {
  color: string;
  width: number;
  align: "INSIDE" | "OUTSIDE" | "CENTER";
};

function buildFrameStroke(value: unknown, nodeId?: string): FrameStroke | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
  const raw = value as Record<string, unknown>;
  if (typeof raw.color !== "string") {
    emitDiagnostic(nodeId, "frame.frameStroke", "rejected value : color is not a string");
    return undefined;
  }
  const color = parseCssColor(raw.color);
  if (color === null) {
    warnRejectedColor("frame.frameStroke.color", nodeId);
    return undefined;
  }
  if (
    typeof raw.width !== "number" ||
    !Number.isFinite(raw.width) ||
    raw.width < 0 ||
    raw.width > 64
  ) {
    emitDiagnostic(
      nodeId,
      "frame.frameStroke",
      "rejected value : width is outside the bounded range",
    );
    return undefined;
  }
  if (raw.align !== "INSIDE" && raw.align !== "OUTSIDE" && raw.align !== "CENTER") {
    emitDiagnostic(nodeId, "frame.frameStroke", "rejected value : align is not supported");
    return undefined;
  }
  if (raw.width === 0) return undefined;
  return { color, width: raw.width, align: raw.align };
}

function frameStrokeToShadow(stroke: FrameStroke): string {
  if (stroke.align === "INSIDE") return `inset 0 0 0 ${stroke.width}px ${stroke.color}`;
  const width = stroke.align === "CENTER" ? stroke.width / 2 : stroke.width;
  return `0 0 0 ${width}px ${stroke.color}`;
}

function sizeProp(v: unknown): number | string | undefined {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string" && v.length > 0) return v;
  return undefined;
}
