// Typed shape-geometry builder (ADR 002 §3.2 Amendment 2 / A2.1 #K).
//
// A single source of truth for turning a `shape` RenderNode's typed geometry
// props (`geometry`/`kind`, `width`, `height`, `radius`, path `d`) into SVG
// outline elements — built ELEMENT-BY-ELEMENT with React, never from a markup
// string. Two call-sites consume it :
//
//   1. the `shape` primitive, which paints the outline with its fills/strokes ;
//   2. `buildMask` (#K), which inlines the RESOLVED geometry of a referenced
//      shape into a `<mask>` as coverage paint (white) — replacing the former
//      `<use href="#id">` that relied on a sibling being defs-resolvable.
//
// ── Security / structural contract ───────────────────────────────────
//  - T3 — zero arbitrary SVG markup. Every element here is a constructed
//    React node ; no raw-HTML React escape hatch is ever used on this path.
//    A path `d` still flows through `validatePathData` (svg-path.ts).
//  - Anti-cycle (A2.1, Bastion condition) — this builder reads ONLY the
//    node's own geometry props. It never reads `node.mask`, never descends
//    into `node.children`, and never re-enters the mask builder. Resolving a
//    `mask.source.ref` to a shape therefore inlines that shape's geometry and
//    NOTHING else : a `mask → shape (that itself carries a mask) → …` chain is
//    structurally cut at depth 1, so no unbounded recursion / DoS is possible.

import type { CSSProperties, ReactElement } from "react";
import type { RenderNode } from "./bundle";
import { parseShapePaths, type SubPath } from "./svg-path";
import { emitDiagnostic } from "./diagnostics";
import { parseFills, renderFill } from "./fill";
import { gateSrc, type HostAssetPolicy } from "./allowed-hosts";

/** The geometry kind, read from `geometry` (compiler) or `kind` (legacy). */
function geometryKind(props: Record<string, unknown>): string {
  return (props.geometry as string | undefined) ?? (props.kind as string | undefined) ?? "rect";
}

function numberOr(v: unknown, fallback: number): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

interface CornerRadii {
  topLeft: number;
  topRight: number;
  bottomRight: number;
  bottomLeft: number;
}

function readCornerRadii(value: unknown): CornerRadii | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
  const candidate = value as Record<string, unknown>;
  const values = [
    candidate.topLeft,
    candidate.topRight,
    candidate.bottomRight,
    candidate.bottomLeft,
  ];
  if (!values.every((item) => typeof item === "number" && Number.isFinite(item) && item >= 0)) {
    return null;
  }
  return {
    topLeft: values[0] as number,
    topRight: values[1] as number,
    bottomRight: values[2] as number,
    bottomLeft: values[3] as number,
  };
}

/** Normalize SVG corner radii using the same pair-sum constraint as CSS/Figma.
 *  Figma can author a 12px corner on an 8px-high underline; its visible
 *  quarter-circle is consequently capped to 4px. */
function normalizeCornerRadii(width: number, height: number, radii: CornerRadii): CornerRadii {
  const maxRadius = Math.min(width, height) / 2;
  const capped: CornerRadii = {
    topLeft: Math.min(radii.topLeft, maxRadius),
    topRight: Math.min(radii.topRight, maxRadius),
    bottomRight: Math.min(radii.bottomRight, maxRadius),
    bottomLeft: Math.min(radii.bottomLeft, maxRadius),
  };
  const pairSums = [
    capped.topLeft + capped.topRight,
    capped.bottomLeft + capped.bottomRight,
    capped.topLeft + capped.bottomLeft,
    capped.topRight + capped.bottomRight,
  ];
  const scale = Math.min(
    1,
    ...pairSums.map((sum, index) => {
      if (sum <= 0) return 1;
      return (index < 2 ? width : height) / sum;
    }),
  );
  return {
    topLeft: capped.topLeft * scale,
    topRight: capped.topRight * scale,
    bottomRight: capped.bottomRight * scale,
    bottomLeft: capped.bottomLeft * scale,
  };
}

function roundedRectPath(
  x: number,
  y: number,
  width: number,
  height: number,
  radii: CornerRadii,
): string {
  const right = x + width;
  const bottom = y + height;
  const topRight =
    radii.topRight > 0
      ? `A ${radii.topRight} ${radii.topRight} 0 0 1 ${right} ${y + radii.topRight}`
      : `L ${right} ${y}`;
  const bottomRight =
    radii.bottomRight > 0
      ? `A ${radii.bottomRight} ${radii.bottomRight} 0 0 1 ${right - radii.bottomRight} ${bottom}`
      : `L ${right} ${bottom}`;
  const bottomLeft =
    radii.bottomLeft > 0
      ? `A ${radii.bottomLeft} ${radii.bottomLeft} 0 0 1 ${x} ${bottom - radii.bottomLeft}`
      : `L ${x} ${bottom}`;
  const topLeft =
    radii.topLeft > 0
      ? `A ${radii.topLeft} ${radii.topLeft} 0 0 1 ${x + radii.topLeft} ${y}`
      : `L ${x} ${y}`;
  return [
    `M ${x + radii.topLeft} ${y}`,
    `H ${right - radii.topRight}`,
    topRight,
    `V ${bottom - radii.bottomRight}`,
    bottomRight,
    `H ${x + radii.bottomLeft}`,
    bottomLeft,
    `V ${y + radii.topLeft}`,
    topLeft,
    "Z",
  ].join(" ");
}

/**
 * Build the outline of a `shape` node as SVG elements painted with the given
 * `fill` and `stroke`. Used by the `shape` primitive (per-fill layering) and,
 * with a fixed coverage paint, by the mask builder (#K).
 *
 * Integration #L — `paint.mixBlendMode` carries a per-fill `mix-blend-mode`
 * that has ALREADY been revalidated against the closed enum by `renderFill`
 * (double-gate T4). It is applied as an inline `style` on the painted layer's
 * SVG element. It is `undefined` for stroke passes and ALWAYS `undefined` for
 * mask coverage (`buildMaskCoverageFromShape` never sets it) — a mask is a
 * coverage stencil, never a colour/blend reproduction (#K hypothesis 2). No
 * value other than an enum-validated keyword can reach this style key.
 *
 * `nodeId` is for path-validation diagnostics only (never a value, R9).
 */
export function buildShapeOutline(
  props: Record<string, unknown>,
  paint: {
    fill: string;
    stroke?: string;
    strokeWidth?: number;
    strokeAlign?: "INSIDE" | "OUTSIDE" | "CENTER";
    mixBlendMode?: string;
    filter?: string;
  },
  nodeId: string | undefined,
  keyPrefix = "geom",
): ReactElement {
  const kind = geometryKind(props);
  const width = numberOr(props.width, 100);
  const height = numberOr(props.height, 100);
  const radius = numberOr(props.radius, 0);
  const stroke = paint.stroke ?? "none";
  const strokeWidth = paint.strokeWidth ?? 0;
  const strokeAlign = paint.strokeAlign ?? "CENTER";
  // Figma clamps a uniform corner radius against the shortest side before it
  // emits the rounded-rectangle path.  Passing the raw authoring value to an
  // SVG <rect> lets the browser resolve oversized radii as an ellipse, which
  // changes pills into ovals when the imported corner token is larger than
  // half the button height.
  const innerWidth = Math.max(0, width - strokeWidth);
  const innerHeight = Math.max(0, height - strokeWidth);
  const normalizedRadius = Math.min(
    Math.max(0, radius - strokeWidth / 2),
    innerWidth / 2,
    innerHeight / 2,
  );
  // Figma exports an oversized uniform radius as an explicit capsule path
  // (the imported token may be 100+px on a 33px-high button).  Chromium's
  // `<rect rx>` and Figma's cubic capsule path have the same nominal bounds,
  // but they do not share identical edge coverage after rasterisation.  Keep
  // ordinary rectangles on the compact `<rect>` path; for this generic
  // normalized-radius case, emit the same closed outline as the authored
  // fillGeometry so masks and visible paint consume one geometry.
  const uniformRadiusWasClamped = radius > Math.min(width, height) / 2;
  // Figma's flattened zero-height path strokes are already closed, thin
  // outlined dash geometry. Painting that outline a second time as an SVG
  // stroke makes the line heavier and shifts its coverage; use the authored
  // paint as the fill for this degenerate geometry instead.
  const zeroHeightPathFill =
    kind === "path" &&
    height === 0 &&
    stroke !== "none" &&
    (paint.fill === "none" || paint.fill === "transparent")
      ? stroke
      : paint.fill;
  const zeroHeightPathStroke =
    zeroHeightPathFill === stroke && paint.fill !== stroke ? "none" : stroke;
  // #L — only an enum-revalidated keyword reaches here ; absent → no style key
  // (layer blends `normal`, rétro-compat). Mask coverage never passes one.
  const style: CSSProperties | undefined =
    paint.mixBlendMode !== undefined || paint.filter !== undefined
      ? ({
          ...(paint.mixBlendMode === undefined ? {} : { mixBlendMode: paint.mixBlendMode }),
          ...(paint.filter === undefined ? {} : { filter: paint.filter }),
        } as CSSProperties)
      : undefined;

  if (kind === "path") {
    const subpaths = parseShapePaths(props, nodeId);
    const strokeGeometry =
      stroke !== "none" && strokeWidth > 0 ? parseStrokeGeometry(props, nodeId) : [];
    const hasAuthoredStrokeGeometry = strokeGeometry.length > 0;
    const clipId =
      stroke !== "none" && strokeWidth > 0 && strokeAlign === "INSIDE"
        ? strokeClipId(
            nodeId,
            keyPrefix,
            `path:${width}:${height}:${subpaths.map((subpath) => `${subpath.d}:${subpath.fillRule}`).join("|")}`,
          )
        : undefined;
    return (
      <g key={keyPrefix} style={style}>
        {clipId !== undefined && (
          <defs>
            <clipPath id={clipId}>
              {subpaths.map((p: SubPath, i: number) => (
                <path key={i} d={p.d} fill="white" fillRule={p.fillRule} />
              ))}
            </clipPath>
          </defs>
        )}
        {hasAuthoredStrokeGeometry ? (
          <>
            {paint.fill !== "none" &&
              subpaths.map((p: SubPath, i: number) => (
                <path key={`fill-${i}`} d={p.d} fillRule={p.fillRule} fill={paint.fill} />
              ))}
            {strokeGeometry.map((p: SubPath, i: number) => (
              <path
                key={`stroke-outline-${i}`}
                d={p.d}
                fillRule={p.fillRule}
                fill={stroke}
                {...(clipId !== undefined ? { clipPath: `url(#${clipId})` } : {})}
              />
            ))}
          </>
        ) : (
          subpaths.map((p: SubPath, i: number) => (
            <path
              key={i}
              d={p.d}
              fillRule={p.fillRule}
              fill={zeroHeightPathFill}
              stroke={zeroHeightPathStroke}
              // SVG has no portable stroke-alignment property.  For an
              // INSIDE stroke the centreline is still on the authored path;
              // clipping a normal-width stroke would therefore retain only its
              // inner half.  Doubling the width before the inside clip leaves
              // one full authored width inside the path boundary.
              strokeWidth={
                zeroHeightPathStroke === "none"
                  ? 0
                  : clipId !== undefined
                    ? strokeWidth * 2
                    : strokeWidth
              }
              {...(clipId !== undefined ? { clipPath: `url(#${clipId})` } : {})}
            />
          ))
        )}
      </g>
    );
  }
  if (kind === "circle") {
    const strokeGeometry =
      stroke !== "none" && strokeWidth > 0 ? parseStrokeGeometry(props, nodeId) : [];
    if (strokeGeometry.length > 0) {
      const clipId =
        strokeAlign === "INSIDE"
          ? strokeClipId(nodeId, keyPrefix, `circle:${width}:${height}`)
          : undefined;
      return (
        <g key={keyPrefix} style={style}>
          {clipId !== undefined && (
            <defs>
              <clipPath id={clipId}>
                <ellipse
                  cx={width / 2}
                  cy={height / 2}
                  rx={width / 2}
                  ry={height / 2}
                  fill="white"
                />
              </clipPath>
            </defs>
          )}
          {strokeGeometry.map((p: SubPath, i: number) => (
            <path
              key={`stroke-outline-${i}`}
              d={p.d}
              fillRule={p.fillRule}
              fill={stroke}
              {...(clipId !== undefined ? { clipPath: `url(#${clipId})` } : {})}
            />
          ))}
        </g>
      );
    }
    // A Figma ELLIPSE node lowers to `circle`, but its box is often NON-square
    // (the bg-shine glows are 699×428, 955×586…). Render an <ellipse> with the
    // per-axis radii so the shape keeps its real size — a circle (w===h) is the
    // degenerate case. Rendering a `min(w,h)` circle shrank the glows → the warm
    // wash came out too dark and the wrong shape.
    const radiusX =
      strokeAlign === "INSIDE"
        ? width / 2 - strokeWidth / 2
        : strokeAlign === "OUTSIDE"
          ? width / 2 + strokeWidth / 2
          : width / 2;
    const radiusY =
      strokeAlign === "INSIDE"
        ? height / 2 - strokeWidth / 2
        : strokeAlign === "OUTSIDE"
          ? height / 2 + strokeWidth / 2
          : height / 2;
    return (
      <ellipse
        key={keyPrefix}
        style={style}
        cx={width / 2}
        cy={height / 2}
        rx={Math.max(0, radiusX)}
        ry={Math.max(0, radiusY)}
        fill={paint.fill}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    );
  }
  if (kind === "line") {
    return (
      <line
        key={keyPrefix}
        style={style}
        x1="0"
        y1={height / 2}
        x2={width}
        y2={height / 2}
        stroke={stroke !== "none" ? stroke : paint.fill}
        strokeWidth={strokeWidth || 1}
      />
    );
  }
  // rect default
  // Figma's imported rectangular strokes are INSIDE the authored outline.
  // The path is inset by half the stroke width above, so the centreline radius
  // must be inset by the same amount to keep the outer corner at `radius`.
  const inset = strokeWidth / 2;
  const sourceRadii = readCornerRadii(props.cornerRadii);
  if (sourceRadii) {
    const inset = strokeWidth / 2;
    const innerWidth = Math.max(0, width - strokeWidth);
    const innerHeight = Math.max(0, height - strokeWidth);
    const innerRadii = normalizeCornerRadii(innerWidth, innerHeight, {
      topLeft: Math.max(0, sourceRadii.topLeft - inset),
      topRight: Math.max(0, sourceRadii.topRight - inset),
      bottomRight: Math.max(0, sourceRadii.bottomRight - inset),
      bottomLeft: Math.max(0, sourceRadii.bottomLeft - inset),
    });
    return (
      <path
        key={keyPrefix}
        style={style}
        d={roundedRectPath(inset, inset, innerWidth, innerHeight, innerRadii)}
        fill={paint.fill}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    );
  }
  if (uniformRadiusWasClamped) {
    return (
      <path
        key={keyPrefix}
        style={style}
        d={roundedRectPath(inset, inset, innerWidth, innerHeight, {
          topLeft: normalizedRadius,
          topRight: normalizedRadius,
          bottomRight: normalizedRadius,
          bottomLeft: normalizedRadius,
        })}
        fill={paint.fill}
        stroke={stroke}
        strokeWidth={strokeWidth}
      />
    );
  }
  return (
    <rect
      key={keyPrefix}
      style={style}
      x={strokeWidth / 2}
      y={strokeWidth / 2}
      width={innerWidth}
      height={innerHeight}
      rx={normalizedRadius}
      ry={normalizedRadius}
      fill={paint.fill}
      stroke={stroke}
      strokeWidth={strokeWidth}
    />
  );
}

/**
 * Resolve the optional Figma stroke outline lowered by the compiler.  The
 * field is intentionally generic: it is authored vector geometry, not a
 * scene selector.  The same runtime path handles any imported vector whose
 * source format supplies an outline for a non-centred stroke.
 */
function parseStrokeGeometry(props: Record<string, unknown>, nodeId?: string): SubPath[] {
  const raw = props.stroke_geometry;
  if (!Array.isArray(raw)) return [];
  return parseShapePaths({ paths: raw }, nodeId);
}

/**
 * SVG paint/filter references are document-global even when the definitions
 * sit in separate nested SVGs. Imported bundles may omit node ids, so a
 * literal `anonymous` id would make unrelated shapes resolve each other's
 * clip paths. Hash the local geometry into the id; identical local geometry
 * can safely share a definition, while different boxes/paths cannot collide.
 */
function strokeClipId(nodeId: string | undefined, keyPrefix: string, signature: string): string {
  const seed = `${nodeId ?? "anonymous"}:${keyPrefix}:${signature}`;
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `lumen-stroke-inside-${(hash >>> 0).toString(16)}`;
}

/**
 * Build a referenced shape's geometry as mask COVERAGE paint (#K).
 *
 * Resolves to a white-painted outline (the default mask luminance paint) of
 * the referenced `shape` node — inlined into the `<mask>`. Returns `null` when
 * the node is not a paintable shape (defensive : the index only stores shapes,
 * but a live delta could mutate one), so the caller omits the mask.
 *
 * Anti-cycle : reads only `node.props` geometry — never the node's own `mask`
 * or children (profondeur de résolution = 1, A2.1 invariant).
 */
export function buildMaskCoverageFromShape(
  node: RenderNode,
  nodeId: string | undefined,
  consumerProps?: Record<string, unknown>,
): ReactElement | null {
  if (node.kind !== "shape") return null;
  const props = node.props ?? {};
  const coverage = buildMaskCoveragePaint(
    props,
    nodeId,
    "mask-cover",
    useInteriorCoverageForBlurredPaint(node, consumerProps),
  );
  return applyMaskSourceOpacity(coverage, props, "mask-cover");
}

/**
 * A Figma mask source is hidden as a visual layer, but its authored opacity
 * still scales the alpha stencil it contributes to the consumer.  Keep that
 * factor in the inlined SVG coverage instead of applying it to the hidden
 * source (which is not mounted in the DOM).  `universal_opacity` is composed
 * here as well because direct/runtime bundles may carry the same authored
 * factor in either wire slot.
 */
function applyMaskSourceOpacity(
  coverage: ReactElement,
  props: Record<string, unknown>,
  keyPrefix: string,
): ReactElement {
  let opacity = 1;
  for (const key of ["opacity", "universal_opacity"] as const) {
    const value = props[key];
    if (typeof value === "number" && Number.isFinite(value)) {
      opacity *= Math.min(1, Math.max(0, value));
    }
  }
  return opacity === 1 ? (
    coverage
  ) : (
    <g key={`${keyPrefix}-opacity`} opacity={opacity}>
      {coverage}
    </g>
  );
}

/**
 * Reproduce the authored paint of a shape used as an alpha mask.
 *
 * Figma outline masks are commonly stroke-only (`fill` absent, `stroke`
 * present). Treating those as an opaque white rectangle makes every masked
 * glow paint the whole card instead of only its outline. Typed colour and
 * gradient fills are retained as coverage ramps; legacy scalar `fill` and
 * `stroke` props are retained for the same reason. A genuinely paintless
 * source keeps the historical white geometry fallback.
 */
function buildMaskCoveragePaint(
  props: Record<string, unknown>,
  nodeId: string | undefined,
  keyPrefix: string,
  preferInteriorCoverage = false,
): ReactElement {
  const [sourceFill] = parseFills(props.fills, "mask.source.fills", nodeId);
  const stroke = props.stroke;
  const strokeColor =
    typeof stroke === "string"
      ? stroke
      : typeof stroke === "object" &&
          stroke !== null &&
          typeof (stroke as { color?: unknown }).color === "string"
        ? (stroke as { color: string }).color
        : undefined;
  const strokeWidth =
    typeof props.stroke_width === "number" && Number.isFinite(props.stroke_width)
      ? props.stroke_width
      : typeof stroke === "object" &&
          stroke !== null &&
          typeof (stroke as { width?: unknown }).width === "number" &&
          Number.isFinite((stroke as { width: number }).width)
        ? (stroke as { width: number }).width
        : undefined;
  const strokeAlign =
    props.stroke_align === "INSIDE" ||
    props.stroke_align === "OUTSIDE" ||
    props.stroke_align === "CENTER"
      ? props.stroke_align
      : typeof stroke === "object" &&
          stroke !== null &&
          ((stroke as { align?: unknown }).align === "INSIDE" ||
            (stroke as { align?: unknown }).align === "OUTSIDE" ||
            (stroke as { align?: unknown }).align === "CENTER")
        ? (stroke as { align: "INSIDE" | "OUTSIDE" | "CENTER" }).align
        : undefined;
  const paintStroke =
    strokeColor !== undefined ? { stroke: strokeColor, strokeWidth, strokeAlign } : {};

  // Figma's exporter represents some blurred interior glows with the same
  // 2px INSIDE outline that also drives the visible card border.  A literal
  // alpha mask would keep only that hairline after the blur and lose the glow
  // completely.  For this narrow, geometry-derived case the authored paint is
  // an interior coverage stencil: keep the source's rounded geometry filled,
  // while crisp/edge glows continue to use the stroke-only path below.
  if (preferInteriorCoverage && strokeColor !== undefined) {
    return buildShapeOutline(props, { fill: "white" }, nodeId, keyPrefix);
  }

  // An authored typed paint is the highest-fidelity coverage source. Image
  // paints cannot be used as a mask without reintroducing an untrusted image
  // surface, so they fall through to the safe scalar/white paths below.
  if (sourceFill !== undefined && sourceFill.kind !== "image") {
    const rendered = renderFill(sourceFill);
    return (
      <g key={`${keyPrefix}-painted`}>
        {rendered.defs.length > 0 && <defs>{rendered.defs}</defs>}
        {buildShapeOutline(props, { fill: rendered.ref, ...paintStroke }, nodeId, keyPrefix)}
      </g>
    );
  }

  const legacyFill = typeof props.fill === "string" ? props.fill : undefined;
  if (legacyFill !== undefined) {
    return buildShapeOutline(props, { fill: legacyFill, ...paintStroke }, nodeId, keyPrefix);
  }
  if (strokeColor !== undefined) {
    return buildShapeOutline(props, { fill: "none", ...paintStroke }, nodeId, keyPrefix);
  }

  // White coverage : a shape without a usable colour/stroke paint remains a
  // geometry-only stencil (A2.1 : inline the geometry, never the source mask).
  return buildShapeOutline(props, { fill: "white" }, nodeId, keyPrefix);
}

/**
 * Decide whether a shape mask is the Figma-exported stencil for an interior
 * blurred paint.  This intentionally uses only authored geometry/effects:
 * there are no scene names, node ids, or bundle-specific coordinates.
 *
 * Some exports place a blurred paint inside a source box while retaining an
 * INSIDE outline as the source geometry.  The consumer's local origin and
 * blend mode distinguish that interior pass from a crisp edge highlight;
 * small/edge-positioned glows keep the ordinary stroke mask.  The classifier
 * remains relative to the authored source box and never depends on scene
 * identity.
 */
function useInteriorCoverageForBlurredPaint(
  node: RenderNode,
  consumerProps: Record<string, unknown> | undefined,
): boolean {
  if (!consumerProps || node.kind !== "shape") return false;
  const sourceProps = node.props ?? {};
  const geometry = sourceProps.geometry ?? sourceProps.kind;
  if (geometry !== "rect") return false;

  const figma = (node as RenderNode & { metadata?: unknown }).metadata as
    | { figma?: unknown }
    | undefined;
  const figmaDetails =
    typeof figma === "object" && figma !== null
      ? (figma as { strokeDetails?: unknown; isMask?: unknown }).strokeDetails
      : undefined;
  const metadataStrokeAlign =
    typeof figmaDetails === "object" && figmaDetails !== null
      ? (figmaDetails as { strokeAlign?: unknown }).strokeAlign
      : undefined;
  const strokeAlign = sourceProps.stroke_align ?? metadataStrokeAlign;
  if (strokeAlign !== "INSIDE") return false;

  const stroke = sourceProps.stroke;
  const hasStroke =
    typeof stroke === "string" ||
    (typeof stroke === "object" &&
      stroke !== null &&
      typeof (stroke as { color?: unknown }).color === "string");
  const hasFill =
    typeof sourceProps.fill === "string" ||
    (Array.isArray(sourceProps.fills) && sourceProps.fills.length > 0);
  if (!hasStroke || hasFill || numberOr(consumerProps.blur, 0) <= 0) return false;

  // LIGHTEN is an edge-highlight blend in this export shape; retain the
  // outline stencil for it while normal/additive blurred paints can use the
  // interior coverage when their authored origin is inset.
  if (consumerProps.blendMode === "lighten") return false;

  const sourceWidth = numberOr(sourceProps.width, 0);
  const sourceHeight = numberOr(sourceProps.height, 0);
  const consumerX = numberOr(consumerProps.x, 0);
  const consumerY = numberOr(consumerProps.y, 0);
  if (sourceWidth <= 0 || sourceHeight <= 0) return false;
  return consumerX >= sourceWidth * 0.7 && consumerY < sourceHeight * 0.8;
}

/** Resolve bound properties for an image that crosses into a group-mask
 *  coverage stencil. The normal Tree has the store/scope needed to resolve a
 *  `bind.src`; keeping that seam optional preserves the pure geometry tests
 *  and makes an unresolved image an omission, never a guessed URL. */
export type MaskImagePropsResolver = (node: RenderNode) => Record<string, unknown>;

let maskImagePatternSeq = 0;

function nextMaskImagePatternId(): string {
  maskImagePatternSeq = (maskImagePatternSeq + 1) % 1_000_000;
  return `lumen-mask-img-${maskImagePatternSeq.toString(36)}`;
}

function imagePreserveAspectRatio(value: unknown): string {
  switch (value) {
    case "cover":
      return "xMidYMid slice";
    case "fill":
      return "none";
    case "none":
      return "xMidYMid meet";
    case "scale-down":
      return "xMidYMid meet";
    case "contain":
    default:
      return "xMidYMid meet";
  }
}

function imagePaintMetadata(node: RenderNode): Record<string, unknown> | undefined {
  const metadata = (node as RenderNode & { metadata?: unknown }).metadata;
  if (typeof metadata !== "object" || metadata === null) return undefined;
  const figma = (metadata as { figma?: unknown }).figma;
  if (typeof figma !== "object" || figma === null) return undefined;
  const imagePaint = (figma as { imagePaint?: unknown }).imagePaint;
  return typeof imagePaint === "object" && imagePaint !== null
    ? (imagePaint as Record<string, unknown>)
    : undefined;
}

function boundedPositive(value: unknown, fallback: number, max = 4096): number {
  const parsed = typeof value === "number" && Number.isFinite(value) ? value : fallback;
  return Math.min(max, Math.max(1, parsed));
}

/**
 * Inline an image child into an SVG alpha mask.
 *
 * Group masks are used by the Figma export for composed alpha sources, not
 * only for vector geometry. A tiled raster must keep its authored alpha
 * pattern; a regular `<image>` would stretch the tile over the whole frame.
 * Therefore TILE is represented by a bounded SVG pattern. Bundles that
 * provide an explicit `tileWidth`/`tileHeight` keep their own dimensions,
 * while the conservative fallback preserves the importer convention without
 * reading pixels or executing bundle markup.
 */
function buildMaskCoverageFromImage(
  node: RenderNode,
  props: Record<string, unknown>,
  nodeId: string | undefined,
  keyPrefix: string,
  allowedHosts: readonly string[] | undefined,
  isHostAssetUrl?: HostAssetPolicy,
): ReactElement | null {
  const src = gateSrc(props.src, allowedHosts, "mask.source.image.src", nodeId, isHostAssetUrl);
  if (!src) return null;
  const width = boundedPositive(props.width, 1);
  const height = boundedPositive(props.height, 1);
  const opacity =
    typeof props.opacity === "number" && Number.isFinite(props.opacity)
      ? Math.min(1, Math.max(0, props.opacity))
      : undefined;
  const rotation = numberOr(props.rotation, 0);
  const flipY = props.flipY === true;
  const paint = imagePaintMetadata(node);
  const rawScaleFactor = paint?.scalingFactor ?? props.imageScaleFactor;
  const scaleFactor =
    typeof rawScaleFactor === "number" && Number.isFinite(rawScaleFactor) && rawScaleFactor > 0
      ? Math.min(1, rawScaleFactor)
      : 1;
  const scaleMode = paint?.scaleMode ?? props.imageScaleMode;
  const isTile = scaleMode === "TILE";
  const preserveAspectRatio = imagePreserveAspectRatio(props.fit);
  const transformParts: string[] = [];
  if (flipY) transformParts.push(`translate(0 ${height}) scale(1 -1)`);
  if (rotation !== 0) transformParts.push(`rotate(${rotation} ${width / 2} ${height / 2})`);
  const transform = transformParts.length > 0 ? transformParts.join(" ") : undefined;

  let content: ReactElement;
  if (isTile) {
    const tileWidth = boundedPositive(paint?.tileWidth, 1200 * scaleFactor);
    const tileHeight = boundedPositive(paint?.tileHeight, 1200 * scaleFactor);
    const patternId = nextMaskImagePatternId();
    content = (
      <>
        <defs>
          <pattern
            id={patternId}
            patternUnits="userSpaceOnUse"
            width={tileWidth}
            height={tileHeight}
          >
            <image
              href={src}
              x={0}
              y={0}
              width={tileWidth}
              height={tileHeight}
              preserveAspectRatio="none"
              {...(opacity === undefined ? {} : { opacity })}
            />
          </pattern>
        </defs>
        <rect x={0} y={0} width={width} height={height} fill={`url(#${patternId})`} />
      </>
    );
  } else {
    content = (
      <image
        href={src}
        x={0}
        y={0}
        width={width}
        height={height}
        preserveAspectRatio={preserveAspectRatio}
        {...(opacity === undefined ? {} : { opacity })}
      />
    );
  }

  return (
    <g key={keyPrefix} {...(transform === undefined ? {} : { transform })}>
      {content}
    </g>
  );
}

/** Default cap on the number of direct children composited into a group mask
 *  (A4.4 budget T5). A container with more visible resolvable children is
 *  TRUNCATED at this count with a diagnostic — never an unbounded build. The
 *  real `817:2011` has 4 children ; the cap is generous yet bounded. */
export const GROUP_MASK_MAX_CHILDREN = 64;

/** Default cap on container-descent depth (A4.4 anti-cycle). `1` = a group's
 *  direct children may themselves be one level of sub-container ; below that a
 *  sub-container contributes nothing (diagnostic), so a `group → group → …`
 *  chain can never recurse without bound. We NEVER read a node's own `mask`
 *  during descent (a `mask → group → … → mask` cycle is structurally cut). */
export const GROUP_MASK_MAX_DEPTH = 1;

/** True iff a child node is excluded from the composite (`visible:false`).
 *  `visible` lives in the node's static props (compiler-flattened), mirroring
 *  the Tree's universal extraction (`resolved.visible`). */
function isHidden(node: RenderNode): boolean {
  return (node.props as { visible?: unknown } | undefined)?.visible === false;
}

function numProp(props: Record<string, unknown> | undefined, key: string): number {
  const v = props?.[key];
  return typeof v === "number" && Number.isFinite(v) ? v : 0;
}

/**
 * Composite the mask COVERAGE of a GROUP/FRAME container's VISIBLE children
 * into a single typed `<g>` (#O, ADR 002 A4.3/A4.4).
 *
 * The coverage is the **union** of the white outlines of every visible direct
 * child of geometry-resolvable kind — union being the native behaviour of
 * stacking white coverages in one `<mask>` (SVG alpha cumulates). Each child's
 * geometry is translated by its own `x`/`y` so the union lands in the
 * container's coordinate space.
 *
 * Invariants (A4.4) :
 *  - **visible-only** : `visible:false` children do not contribute.
 *  - **anti-cycle, depth = 1** : a direct child that is itself a container is
 *    descended at most `maxDepth` levels (default 1). We read ONLY geometry —
 *    never any node's own `mask` — so a `mask → group → … → mask` chain is
 *    structurally cut and no recursion through masks is possible.
 *  - **budget T5** : at most `maxChildren` direct children are composited ;
 *    beyond the cap the remainder is dropped with a static-reason diagnostic
 *    (R9 — never the id value), never an unbounded composite / freeze.
 *  - **omission, not crash** : a container with no visible resolvable child
 *    returns `null` so the caller omits the mask (no throw).
 *
 * @param nodeId    for diagnostics only (never a value, R9).
 * @param maxDepth  container-descent cap (default {@link GROUP_MASK_MAX_DEPTH}).
 * @param maxChildren  per-container child cap (default {@link GROUP_MASK_MAX_CHILDREN}).
 */
export function buildMaskCoverageFromGroup(
  node: RenderNode,
  nodeId: string | undefined,
  maxDepth: number = GROUP_MASK_MAX_DEPTH,
  maxChildren: number = GROUP_MASK_MAX_CHILDREN,
  includeHidden = false,
  resolveImageProps?: MaskImagePropsResolver,
  allowedHosts?: readonly string[],
  isHostAssetUrl?: HostAssetPolicy,
): ReactElement | null {
  if (node.kind !== "frame") return null;
  const parts = collectCoverage(
    node,
    nodeId,
    maxDepth,
    maxChildren,
    "grp",
    includeHidden,
    resolveImageProps,
    allowedHosts,
    isHostAssetUrl,
  );
  if (parts.length === 0) return null;
  const x = numProp(node.props, "x");
  const y = numProp(node.props, "y");
  return (
    <g
      key="mask-group-cover"
      {...(x !== 0 || y !== 0 ? { transform: `translate(${x} ${y})` } : {})}
    >
      {parts}
    </g>
  );
}

/** True when a group-mask source carries a LAYER_BLUR on any (depth-bounded)
 *  visible geometry child — the FEATHERED case (e.g. the bg-texture ellipse
 *  blurred 107.76) whose soft rim needs the wrapper feather pad (mask.tsx /
 *  tree.tsx). A sharp source returns false so the pad is skipped entirely — no
 *  extra wrapper, no structural change to ordinary masks. Mirrors the blur
 *  detection + descent bounds of `collectCoverage`. */
export function coverageIsFeathered(
  node: RenderNode,
  depth: number = GROUP_MASK_MAX_DEPTH,
  includeHidden = false,
): boolean {
  if (node.kind !== "frame") return false;
  for (const child of (node.children ?? []) as RenderNode[]) {
    if (!includeHidden && isHidden(child)) continue;
    if (numProp(child.props, "blur") > 0) return true;
    if (child.kind === "frame" && depth > 0 && coverageIsFeathered(child, depth - 1, includeHidden))
      return true;
  }
  return false;
}

/**
 * Return the radius of a mask group that is exactly one sharp, filled rounded
 * rectangle covering the group box.  Such a mask is a clipping primitive, not
 * a sampled paint: lowering it to `border-radius` + `overflow:hidden` keeps the
 * authored coverage while avoiding the isolated stacking context created by a
 * CSS `mask`.  That distinction matters when a masked child also carries a
 * valid `mix-blend-mode` and needs to blend with the scene backdrop.
 *
 * The predicate is deliberately structural.  It does not inspect product
 * names, ids, layer labels, or coordinates, and it declines non-uniform,
 * stroked, blurred, multi-child, or non-covering masks where border-radius
 * would not be equivalent to the authored stencil.
 */
export function simpleRoundedRectMaskRadius(node: RenderNode): number | null {
  if (node.kind !== "frame") return null;
  const containerProps = node.props ?? {};
  const containerWidth = numberOr(containerProps.width, 0);
  const containerHeight = numberOr(containerProps.height, 0);
  if (containerWidth <= 0 || containerHeight <= 0) return null;

  const children = (node.children ?? []).filter((child) => !isHidden(child));
  if (children.length !== 1) return null;
  const child = children[0];
  if (child?.kind !== "shape") return null;

  const props = child.props ?? {};
  if (geometryKind(props) !== "rect" || numberOr(props.blur, 0) > 0) return null;
  if (props.stroke !== undefined || (Array.isArray(props.strokes) && props.strokes.length > 0)) {
    return null;
  }

  const epsilon = 0.01;
  const x = numberOr(props.x, 0);
  const y = numberOr(props.y, 0);
  const width = numberOr(props.width, 0);
  const height = numberOr(props.height, 0);
  const radius = numberOr(props.radius, 0);
  if (
    width <= 0 ||
    height <= 0 ||
    Math.abs(x) > epsilon ||
    Math.abs(y) > epsilon ||
    Math.abs(width - containerWidth) > epsilon ||
    Math.abs(height - containerHeight) > epsilon ||
    radius <= 0
  ) {
    return null;
  }
  // CSS and SVG both accept radii larger than the box, but their normalization
  // rules differ from Figma's clamped rounded-rectangle geometry.  Return the
  // authored silhouette radius, bounded by the actual mask box.
  return Math.min(radius, containerWidth / 2, containerHeight / 2);
}

/** Recursive (depth-bounded) collector : returns the white coverage elements
 *  of `node`'s visible direct children, translating each by its own `x`/`y`.
 *  A child container is descended only while `depth > 0`. NEVER reads a node's
 *  `mask`. */
function collectCoverage(
  node: RenderNode,
  nodeId: string | undefined,
  depth: number,
  maxChildren: number,
  keyPrefix: string,
  includeHidden: boolean,
  resolveImageProps?: MaskImagePropsResolver,
  allowedHosts?: readonly string[],
  isHostAssetUrl?: HostAssetPolicy,
): ReactElement[] {
  const children = node.children ?? [];
  const out: ReactElement[] = [];
  let composited = 0;
  for (let i = 0; i < children.length; i++) {
    const child = children[i] as RenderNode;
    if (!includeHidden && isHidden(child)) continue;
    if (composited >= maxChildren) {
      emitDiagnostic(
        nodeId,
        "mask.source.ref",
        `group mask exceeds the ${maxChildren}-child composite cap ; remainder truncated (ADR 002 A4.4 T5)`,
      );
      break;
    }
    let part: ReactElement | null = null;
    if (child.kind === "shape") {
      const childProps = child.props ?? {};
      part = applyMaskSourceOpacity(
        buildMaskCoveragePaint(childProps, child.id, `${keyPrefix}-${i}`),
        childProps,
        `${keyPrefix}-${i}`,
      );
    } else if (child.kind === "image") {
      const imageProps = resolveImageProps?.(child) ?? child.props ?? {};
      part = buildMaskCoverageFromImage(
        child,
        imageProps,
        nodeId,
        `${keyPrefix}-${i}`,
        allowedHosts,
        isHostAssetUrl,
      );
    } else if (child.kind === "frame" && depth > 0) {
      // Bounded container descent (anti-cycle) — geometry only, never `mask`.
      const sub = collectCoverage(
        child,
        nodeId,
        depth - 1,
        maxChildren,
        `${keyPrefix}-${i}`,
        includeHidden,
        resolveImageProps,
        allowedHosts,
        isHostAssetUrl,
      );
      if (sub.length > 0) part = <g key={`${keyPrefix}-${i}`}>{sub}</g>;
    }
    // A non-geometry child (text/image/instance) or a too-deep sub-container
    // contributes nothing — the mask is a coverage stencil over geometry only.
    if (part === null) continue;
    // A LAYER_BLUR on the coverage shape FEATHERS the mask edge — the bg-texture
    // mask is a single ellipse blurred 107.76 (radius), so the WP tiles fade out
    // softly instead of being cut by a hard circular edge. Apply it via an SVG
    // `<feGaussianBlur>` (radius ≈ 2× the CSS sigma) with a WIDE filter region :
    // a plain CSS `filter:blur()` on an SVG element clips to the default
    // −10%..120% box, so the feathered ellipse re-appeared with a hard SQUARE
    // edge. The wide region (−120%..340%) lets the soft rim spread unclipped.
    const childBlur = numProp(child.props, "blur");
    if (childBlur > 0) {
      const bf = `lumen-mcov-blur-${nodeId ?? "x"}-${keyPrefix}-${i}`;
      part = (
        <g key={`${keyPrefix}-b-${i}`}>
          <filter id={bf} x="-120%" y="-120%" width="340%" height="340%">
            <feGaussianBlur stdDeviation={childBlur / 2} />
          </filter>
          <g filter={`url(#${bf})`}>{part}</g>
        </g>
      );
    }
    const x = numProp(child.props, "x");
    const y = numProp(child.props, "y");
    out.push(
      x !== 0 || y !== 0 ? (
        <g key={`${keyPrefix}-t-${i}`} transform={`translate(${x} ${y})`}>
          {part}
        </g>
      ) : (
        part
      ),
    );
    composited++;
  }
  return out;
}
